    [2853840596] = {
        ["english"] = { [1] = "First Aid may not make up for a priest's healing, but it's handy in a pinch.  I recommend ye go talk to Thamner in the Thunderbrew Distillery and learn what ye can." },
        ["text"] = "Перша допомога не замінить зцілення жерця, але в скрутну мить рятує. Раджу поговорити з Тамнером у винокурні Громовара й навчитися всього, що зможеш.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [3873680550] = {
        ["english"] = { [1] = "Heading to Outland? Visit Vixton Pinchwhistle in Netherstorm's Area 52. As the Steamwheedle Fighting Circuit's official Arena Vendor, he has all sorts of incredible items for sale to those with enough Arena Points." },
        ["text"] = "Прямуєш до Позамежжя? Завітай до Вікстона Пінчвістла в Зону 52 у Бурекраї. Як офіційний продавець арени Бойового Кола Паровиманки, він продає всілякі неймовірні речі тим, хто має достатньо очок арени.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2715294685] = {
        ["english"] = { [1] = "Hey, I recognize you! I guess I have you to thanks for me being here. That teleport accident was the best thing that ever happened to me.$B$BIf you find yourself back in Borean Tundra, let my goody two-shoes nerd of a duplicate know that I've move up in the world quite a bit!" },
        ["text"] = "Гей, я тебе впізнаю! Здається, завдяки тобі я тепер тут. Та аварія з телепортом — найкраще, що зі мною траплялося.$B$BЯкщо знову будеш у Борейській тундрі, передай моєму занудному правильному двійнику, що я неабияк піднявся у світі!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [837930098] = {
        ["english"] = { [1] = "Guild Master" },
        ["text"] = "Майстер гільдій",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 4262, [7] = 5595, [8] = 6272, [9] = 6740, [10] = 8931, [11] = 12996, [12] = 13076, [13] = 274781 },
        ["roles"] = { ["reply"] = true },
