    [1126230939] = {
        ["english"] = { [1] = "I believe Aldwin Laughlin is still the resident Guild Master of Stormwind.  Look for his residence on your left as you pass the inner gate of Stormwind." },
        ["text"] = "Гадаю, Олдвін Лафлін досі є майстром гільдій Штормовію. Шукай його оселю ліворуч, коли пройдеш внутрішню браму Штормовію.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [2254238822] = {
        ["english"] = { [1] = "Here you are, $n.$b$bNow please, return your focus to the task at hand...." },
        ["text"] = "Ось, тримай, $n.$b$bА тепер, будь ласка, знову зосередься на справі....",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
