    [3622277286] = {
        ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Silvermoon City.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Silvermoon City for your duty and service.", [2] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Silvermoon City.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Silvermoon City for your duty and service.\013\013\010" },
        ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Срібномісяць. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Орди.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Срібномісяця.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1576888018] = {
        ["english"] = { [1] = "FINE! And how, dare I ask, am I supposed to acquire an arcanite buoy?" },
        ["text"] = "ГАРАЗД! І як, дозволь запитати, я маю роздобути арканітовий буй?",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [463181679] = {
        ["english"] = { [1] = "Don't come out of the shadows like that. Next time give a girl some warning. " },
        ["text"] = "Не виринай так із тіней. Наступного разу попередь дівчину. ",
