    [205021494] = {
        ["english"] = { [1] = "Druids are very sensitive to the plight of all creatures of the world. When it was found that these birds were in danger, we set up a system of rescuing them from the corruption of Feralas.$B$BA gnome named Curgle Cranklehop leads the affair; she collects the eggs and has them sent here, where I care for them.$B$BWe could always use more help for our cause, $N. Maybe you should head over to Gadgetzan and look for Curgle." },
        ["text"] = "Друїди дуже чутливі до страждань усіх створінь світу. Коли з'ясувалося, що цим птахам загрожує небезпека, ми створили систему їхнього порятунку від скверни Фераласу.$B$BЦією справою керує гномка Керґл Кренклгоуп: вона збирає яйця й надсилає їх сюди, де я за ними доглядаю.$B$BНам завжди потрібна допомога, $N. Може, вам варто навідатися до Пристробляха й розшукати Керґл.",
        ["npcs"] = { [1] = 7916 },
        ["roles"] = { ["greeting"] = true },
    },
    [1281567362] = {
        ["english"] = { [1] = "Grimnur Stonebrand will tell ye some whoppers about the one that got away, but he's still one o' the best fishermen around.  He's got a shop set up in The Forlorn Cavern called the Traveling Fisherman." },
        ["text"] = "Ґрімнур Кам'яний Тавр розкаже тобі небилиць про ту рибину, що зірвалася, але він усе одно один із найкращих рибалок. У Закинутій печері в нього є крамниця «Мандрівний рибалка».",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [223965412] = {
        ["english"] = { [1] = "Hmm... well you seem capable enough. If you truly desire to learn, then nothing will stand in your way! I will guide you through your first steps on what I hope will be a long and fulfilling path." },
        ["text"] = "Гм... схоже, здібностей у тебе достатньо. Якщо справді хочеш учитися, ніщо тебе не зупинить! Я проведу тебе через перші кроки на шляху, який, сподіваюся, буде довгим і плідним.",
        ["npcs"] = { [1] = 11068 },
        ["roles"] = { ["greeting"] = true },
    },
    [2455838375] = {
