    [3899105209] = {
        ["english"] = { [1] = "Good to see you again, $N! Just a few more adjustments and the trajectory of the jump will be perfect!" },
        ["text"] = "Радий знову тебе бачити, $N! Ще кілька налаштувань — і траєкторія стрибка буде ідеальною!",
