    [2744412375] = {
        ["english"] = { [1] = "For the love of all that is holy and dear, please tell me that you've come to deliver us from this forsaken land.  Though I'm with Marshal Expeditions, I would give you the gold teeth from my mouth to climb inside your backpack and leave this place." },
        ["text"] = "Заради всього святого й дорогого, скажи, що ти прийшов визволити нас із цієї проклятої землі. Я з експедицією Маршалла, але віддав би золоті зуби з власного рота, аби залізти тобі в наплічник і забратися звідси.",
