    [879092597] = {
        ["english"] = { [1] = "Good ol' Thamner bandaged me up just the other day when I had a run in with a nasty trogg.  I'm good as new I tell ye!  I'm sure Thamner would be happy to show ye how to make a good bandage." },
        ["text"] = "Старий добрий Тамнер днями перев'язав мене після сутички з гидким троґґом. Я тепер як новенький, кажу тобі! Упевнений, Тамнер залюбки покаже, як робити добрі бинти.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2616919987] = {
        ["english"] = { [1] = "Frostwolf Keep lies in the south corner of Alterac Valley and protects Frostwolf Village, home of orc clan of the same name.  All Horde territories in Alterac Valley stem from this one place of power.$B$BFrostwolf Keep is intact." },
        ["text"] = "Форт Морозних Вовків лежить у південному куті Альтерацької долини й захищає селище Морозних Вовків — домівку однойменного орчого клану. Усі володіння Орди в Альтерацькій долині беруть початок від цього осередку сили.$B$BФорт Морозних Вовків неушкоджений.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3608579360] = {
        ["english"] = { [1] = "Hawkstriders are noble creatures.  Make sure to always treat yours well; there are fewer things more dangerous than an angry hawkstrider." },
        ["text"] = "Яструбобіги — шляхетні створіння. Завжди добре стався до свого: мало що небезпечніше за розлюченого яструбобіга.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1974815625] = {
        ["english"] = { [1] = "Does this dress make me look fat?" },
        ["text"] = "Ця сукня мене повнить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
