    [983792567] = {
        ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Darnassus.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Darnassus for your duty and service.\010", [2] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Darnassus.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Darnassus for your duty and service.\010\010" },
        ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Дарнас. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Альянсу.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Дарнаса.\010",
        ["npcs"] = { [1] = 15731, [2] = 15762 },
        ["roles"] = { ["greeting"] = true },
    },
    [2708495890] = {
        ["english"] = { [1] = "Doctor Herbert Halsey in The Apothecarium where us was born.  Him could sew you back together better like us." },
        ["text"] = "Доктор Герберт Голсі в Аптекаріумі, де нас народили. Він може зшити тебе докупи краще, як нас.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1424397648] = {
        ["english"] = { [1] = "Here in Darnassus you will find skilled trainers who have perfected the skills of their chosen class through ages of training and dedication.  I will guide you to one who can become your mentor, you have but to name your chosen path." },
        ["text"] = "Тут, у Дарнасі, ти знайдеш вправних наставників, які за довгі віки навчання й відданості довели майстерність свого класу до досконалості. Я проведу тебе до того, хто стане твоїм наставником — лише назви обраний шлях.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3725716031] = {
        ["english"] = { [1] = "Ey, mon! Take me to mah troll bruddas!" },
        ["text"] = "Йо, мон! Відведи мене до моїх тролячих братів!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1811305791] = {
        ["english"] = { [1] = "I bear witness to a miracle that stands before me! In one thousand years of captivity, I have not seen a single LIVING specimen - other than those foul Qiraji and silithid - enter these chambers." },
        ["text"] = "Я свідок дива, що стоїть переді мною! За тисячу років полону я не бачив жодного ЖИВОГО створіння — крім тих огидних кіражів і силітидів — яке б увійшло до цих залів.",
        ["npcs"] = { [1] = 15380 },
        ["roles"] = { ["greeting"] = true },
    },
    [2358624972] = {
        ["english"] = { [1] = "I be seeking someone, $c. Please, leave me be... it is important I find them." },
        ["text"] = "Я шукаю когось, $c. Будь ласка, залиш мене... мені дуже важливо їх знайти.",
        ["npcs"] = { [1] = 11407 },
        ["roles"] = { ["greeting"] = true },
    },
    [2682233441] = {
        ["english"] = { [1] = "Gosh, I'm sorry. I don't have anything new to teach you. How about you go talk to Simon Tanner in the Old Town section of Stormwind? He's a human with big muscles and dreamy red hair." },
        ["text"] = "Ой, вибач. Мені більше нічого нового тебе навчити. Може, поговориш із Саймоном Таннером у Старому місті Штормовію? Це людина з великими м'язами й розкішним рудим волоссям.",
        ["npcs"] = { [1] = 1632 },
        ["roles"] = { ["greeting"] = true },
    },
    [916519374] = {
        ["english"] = { [1] = "I be one of da first to answer Vol'jin's call to arms. Will you be joinin' us?" },
        ["text"] = "Я один із перших відповісти на заклик Вол'джина до зброї. Приєднаєшся до нас?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [553065873] = {
        ["english"] = { [1] = "I be a messenger from the Eastern Kingdoms, $N. I be sent here to make sure da priests who travel here be given proper direction." },
        ["text"] = "Я посланець зі Східних Королівств, $N. Мене прислати сюди, щоб жерці, які приходять, отримувати правильні вказівки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2745208301] = {
        ["english"] = { [1] = "Greetings, hero. I craft and sell Ahn'kahar Blood Hunter armor for hunters." },
        ["text"] = "Вітаю, герою. Я виготовляю й продаю мисливцям обладунки Кривавого мисливця Ан'кахара.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1815762675] = {
        ["english"] = { [1] = "Greetings.  I'm an undead mage trainer, and you're a mage." },
        ["text"] = "Вітаю. Я наставник магів-невмерлих, а ти маг.",
        ["npcs"] = { [1] = 2124, [2] = 2128, [3] = 3047, [4] = 3048, [5] = 3049, [6] = 4566, [7] = 4567, [8] = 4568 },
        ["roles"] = { ["greeting"] = true },
    },
    [1509434533] = {
        ["english"] = { [1] = "Documents such as guild creation papers can be acquired from the Guild Master in the city of Darnassus.  " },
        ["text"] = "Такі документи, як папери для створення гільдії, можна отримати в майстра гільдій у Дарнасі.  ",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [3206936285] = {
        ["english"] = { [1] = "Fengus make you fierce!  Crazed!  RAR!" },
        ["text"] = "Фенґус зробить тебе лютим! Несамовитим! РАААР!",
        ["npcs"] = { [1] = 14321 },
        ["roles"] = { ["greeting"] = true },
    },
    [327344736] = {
        ["english"] = { [1] = "Elder Skychaser looks out over Westfall from atop Sentinel Hill." },
        ["text"] = "Старійшина Небесний Ловець споглядає Західний край із Вартового пагорба.",
        ["npcs"] = { [1] = 15565, [2] = 15576, [3] = 15593 },
        ["roles"] = { ["greeting"] = true },
    },
    [103422313] = {
        ["english"] = { [1] = "How many bandages have the Horde collected so far?" },
        ["text"] = "Скільки бинтів уже зібрала Орда?",
        ["npcs"] = { [1] = 15539, [2] = 15700 },
        ["roles"] = { ["reply"] = true },
    },
    [2409492443] = {
        ["english"] = { [1] = "Elune-adore, my $gbrother:sister;. You are welcome here. Speak, and I will do what I can to aid you." },
        ["text"] = "Елуне-адоре, мій $g брате:сестро;. Тут тобі раді. Говори, і я допоможу чим зможу.",
        ["npcs"] = { [1] = 11041 },
        ["roles"] = { ["greeting"] = true },
    },
    [1092431156] = {
        ["english"] = { [1] = "I barely have any supplies for upgrades." },
        ["text"] = "У мене майже немає припасів для покращень.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1518779644] = {
        ["english"] = { [1] = "Have you come to seek the knowledge of Hgarth?" },
        ["text"] = "Ти прийшов по знання Гґарта?",
        ["npcs"] = { [1] = 11074 },
        ["roles"] = { ["greeting"] = true },
    },
    [1494843491] = {
        ["english"] = { [1] = "How you doin' mon!" },
        ["text"] = "Як ся маєш, мон!",
        ["npcs"] = { [1] = 7871 },
        ["roles"] = { ["greeting"] = true },
    },
    [3608765731] = {
        ["english"] = { [1] = "I appreciate the company, but let's face it: you have more experience with potions than I do. Talk to Doctor Marsh instead if you want training. He's a Forsaken in the Apothecarium of the Undercity." },
        ["text"] = "Я ціную товариство, але визнаймо: ти знаєш про зілля більше за мене. Якщо хочеш навчатися, поговори краще з доктором Маршем. Він Відречений і працює в Аптекаріумі Підміста.",
        ["npcs"] = { [1] = 2132 },
        ["roles"] = { ["greeting"] = true },
    },
    [1300797784] = {
        ["english"] = { [1] = "Dying for one's country is a soldier's duty.  But if calling this war folly is treason, then I'm a traitor." },
        ["text"] = "Померти за свою країну — обов'язок солдата. Але якщо називати цю війну безглуздям — зрада, тоді я зрадник.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [562830311] = {
        ["english"] = { [1] = "I am Zarevhi of the Consortium.  My skills as a transmuter are known in a thousand worlds." },
        ["text"] = "Я Заревгі з Консорціуму. Мою майстерність трансмутації знають у тисячі світів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1772326107] = {
        ["english"] = { [1] = "I AM FLUENT IN OVER TWO LANGUAGES: DWARVISH, GNOMISH AND THE VERY COMMON TONGUE OF HUMANS.  BUT I HAVE NO IDEA WHAT YOU ARE SAYING!$B$BSPEAK UP; I CANNOT HEAR YOU OVER THE GRINDING OF MY GEARS!" },
        ["text"] = "Я ВІЛЬНО ВОЛОДІЮ БІЛЬШ НІЖ ДВОМА МОВАМИ: ДВОРФІЙСЬКОЮ, ГНОМСЬКОЮ ТА ЗВИЧАЙНОЮ МОВОЮ ЛЮДЕЙ. АЛЕ Я НЕ МАЮ УЯВЛЕННЯ, ЩО ВИ КАЖЕТЕ!$B$BГОВОРІТЬ ГОЛОСНІШЕ; Я НЕ ЧУЮ ВАС ЧЕРЕЗ СКРЕГІТ МОЇХ ШЕСТЕРЕНЬ!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [356104345] = {
        ["english"] = { [1] = "Hello, dear. I am Geyah, matron of the Mag'har.$B$B<Greatmother Geyah coughs.>$B$BIf you are here, it would be safe to assume that the portal has opened. Most of the orcs here were too young or too sick to remember the Dark Portal.$B$B<Greatmother Geyah points to the orcs around her.>$B$BMany of them were orphans or would soon become orphans. Aye, Blackhand would have it no other way. Keep the sick from the healthy. Only the strong would survive... Or so they say." },
        ["text"] = "Привіт, любий. Я Ґея, матрона маґ'гарів.$B$B<Велика Матір Ґея кашляє.>$B$BЯкщо ти тут, можна припустити, що портал відкрився. Більшість орків тут були надто молодими або хворими, щоб пам'ятати Темний портал.$B$B<Велика Матір Ґея вказує на орків навколо.>$B$BБагато з них були сиротами або невдовзі мали ними стати. Так, Чорнорук не хотів інакше. Хворих відокремлювали від здорових. Вижити мали лише сильні... принаймні так казали.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [537235616] = {
        ["english"] = { [1] = "I am Zanza, a Loa of Zandalar. I have come in this ethereal form from Zandalar to help my people. Hakkar has no dominion over my soul.$B$BI help those that have helped the Zandalarian people." },
        ["text"] = "Я Занза, лоа Зандалара. Я прибув у цій ефірній формі із Зандалара, щоб допомогти своєму народові. Гаккар не має влади над моєю душею.$B$BЯ допомагаю тим, хто допоміг народу Зандалара.",
        ["npcs"] = { [1] = 930 },
        ["roles"] = { ["greeting"] = true },
    },
    [2067155831] = {
        ["english"] = { [1] = "I am unable to teach a Tauren to ride a Skeletal Mount.  I am sorry but there is nothing I can do for you." },
        ["text"] = "Я не можу навчити таурена їздити верхи на скелетному скакуні. Вибач, але нічим не можу допомогти.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4150637431] = {
        ["english"] = { [1] = "Elune has granted the night elves many gifts. In return, it is our responsibility to safeguard these forests from the demonic taint that the Horde always brings with it." },
        ["text"] = "Елуна дарувала нічним ельфам безліч дарів. Натомість наш обов'язок — захищати ці ліси від демонічної скверни, яку Орда завжди приносить із собою.",
        ["npcs"] = { [1] = 3967 },
        ["roles"] = { ["greeting"] = true },
    },
    [817120407] = {
        ["english"] = { [1] = "I am unable to process your chronological reference in comparison to the recording of this data, my apologies.$B$BThough the dwarf maintains most of the Earthen's mental attunement to Azeroth's stone composition, the reversion back into living biomass remains the main degeneration of the matrix.  Dwarves eat and procreate through means typical to other standard biomasses.$B$BThe Creators view the dwarf as an acceptable variant, worthy of genesis in its own right." },
        ["text"] = "Перепрошую, але я не можу обробити ваше хронологічне посилання у співвідношенні із записом цих даних.$B$BХоча дворф зберігає більшість ментального налаштування земельників на кам'яну структуру Азероту, повернення до живої біомаси лишається головною деградацією матриці. Дворфи харчуються й розмножуються способами, типовими для інших стандартних біомас.$B$BТворці вважають дворфа прийнятним варіантом, гідним окремого походження.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [967857885] = {
        ["english"] = { [1] = "Here to learn? Very well. I suppose you can't cause our allies much harm if I teach you. Just as long as you actually do manage to harm our enemies." },
        ["text"] = "Прийшов учитися? Гаразд. Гадаю, якщо я тебе навчу, нашим союзникам ти багато шкоди не завдаси. Головне — щоб ворогам таки завдав.",
        ["npcs"] = { [1] = 4609 },
        ["roles"] = { ["greeting"] = true },
    },
    [2967999307] = {
        ["english"] = { [1] = "Greetings, $c.$B$BWhen the Horde controls Wintergrasp Fortress, I will open a portal for those who wish to travel there.$B$BThe battle currently ensues. Hurry to Wintergrasp to support our forces." },
        ["text"] = "Вітаю, $c.$B$BКоли Орда контролює фортецю Зимохвату, я відкриваю портал для всіх, хто хоче туди вирушити.$B$BБитва вже триває. Поспішай до Зимохвату підтримати наші сили.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [147773471] = {
        ["english"] = { [1] = "How are we doing in the battle to subvert the cauldrons?" },
        ["text"] = "Як просувається наша боротьба за саботаж казанів?",
        ["npcs"] = { [1] = 11053, [2] = 11055 },
        ["roles"] = { ["reply"] = true },
    },
    [684870978] = {
        ["english"] = { [1] = "Greetings, Light of Elune be with you." },
        ["text"] = "Вітаю, нехай Світло Елуни буде з вами.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2391899961] = {
        ["english"] = { [1] = "Hey there, $c. I've talked with everyone around here, and it seems like we have all of the stuff that the Alliance wants for the war. That mean orc ambassador said that the Horde is still gathering though, which means we have some time before we need to ship all of this stuff over to Silithus." },
        ["text"] = "Привіт, $c. Я поговорив з усіма тут, і схоже, ми маємо все, що Альянс хотів для війни. Той злий орчий посол сказав, що Орда ще збирає своє, тож у нас є трохи часу, перш ніж усе це треба буде відправити до Силітусу.",
        ["npcs"] = { [1] = 15456 },
        ["roles"] = { ["greeting"] = true },
    },
    [1506331796] = {
        ["english"] = { [1] = "Hiya! This workshop isn't mine, no! But one day after I finish training I am going to be an inventor, just like my hero, Marvon Rivetseeker.$B$BYou've never heard of him? Well it just so happens that he left quite some time ago to study some ancient troll ruins he kept talking about. He left in a zeppelin... not quite sure about where exactly he went...$B$BTanarasin? Tenkeris? Taneranisany?$B$B<Liv shakes her head.>$B$BNo, that's not it..." },
        ["text"] = "Привіт! Ця майстерня не моя, ні! Але одного дня, коли завершиться моє навчання, я стану винахідником, як мій герой Марвон Заклепкошук.$B$BНіколи про нього не чув? Так от, він давно вирушив досліджувати якісь стародавні тролячі руїни, про які постійно говорив. Полетів на дирижаблі... тільки я не знаю, куди саме...$B$BТанарасін? Тенкеріс? Танеранісані?$B$B<Лів хитає головою.>$B$BНі, не те...",
        ["npcs"] = { [1] = 8496 },
        ["roles"] = { ["greeting"] = true },
    },
    [1743126746] = {
        ["english"] = { [1] = "I am told that the dust and heat of Hellfire Peninsula is quite irritating... I would not know, but I will trust my esteemed, and still living, allies." },
        ["text"] = "Кажуть, пил і спека Півострова Пекельного Вогню страшенно дратують... Я цього не знаю, але довірюся своїм шановним і досі живим союзникам.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2427068758] = {
        ["english"] = { [1] = "I am Tinkmaster Overspark, and I am the chief architect for modern gnomish engineering principles in the world today.  It is my job to ensure that the power of invention continues to shine brightest from our arclight spanners than anywhere else!$B$BAlso, if you happen to know a good schematic for radiation elimination, we just so happen to be in the market for one right about now..." },
        ["text"] = "Я майстер-винахідник Оверспарк, головний архітектор сучасних принципів гномської інженерії у світі. Моє завдання — стежити, щоб сила винахідництва сяяла з наших арклайтових гайкових ключів яскравіше, ніж будь-де!$B$BА ще, якщо вам раптом відома добра схема усунення радіації, то ми саме зараз дуже нею цікавимося...",
        ["npcs"] = { [1] = 7944 },
        ["roles"] = { ["greeting"] = true },
    },
    [3996298454] = {
        ["english"] = { [1] = "Greetings, $c.  I am Exzhal, Servitor of Rastakhan." },
        ["text"] = "Вітаю, $c. Я Екзгал, слуга Растахана.",
        ["npcs"] = { [1] = 14910 },
        ["roles"] = { ["greeting"] = true },
    },
    [2614163052] = {
        ["english"] = { [1] = "Duke of Fathoms! I hold your signet!  Heed my call!" },
        ["text"] = "Герцогу Глибин! Я тримаю твою печатку! Почуй мій поклик!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1906841416] = {
        ["english"] = { [1] = "Duke of Zephyrs! I hold your signet!  Heed my call!" },
        ["text"] = "Герцогу Зефірів! Я тримаю твою печатку! Почуй мій поклик!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [929890739] = {
        ["english"] = { [1] = "During your battles with the Scourge in Naxxramas, should you come across desecrated battlements and wartorn plate scraps, return them to me and I shall craft for you a piece of this armor worn by heroes." },
        ["text"] = "Під час боїв зі Скверною в Наксрамасі, якщо вам трапляться осквернені бастіони та пошматовані латні уламки, принесіть їх мені, і я викую для вас частину цих обладунків героїв.",
        ["npcs"] = { [1] = 16112 },
        ["roles"] = { ["greeting"] = true },
    },
    [2830088688] = {
        ["english"] = { [1] = "Greetings, $c.  I get so few visitors up here.  To what do I owe the pleasure?" },
        ["text"] = "Вітаю, $c. Тут у мене так мало відвідувачів. Чим завдячую честю?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1430068177] = {
        ["english"] = { [1] = "Duke of Shards! I hold your signet!  Heed my call!" },
        ["text"] = "Герцогу Осколків! Я тримаю твою печатку! Почуй мій поклик!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2801304408] = {
        ["english"] = { [1] = "How many metal bars have the Horde collected so far?" },
        ["text"] = "Скільки металевих зливків уже зібрала Орда?",
        ["npcs"] = { [1] = 15539, [2] = 15700 },
        ["roles"] = { ["reply"] = true },
    },
    [1341397608] = {
        ["english"] = { [1] = "How do the goblins ever manage to secure packs to these beasts?  Kodos are ten times the size!" },
        ["text"] = "Як гоблінам узагалі вдається прив'язувати в'юки до цих звірів? Кодо вдесятеро більші!",
        ["npcs"] = { [1] = 11627 },
        ["roles"] = { ["greeting"] = true },
    },
    [1058998601] = {
        ["english"] = { [1] = "I am the latest incarnation of automated vendors... we will rule the world one day... don't tell my boss that I am skimming money off his merchandise..." },
        ["text"] = "Я найновіше покоління автоматизованих торговців... одного дня ми правитимемо світом... тільки не кажи начальнику, що я відщипую собі трохи грошей із його товарів...",
        ["npcs"] = { [1] = 12246 },
        ["roles"] = { ["greeting"] = true },
    },
    [3964076072] = {
        ["english"] = { [1] = "I am sure that, with our help, Botanist Taerix will be able to find solutions to our problems." },
        ["text"] = "Я певен, що з нашою допомогою ботанік Таерікс зможе знайти розв'язання наших проблем.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [947855649] = {
        ["english"] = { [1] = "Greetings, $c.$B$BThe Horde now controls Wintergrasp Fortress. Use the portal, if you like.$B$BThe next battle begins in $3975w:$3976w$3782w:$3784w$3785w." },
        ["text"] = "Вітаю, $c.$B$BОрда зараз контролює фортецю Зимохвату. Можеш скористатися порталом.$B$BНаступна битва почнеться через $3975w:$3976w$3782w:$3784w$3785w.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1664783109] = {
        ["english"] = { [1] = "Hey mon, what can I be doin' for you?" },
        ["text"] = "Гей, мон, чим можу бути корисний?",
        ["npcs"] = { [1] = 3484 },
        ["roles"] = { ["greeting"] = true },
    },
    [2847794539] = {
        ["english"] = { [1] = "I am sorry $c, but you need to be more powerful before I can allow you to enter Arathi Basin." },
        ["text"] = "Вибач, $c, але тобі треба стати сильнішим, перш ніж я дозволю ввійти до Низини Араті.",
        ["npcs"] = { [1] = 907, [2] = 12198, [3] = 15006, [4] = 15008 },
        ["roles"] = { ["greeting"] = true },
    },
    [1429074638] = {
        ["english"] = { [1] = "I am sorry $c, but you need to be more experienced before you can survive in Alterac Valley." },
        ["text"] = "Вибач, $c, але тобі потрібно більше досвіду, щоб вижити в Альтерацькій долині.",
        ["npcs"] = { [1] = 347, [2] = 5118, [3] = 7410, [4] = 7427, [5] = 14942 },
        ["roles"] = { ["greeting"] = true },
    },
    [232724434] = {
        ["english"] = { [1] = "How can I prove myself to the Timbermaw furbolg?" },
        ["text"] = "Як мені довести свою відданість фурболґам Деревопащих?",
        ["npcs"] = { [1] = 11554 },
        ["roles"] = { ["reply"] = true },
    },
    [996376627] = {
        ["english"] = { [1] = "I am sorry $c, but you are not seasoned enough yet to enter Warsong Gulch." },
        ["text"] = "Вибач, $c, але ти ще недостатньо загартований, щоб увійти до Ущелини Пісні Війни.",
        ["npcs"] = { [1] = 2302, [2] = 2804, [3] = 3890, [4] = 10360, [5] = 14981 },
        ["roles"] = { ["greeting"] = true },
    },
    [3789642240] = {
        ["english"] = { [1] = "Fish so delicious. You come learn fish? Eat fish? Mmmmm..." },
        ["text"] = "Риба така смачна. Ти прийти вчити риба? Їсти риба? М-м-м...",
        ["npcs"] = { [1] = 3332 },
        ["roles"] = { ["greeting"] = true },
    },
    [1066839709] = {
        ["english"] = { [1] = "I am so very close to figuring this ore out. Any minute now and I will have the solution!" },
        ["text"] = "Я вже майже розгадав цю руду. Ще мить — і знайду рішення!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3291783132] = {
        ["english"] = { [1] = "I am so smart!  S-M-R-T!" },
        ["text"] = "Я такий розумний! Р-О-З-М!",
        ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 },
        ["roles"] = { ["greeting"] = true },
    },
    [1106196621] = {
        ["english"] = { [1] = "How can I help?" },
        ["text"] = "Чим можу допомогти?",
        ["npcs"] = { [1] = 3442, [2] = 11216 },
        ["roles"] = { ["greeting"] = true, ["reply"] = true },
    },
    [3360886449] = {
        ["english"] = { [1] = "I am Al'tabim the All-Seeing - an envoy of King Rastakhan.$B$BMy dealings are with priests, mages, and warlocks." },
        ["text"] = "Я Ал'табім Всевидячий — посланець короля Растахана.$B$BМаю справи з жерцями, магами й чорнокнижниками.",
        ["npcs"] = { [1] = 14903 },
        ["roles"] = { ["greeting"] = true },
    },
    [4048881763] = {
        ["english"] = { [1] = "I am SO glad that evil Gankly Rottenfist got his just desserts!  I have lots of skins if you want some to give to Harold." },
        ["text"] = "Я ТАК радий, що мерзотник Ґенклі Гнилокулак отримав по заслузі! У мене повно шкур, якщо хочеш передати кілька Гарольду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2189686614] = {
        ["english"] = { [1] = "How can my people fight when the elements are in such turmoil? Do they not see that without the support of the elements, the world simply cannot be." },
        ["text"] = "Як мій народ може битися, коли стихії в такому безладі? Невже вони не бачать, що без підтримки стихій сам світ не може існувати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3603249327] = {
        ["english"] = { [1] = "Find Tarshaw Jaggedscar inside the barracks on the east side of Razor Hill.  Bring pride and honor to the Horde youngling!" },
        ["text"] = "Знайди Таршоу Рваношрама в казармах на східному боці Колючого Пагорба. Принеси Орді гордість і честь, малий!",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [4204357241] = {
        ["english"] = { [1] = "Fascinating. Please, tell me more." },
        ["text"] = "Захопливо. Розкажіть, будь ласка, більше.",
        ["npcs"] = { [1] = 8888 },
        ["roles"] = { ["reply"] = true },
    },
    [3091191922] = {
        ["english"] = { [1] = "I am Samuel Hawke, the main supplier for the League of Arathor posted here at Arathi Basin.  As you improve your standing with us, I will make available to you a fine selection of goods that you might find useful.  Should you find yourself in need of item repair, I also provide those services." },
        ["text"] = "Я Семюел Гок, головний постачальник Ліги Аратора тут, у Низині Араті. Що кращою ставатиме твоя репутація в нас, то ширший вибір корисних товарів я тобі пропонуватиму. Якщо знадобиться ремонт предметів — цю послугу я теж надаю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [678374959] = {
        ["english"] = { [1] = "Heya mon.  Go talk to mah Master Gadrin right over there.  Take care of that Zalazane crazy for him and I fix ya right up!" },
        ["text"] = "Гей, мон. Поговори з моїм майстром Ґадріном он там. Розберися для нього з тим божевільним Залазаном — і я тебе підлатаю!",
        ["npcs"] = { [1] = 10578 },
        ["roles"] = { ["greeting"] = true },
    },
    [1919670884] = {
        ["english"] = { [1] = "Duke of Cynders! I hold your signet!  Heed my call!" },
        ["text"] = "Герцогу Попелу! Я тримаю твою печатку! Почуй мій поклик!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [206445624] = {
        ["english"] = { [1] = "Go to Ironforge's Mystic Ward and speak with the night elf druids there. They can transport you to Moonglade to join in the Lunar Festival celebration." },
        ["text"] = "Іди до Містичного кварталу Залізогарта й поговори там із друїдами нічних ельфів. Вони можуть перенести тебе до Місячної Галявини, щоб приєднатися до святкування Місячного фестивалю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [582404263] = {
        ["english"] = { [1] = "Greetings young $c. It is here that your Warchief challenged Orgrim Doomhammer! Although it happened so many years ago, it is an image still fresh in my mind." },
        ["text"] = "Вітаю, юний $c. Саме тут твій Вождь кинув виклик Орґріму Молоту Згуби! Хоч це сталося багато років тому, картина досі стоїть перед очима.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2138320769] = {
        ["english"] = { [1] = "Fancy yourself a chef?  Head to the Undercity south of town for your training.  You can catch the elevators heading down at the back of the Ruins of Lordaeron.  Talk to one of those lumbering Undercity Guardians for further assistance once you arrive." },
        ["text"] = "Вважаєш себе кухарем? Тоді йди в Підмісто на південь від міста на навчання. Ліфти вниз розташовані позаду руїн Лордерону. Коли прибудеш, звернися до одного з незграбних вартових Підміста — вони підкажуть далі.",
        ["npcs"] = { [1] = 1496, [2] = 1652, [3] = 1735, [4] = 1738, [5] = 1742, [6] = 1743, [7] = 1744, [8] = 1745, [9] = 1746, [10] = 2209, [11] = 2210, [12] = 5725 },
        ["roles"] = { ["greeting"] = true },
    },
    [1370617837] = {
        ["english"] = { [1] = "I am Rutherford Twing, the main supplier for the Defilers posted here at Arathi Basin.  As you improve your standing with us, I will make available to you a fine selection of goods that you might find useful.  Should you find yourself in need of item repair, I also provide those services." },
        ["text"] = "Я Резерфорд Твінґ, головний постачальник Осквернителів тут, у Низині Араті. Що кращою ставатиме твоя репутація в нас, то ширший вибір корисних товарів я тобі пропонуватиму. Якщо знадобиться ремонт предметів — цю послугу я теж надаю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [670156289] = {
        ["english"] = { [1] = "Everything has a spirit, if you learn to listen to it you can get it to take any shape you want. Blacksmithing isn't about beating metal, forcing it to do your will. It's about listening to the spirit within the steel and guiding it to the shape you know it wants to take." },
        ["text"] = "У всього є дух. Якщо навчишся його слухати, зможеш надати металу будь-якої форми. Ковальство — це не про те, щоб бити метал і силоміць підкоряти його волі. Це про те, щоб слухати дух у сталі й вести її до форми, якої вона сама прагне.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1283207972] = {
        ["english"] = { [1] = "I am ready, Historian Archesonus." },
        ["text"] = "Я готовий, історике Архезонусе.",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["reply"] = true },
    },
    [3220120621] = {
        ["english"] = { [1] = "I am ready, as are my forces. Let us end this masquerade!" },
        ["text"] = "Я готовий, як і мої сили. Покладемо край цій виставі!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1190113327] = {
        ["english"] = { [1] = "Don't get too close, $N. I'm liable to fumble and bash your brains open with the face of my hammer." },
        ["text"] = "Не підходь надто близько, $N. Ще незграбно махну молотом і розтрощу тобі голову.",
        ["npcs"] = { [1] = 11191 },
        ["roles"] = { ["greeting"] = true },
    },
    [911757074] = {
        ["english"] = { [1] = "I am ready to discover where my fortune lies!" },
        ["text"] = "Я готовий дізнатися, де ховається моя доля!",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [3303141312] = {
        ["english"] = { [1] = "Hendel is in our custody now, $N, thanks to you.$B$BAlthough the questioning goes slowly, I assure you, he will tell us everything he knows.$B$BFor now, please be patient. I will contact you immediately if we have need of your assistance.$B$BUntil then, please, enjoy Theramore and I invite you to stay for as long as you like within our city's walls as a friend of the Alliance." },
        ["text"] = "Гендел тепер у нас під вартою, $N, завдяки тобі.$B$BДопит просувається повільно, але запевняю, він розповість усе, що знає.$B$BА поки наберись терпіння. Якщо нам знадобиться допомога, я негайно зв'яжуся з тобою.$B$BДо того часу насолоджуйся Терамором і залишайся в наших мурах стільки, скільки забажаєш, як друг Альянсу.",
        ["npcs"] = { [1] = 4968 },
        ["roles"] = { ["greeting"] = true },
    },
    [3674838133] = {
        ["english"] = { [1] = "Good steel $N. Grab a hammer and come over here, let me show you the secret to forging a legendary weapon." },
        ["text"] = "Добра сталь, $N. Бери молот і ставай сюди — я покажу тобі секрет кування легендарної зброї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [74469947] = {
        ["english"] = { [1] = "Enjoying the festival, $c?$b$bWhile the Flame Keepers tend to the fires of the present, I am more of a historian, keeping close the festivals past. I'm also, of course, documenting this year's festivities. Things are going well thus far, don't you think?$b$bYou know, $n, there is power inherent in all festival fires burning throughout the holiday. We're taking care of ours, but I'm certain there are sacred flames burning deep within our enemy's cities..." },
        ["text"] = "Подобається свято, $c?$b$bПоки Вартові Полум'я дбають про вогні сьогодення, я більше історик і бережу пам'ять про минулі свята. І, звісно, записую події цього року. Поки що все йде добре, хіба ні?$b$bЗнаєш, $n, у всіх святкових вогнях, що палають упродовж свята, є своя сила. Ми бережемо наші, але я певен, що священні вогні палають і в самому серці ворожих міст...",
        ["npcs"] = { [1] = 16818 },
        ["roles"] = { ["greeting"] = true },
    },
    [3954486438] = {
        ["english"] = { [1] = "Er... that's how I found them.  I wanted to show the king that they were a threat!  Say Captain... I overheard Guard Fengus calling you a fat, useless gnoll lover!" },
        ["text"] = "Е-е... так я їх і знайшов. Я хотів показати королю, що вони становлять загрозу! До речі, капітане... я чув, як вартовий Фенґус назвав вас товстим, нікчемним любителем ґнолів!",
        ["npcs"] = { [1] = 14325 },
        ["roles"] = { ["reply"] = true },
    },
    [3541344820] = {
        ["english"] = { [1] = "How are the gift standings?  Who's the most popular?" },
        ["text"] = "Які результати з подарунками? Хто найпопулярніший?",
        ["npcs"] = { [1] = 16075 },
        ["roles"] = { ["reply"] = true },
    },
    [2838855836] = {
        ["english"] = { [1] = "Forgive me, $r, I must focus on my job." },
        ["text"] = "Пробачте, $r, я мушу зосередитися на роботі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3094669263] = {
        ["english"] = { [1] = "How can I get Evoroot?" },
        ["text"] = "Як мені дістати евокорінь?",
        ["npcs"] = { [1] = 7775 },
        ["roles"] = { ["reply"] = true },
    },
    [2515627735] = {
        ["english"] = { [1] = "Elder Rumblerock passes the years in a cave atop Dreadmaul Rock in the Burning Steppes." },
        ["text"] = "Старійшина Гуркоскеля проводить роки в печері на вершині Скелі Жахобою в Палаючому степу.",
        ["npcs"] = { [1] = 15562, [2] = 15565, [3] = 15576, [4] = 15585 },
        ["roles"] = { ["greeting"] = true },
    },
    [2546110839] = {
        ["english"] = { [1] = "I am ready to begin." },
        ["text"] = "Я готовий почати.",
        ["npcs"] = { [1] = 7998 },
        ["roles"] = { ["reply"] = true },
    },
    [172934421] = {
        ["english"] = { [1] = "I am pleased with your progress so far. Surely the Earth Mother has inspired your hands." },
        ["text"] = "Я задоволений твоїм поступом. Без сумніву, сама Матір-Земля надихнула твої руки.",
        ["npcs"] = { [1] = 11084 },
        ["roles"] = { ["greeting"] = true },
    },
    [83784901] = {
        ["english"] = { [1] = "I am pleased that you've decided to take up our cause.  As a reward I will infuse a ring with the remnants of the Well of Eternity you brought me.$B$BI offer you four different paths in which to unlock their power.  Choose wisely, $N.  The sands of time flow easily in one direction and not the other." },
        ["text"] = "Я радий, що ти вирішив підтримати нашу справу. Як нагороду я наповню перстень залишками Криниці Вічності, які ти приніс.$B$BЯ пропоную чотири різні шляхи розкриття їхньої сили. Обирай мудро, $N. Піски часу легко течуть лише в одному напрямку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3622892045] = {
        ["english"] = { [1] = "I am patiently awaiting orders, $c." },
        ["text"] = "Я терпляче чекаю наказів, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [554234738] = {
        ["english"] = { [1] = "I am not here because of honor, $N. I am here because of one orc's pride.$B$BIf I had not rejected Belgrom's offers, then I'm sure I'd still be in Orgrimmar taking care of real business.$B$BHis desire for women is not unknown to many of the female warriors in Durotar, but that doesn't stop him from being his charming self.$B$BHe's lucky he didn't pursue his desire for me much longer though--he'd be short more than just the digits on his hands." },
        ["text"] = "Я тут не заради честі, $N. Я тут через гордість одного орка.$B$BЯкби я не відкинула пропозиції Белґрома, певно, досі була б в Орґріммарі й займалася справжньою роботою.$B$BЙого слабкість до жінок добре відома багатьом воїтелькам Дуротару, але це не заважає йому лишатися «чарівним».$B$BЙому пощастило, що він не переслідував мене довше — інакше втратив би не лише пальці на руках.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3606533415] = {
        ["english"] = { [1] = "I am no cultist, you monster!  Come to me and face your destruction!" },
        ["text"] = "Я не культист, потворо! Іди сюди й зустрінь свою загибель!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3368081366] = {
        ["english"] = { [1] = "Greetings, $c.  Are you here to learn of the hidden arts?" },
        ["text"] = "Вітаю, $c. Прийшли навчитися таємних мистецтв?",
        ["npcs"] = { [1] = 5880, [2] = 5882, [3] = 5883, [4] = 5884, [5] = 5885, [6] = 7311 },
        ["roles"] = { ["greeting"] = true },
    },
    [943633770] = {
        ["english"] = { [1] = "Good to see ya again!$B$BKing Stormheart has informed me that he will be taking his leave for a time... a grim memory brought back to him has left him with a score to settle it seems. He was very insistent that we not join him, so we have respected his wishes as we always do.$B$BI have taken responsibility for our clan in the meantime. You are still welcome with us, of course." },
        ["text"] = "Радий знову тебе бачити!$B$BКороль Буресерд повідомив, що на деякий час піде... схоже, похмурий спогад повернувся й лишив у нього незакритий рахунок. Він дуже наполягав, щоб ми не йшли за ним, тож ми, як завжди, поважаємо його волю.$B$BПоки що я взяв відповідальність за наш клан на себе. І, звісно, тобі досі тут раді.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1126360780] = {
        ["english"] = { [1] = "I am most grateful for your help, $c!" },
        ["text"] = "Я безмежно вдячний за твою допомогу, $c!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [742052645] = {
        ["english"] = { [1] = "Everything that has happened since the crash is little more than a blur. It seems like a lifetime ago that I was aboard the Exodar.$B$BNow, my reality is restricted to this island with its mutant creatures and endless sea of blood elf agents. Soon, it will be as if I've never known anything different..." },
        ["text"] = "Усе, що сталося після аварії, злилося в суцільну каламуть. Здається, минуло ціле життя відтоді, як я був на борту Екзодара.$B$BТепер увесь мій світ — цей острів, мутовані істоти та нескінченний потік агентів ельфів крові. Скоро здаватиметься, ніби я ніколи й не знав іншого життя...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1284658079] = {
        ["english"] = { [1] = "How many more supplies are needed for the next upgrade?" },
        ["text"] = "Скільки ще припасів потрібно для наступного покращення?",
        ["npcs"] = { [1] = 13176, [2] = 13257 },
        ["roles"] = { ["reply"] = true },
    },
    [1580593471] = {
        ["english"] = { [1] = "Examining the corpse, you conclude that this must be Blood Knight Dawnstar, the leader of the failed assault on Deatholme." },
        ["text"] = "Оглянувши труп, ви доходите висновку, що це, мабуть, лицар крові Світанкова Зірка — очільник невдалого штурму Смертгольма.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3038433944] = {
        ["english"] = { [1] = "Go to the Valley of Strength and look for the Bank of Orgrimmar to the south of the Sky Tower." },
        ["text"] = "Іди до Долини Сили й шукай Банк Орґріммара на південь від Небесної Вежі.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [3888775074] = {
        ["english"] = { [1] = "Don't get me wrong, I'd rather not be in a tunnel filled with silithid day in and day out, but if hiding here and watching these creatures' movements is going to help us win the war then I'll do it for as long as it takes." },
        ["text"] = "Не зрозумій мене неправильно: я не в захваті від того, що день у день сиджу в тунелі, повному силітидів. Але якщо наша засідка тут і спостереження за їхніми пересуваннями допоможуть виграти війну, я сидітиму стільки, скільки треба.",
        ["npcs"] = { [1] = 15611 },
        ["roles"] = { ["greeting"] = true },
    },
    [1964788678] = {
        ["english"] = { [1] = "I am listening, Demitrian." },
        ["text"] = "Я слухаю, Демітріане.",
        ["npcs"] = { [1] = 14347 },
        ["roles"] = { ["reply"] = true },
    },
    [1724514451] = {
        ["english"] = { [1] = "I am Krathok, overseer of these craftsmen." },
        ["text"] = "Я Краток, наглядач цих ремісників.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1512875991] = {
        ["english"] = { [1] = "Draenei have come back! This group jumped two of my best wolf riders as they were out patrolling the western roads. Needless to say, we were victorious in that skirmish.$B$BNow I'm not sure what's going on but from what my scouts tell me, there are blood elves and draenei all over Halaa. I'm no blood elf lover but if it's one thing I hate it's a draenei. If you see draenei or any of their allies at Halaa, be sure to put a boot in their backsides for me.$B$BHalaa's to the west... In case you want to go now." },
        ["text"] = "Дренеї повернулися! Ця зграя напала на двох моїх найкращих вовчих вершників, коли ті патрулювали західні дороги. Звісно, у тій сутичці ми перемогли.$B$BНе знаю, що там коїться, але розвідники кажуть, що Халаа кишить ельфами крові та дренеями. Я не люблю ельфів крові, але якщо когось і ненавиджу більше — то дренеїв. Побачиш у Халаа дренея чи когось із їхніх союзників — копни його під зад від мого імені.$B$BХалаа на заході... Якщо раптом хочеш вирушити просто зараз.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2707566082] = {
        ["english"] = { [1] = "First Aid?  Well ye don't look hurt to me.  If yer really interested in learning First Aid, then Nissa Firestone is the one to learn from.  Go see her over by The Great Forge in her shop, The Ironforge Physician." },
        ["text"] = "Перша допомога? Та ти наче не поранений. Якщо справді хочеш її вивчити, звертайся до Нісси Вогнекамінь. Вона біля Великої Кузні, у крамниці «Залізогартський лікар».",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [1578433925] = {
        ["english"] = { [1] = "I am sorry but I can not train any more apprentices. Seek out Mak in Thunder Bluff. He will be able to teach you the basics." },
        ["text"] = "Вибач, але я більше не можу брати учнів. Знайди Мака в Громовому Бескиді. Він навчить тебе основ.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1661491296] = {
        ["english"] = { [1] = "How many herbs have the Alliance collected so far?" },
        ["text"] = "Скільки трав уже зібрав Альянс?",
        ["npcs"] = { [1] = 15458, [2] = 15701 },
        ["roles"] = { ["reply"] = true },
    },
    [1013039218] = {
        ["english"] = { [1] = "Helpless... powerless... restore... must restore... Zevrim controls... end this torment..." },
        ["text"] = "Безпорадний... безсилий... відновити... треба відновити... Зеврім керує... припиніть ці муки...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2166305233] = {
        ["english"] = { [1] = "Hello $r, it is a pleasure to make your acquaintance.\010" },
        ["text"] = "Привіт, $r, приємно познайомитися.\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3434498634] = {
        ["english"] = { [1] = "I am afraid that I am no longer gentle or humble. Age and countless battles have hardened my skin and soul. Perhaps that is why Cairne assigned me to Sun Rock Retreat... the gentle winds and warm sun does ease the pain." },
        ["text"] = "Боюся, я вже не лагідний і не смиренний. Вік і незліченні битви загартували мою шкіру й душу. Можливо, саме тому Керн призначив мене до прихистку Сонячної Скелі... лагідний вітер і тепле сонце трохи вгамовують біль.",
        ["npcs"] = { [1] = 11860 },
        ["roles"] = { ["greeting"] = true },
    },
    [2855132815] = {
        ["english"] = { [1] = "Focus your mind, mortal. This is the front line of a war unlike any you've witnessed.$b$bYou'll need full command of your faculties if you are to be of any use." },
        ["text"] = "Зосередься, смертний. Це передова війни, якої ти ще ніколи не бачив.$b$bЯкщо хочеш бути корисним, тобі знадобиться повний контроль над власним розумом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2829592436] = {
        ["english"] = { [1] = "I am Jin'rokh the Breaker, envoy of Mugamba: Fist of Rastakhan!$B$BMy dealings are with warriors and heathens." },
        ["text"] = "Я Джин'рок Руйнівник, посланець Муґамби — Кулака Растахана!$B$BМаю справи з воїнами та язичниками.",
        ["npcs"] = { [1] = 14902 },
        ["roles"] = { ["greeting"] = true },
    },
    [3833420991] = {
        ["english"] = { [1] = "Even in peace there is still war, and many clans still fight beneath the banner of the Warchief. Are you here to add your clan to those that fight for Orgrimmar?" },
        ["text"] = "Навіть у мирний час триває війна, і багато кланів досі б'ються під прапором Вождя. Ти прийшов додати свій клан до тих, хто воює за Орґріммар?",
        ["npcs"] = { [1] = 3370 },
        ["roles"] = { ["greeting"] = true },
    },
    [2633380395] = {
        ["english"] = { [1] = "I am interested in mage training." },
        ["text"] = "Мене цікавить навчання магії.",
        ["npcs"] = { [1] = 198, [2] = 328, [3] = 331, [4] = 944, [5] = 1228, [6] = 2124, [7] = 2128, [8] = 3047, [9] = 3048, [10] = 3049, [11] = 4566, [12] = 4567, [13] = 4568, [14] = 5144, [15] = 5145, [16] = 5146, [17] = 5497, [18] = 5498, [19] = 5880, [20] = 5882, [21] = 5883, [22] = 5884, [23] = 5885, [24] = 7311, [25] = 7312 },
        ["roles"] = { ["reply"] = true },
    },
    [4123841051] = {
        ["english"] = { [1] = "I almost have enough supplies to upgrade to veteran units." },
        ["text"] = "Мені майже вистачає припасів, щоб покращити війська до рівня ветеранів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3317324220] = {
        ["english"] = { [1] = "For reasons I cannot understand, Elder Thunderhorn has gone to the Slithering Scar in Un'Goro Crater." },
        ["text"] = "З незрозумілих мені причин старійшина Громовий Ріг вирушив до Повзучого Шраму в кратері Ун'Ґоро.",
        ["npcs"] = { [1] = 15570, [2] = 15573, [3] = 15578, [4] = 15586, [5] = 15599 },
        ["roles"] = { ["greeting"] = true },
    },
    [1166608918] = {
        ["english"] = { [1] = "Hello, friend. How may I be of service to you today?" },
        ["text"] = "Привіт, друже. Чим можу прислужитися сьогодні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2603207495] = {
        ["english"] = { [1] = "I am in search of a great and powerful Warlock." },
        ["text"] = "Я шукаю великого й могутнього чорнокнижника.",
        ["npcs"] = { [1] = 14469 },
        ["roles"] = { ["reply"] = true },
    },
    [412977096] = {
        ["english"] = { [1] = "Greetings, $r!  I trust this day finds you well?" },
        ["text"] = "Вітаю, $r! Сподіваюся, день видався добрим?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1576207002] = {
        ["english"] = { [1] = "How do I use the Cache of Mau'ari?" },
        ["text"] = "Як користуватися Сховком Мау'арі?",
        ["npcs"] = { [1] = 10307 },
        ["roles"] = { ["reply"] = true },
    },
    [307174346] = {
        ["english"] = { [1] = "Greetings, $c. Is there something I can help you with?" },
        ["text"] = "Вітаю, $c. Чим можу допомогти?",
        ["npcs"] = { [1] = 4489 },
        ["roles"] = { ["greeting"] = true },
    },
    [4169688849] = {
        ["english"] = { [1] = "Hegnar Rumbleshot, at your service!" },
        ["text"] = "Геґнар Громопостріл, до ваших послуг!",
        ["npcs"] = { [1] = 1243 },
        ["roles"] = { ["greeting"] = true },
    },
    [93545350] = {
        ["english"] = { [1] = "Glacial Cloak." },
        ["text"] = "Льодовиковий плащ.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [2454051356] = {
        ["english"] = { [1] = "Greatfather Winter leaves toys for everyone under the tree in Ironforge during the feast of Winter Veil!" },
        ["text"] = "Під час Свята Зимового Покрову Дідусь Зима залишає під деревом у Залізогарті іграшки для всіх!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1077726857] = {
        ["english"] = { [1] = "How are ye? Had yer fill o' Outland, and ready ta head back ta Alterac Valley and give the Horde what for?" },
        ["text"] = "Як ся маєш? Уже досить Позамежжя й готовий вертатися до Альтерацької долини та добряче всипати Орді?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3626381741] = {
        ["english"] = { [1] = "I am impressed that pine tree branches don't seem to damage our ship much.$b$bNot that it excuses the three times we've crashed into some forest." },
        ["text"] = "Мене вражає, що соснові гілки майже не пошкоджують наш корабель.$b$bЩоправда, це не виправдовує трьох випадків, коли ми врізалися в ліс.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1583634878] = {
        ["english"] = { [1] = "Frostmourne: the blade that destroyed our kingdom..." },
        ["text"] = "Крижана Скорбота: клинок, що знищив наше королівство...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [429970158] = {
        ["english"] = { [1] = "Greetings.  I'm a gnome mage trainer, and you're a mage." },
        ["text"] = "Вітаю. Я гном-наставник магів, а ти маг.",
        ["npcs"] = { [1] = 944, [2] = 1228, [3] = 5144, [4] = 5145, [5] = 5146, [6] = 7312 },
        ["roles"] = { ["greeting"] = true },
    },
    [2373270166] = {
        ["english"] = { [1] = "Don't let the beady eyes and bushy beard fool you. Vosur's a talented apprentice and a good friend, even if I do get a crick in my neck when I talk to him." },
        ["text"] = "Нехай ці очі-намистинки й кущиста борода тебе не обманюють. Возур — здібний учень і добрий друг, хоча в мене й шия затікає, коли з ним розмовляю.",
        ["npcs"] = { [1] = 5177 },
        ["roles"] = { ["greeting"] = true },
    },
    [1938676238] = {
        ["english"] = { [1] = "Heh. Nothing against you, pup, but you might want to find somewhere else to bed down for the night. Wouldn't want that tender skin of yours to get bruised." },
        ["text"] = "Хех. Нічого проти тебе, щеня, але на ніч краще знайти інше місце. Не хотілося б, щоб твоя ніжна шкірка вкрилася синцями.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [341187928] = {
        ["english"] = { [1] = "Get it over with you filthy $r.$B$B<Kharan lowers his head, exposing his stubby neck.>" },
        ["text"] = "Кінчай уже, брудний $r.$B$B<Каран опускає голову, оголюючи коротку шию.>",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["greeting"] = true },
    },
    [3418152136] = {
        ["english"] = { [1] = "I am honored to share my knowledge with you, $N. See that you use it well." },
        ["text"] = "Для мене честь поділитися з тобою знаннями, $N. Використовуй їх мудро.",
        ["npcs"] = { [1] = 5500 },
        ["roles"] = { ["greeting"] = true },
    },
    [2460415185] = {
        ["english"] = { [1] = "Hello there, $N.  I am known as Chronormu, but you may call me Chromie.  I am comfortable with such familiarity.$B$BNow - how did I know your name, you ask?  I am one of the bronze dragonflight, forever attuned to the ebb and flow of time.  You could say that we have met before.  To that end, we shall also meet again.$B$BI hope that my choice of visual demeanor does not disturb you; while I might be charged to be a sentry of sorrowful places, I choose not to drown in the sorrow of the locale.\010\010\010" },
        ["text"] = "Привіт, $N. Мене звати Хронорму, але можеш називати мене Хромі. Я не проти такої фамільярності.$B$BА тепер ти, мабуть, питаєш, звідки я знаю твоє ім'я? Я з бронзової драконячої зграї, навіки налаштованої на припливи й відпливи часу. Можна сказати, ми вже зустрічалися. І так само ще зустрінемося.$B$BСподіваюся, мій обраний вигляд тебе не бентежить; хоч мені й доручено стерегти скорботні місця, я не збираюся потопати в їхньому смутку.\010\010\010",
        ["npcs"] = { [1] = 10667 },
        ["roles"] = { ["greeting"] = true },
    },
    [1365015053] = {
        ["english"] = { [1] = "I am here to assist and defend you.$B$BHow next shall we strike at the enemy?" },
        ["text"] = "Я тут, щоб допомагати й захищати вас.$B$BКуди завдамо наступного удару по ворогу?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2798850586] = {
        ["english"] = { [1] = "I am here for training." },
        ["text"] = "Я прийшов на навчання.",
        ["npcs"] = { [1] = 4217, [2] = 5116 },
        ["roles"] = { ["reply"] = true },
    },
    [1078876313] = {
        ["english"] = { [1] = "I am here at the behest of Nexus-Prince Haramad. Strange things are afoot at the Stormspire." },
        ["text"] = "Я тут за наказом принца Нексуса Гарамада. На Штормовому Шпилі коїться щось дивне.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2865378603] = {
        ["english"] = { [1] = "Here for training eh? Just began my training meself, but I would be glad ta teach ye what I can." },
        ["text"] = "На навчання, еге ж? Я й сам лише почав учитися, але залюбки навчу тебе того, що знаю.",
        ["npcs"] = { [1] = 1241 },
        ["roles"] = { ["greeting"] = true },
    },
    [3245543864] = {
        ["english"] = { [1] = "I am he that watches they. I am the fist of retribution. That which does quell the recalcitrant. Dare you defy the Warchief? Dare you face my merciless judgement?" },
        ["text"] = "Я той, хто стежить за ними. Я — кулак відплати. Той, хто втихомирює непокірних. Насмілишся кинути виклик Вождю? Насмілишся постати перед моїм безжальним судом?",
        ["npcs"] = { [1] = 14720 },
        ["roles"] = { ["greeting"] = true },
    },
    [1053073164] = {
        ["english"] = { [1] = "I am he that carries out the Warchief's commands without question. I am Horde." },
        ["text"] = "Я той, хто беззаперечно виконує накази Вождя. Я — Орда.",
        ["npcs"] = { [1] = 14392 },
        ["roles"] = { ["greeting"] = true },
    },
    [2087230170] = {
        ["english"] = { [1] = "Here is your fortune, $N.  May it serve you well.\010" },
        ["text"] = "Ось твоє пророцтво, $N. Нехай стане тобі в пригоді.\010",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["greeting"] = true },
    },
    [2880991216] = {
        ["english"] = { [1] = "Everything okay?" },
        ["text"] = "Усе гаразд?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3315074669] = {
        ["english"] = { [1] = "I am unable to process your chronological reference in comparison to the recording of this data, my apologies.$B$BThe trogg retains some composition of Azeroth's various stone core compounds, but the loss of cognitive power makes this variant unacceptable to the Creators.$B$BThe trogg procreates as per a standard biomass.  By default it consumes stone and anything else it can acquire, including other troggs.  Cannibalism is considered unacceptable by the Creators." },
        ["text"] = "Перепрошую, але я не можу обробити ваше хронологічне посилання у співвідношенні із записом цих даних.$B$BТроґґ зберігає певний склад різних кам'яних сполук ядра Азероту, але втрата когнітивних здібностей робить цей варіант неприйнятним для Творців.$B$BТроґґ розмножується як стандартна біомаса. За замовчуванням він споживає камінь і все інше, що може здобути, включно з іншими троґґами. Канібалізм Творці вважають неприйнятним.",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["greeting"] = true },
    },
    [168119001] = {
        ["english"] = { [1] = "Greetings, $N. I see you've come from Orgrimmar to aid us. I'm glad. I want to be out of this forsaken forest as quickly as possible. I'd much rather be spending my time in Orgrimmar with a good ale.$B$BAlthough I cannot wait to hear how Belgrom talked you into coming out here." },
        ["text"] = "Вітаю, $N. Бачу, ти прийшов з Орґріммара допомогти нам. Радий. Хочу якнайшвидше забратися з цього проклятого лісу. Я б значно охочіше сидів в Орґріммарі з добрим елем.$B$BХоча мені дуже цікаво почути, як Белґром умовив тебе сюди прийти.",
        ["npcs"] = { [1] = 8587 },
        ["roles"] = { ["greeting"] = true },
    },
    [1891203513] = {
        ["english"] = { [1] = "Hmmm, that good idea.  Maybe we head there to get some stitches replaced?  Him sew good.  You find Josef Gregorian on inner circle of Magic Quarter." },
        ["text"] = "Гм-м, гарна думка. Може, й нам туди — підлатати кілька швів? Він добре шиє. Йозефа Ґреґоріана знайдеш на внутрішньому кільці Магічного кварталу.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1349019503] = {
        ["english"] = { [1] = "I am forever in your debt, $N." },
        ["text"] = "Я навіки твій боржник, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1881609992] = {
        ["english"] = { [1] = "I am forever denied the touch of stone.  I will never again know the glory of shaped iron..." },
        ["text"] = "Мені назавжди відмовлено в дотику каменю. Я більше ніколи не відчую слави кованого заліза...",
        ["npcs"] = { [1] = 9037 },
        ["roles"] = { ["greeting"] = true },
    },
    [2114846294] = {
        ["english"] = { [1] = "Hail, traveler! What brings you to my doorstep?" },
        ["text"] = "Вітаю, мандрівнику! Що привело тебе до мого порога?",
        ["npcs"] = { [1] = 11068 },
        ["roles"] = { ["greeting"] = true },
    },
    [2952894824] = {
        ["english"] = { [1] = "Greeting $c - welcome to the front lines in our conquest of Ashenvale!  If you are looking for something to do, then you've come to the right place.  I'm always looking for able-bodied individuals to help bring glory to the Horde!" },
        ["text"] = "Вітаю, $c — ласкаво просимо на передову нашого завоювання Ясенедолу! Якщо шукаєш, чим зайнятися, ти прийшов куди треба. Я завжди шукаю міцних бійців, які допоможуть принести славу Орді!",
        ["npcs"] = { [1] = 12757 },
        ["roles"] = { ["greeting"] = true },
    },
    [328846629] = {
        ["english"] = { [1] = "Greetings, $c.  You are welcome in Nighthaven, as well as all of Moonglade.  The Cenarion Circle welcomes all beings who respect the authority and command of nature.$B$BWhile you are here, please be sure to preserve the balance in all things.  Disturbances are not welcome here, and our wardens are trained to cease all hostilities without question." },
        ["text"] = "Вітаю, $c. Тобі раді в Нічній Гавані й по всій Місячній Галявині. Кенарієве Коло приймає всіх істот, які шанують владу й порядок природи.$B$BПоки ти тут, бережи рівновагу в усьому. Порушення спокою тут не вітаються, а наші вартові навчені негайно припиняти будь-які сутички.",
        ["npcs"] = { [1] = 11802 },
        ["roles"] = { ["greeting"] = true },
    },
    [1778049913] = {
        ["english"] = { [1] = "Have you ever seen drakes like the ones around here? Makes for perfect hunting." },
        ["text"] = "Бачив колись таких драків, як тут? Ідеальна дичина.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2879962088] = {
        ["english"] = { [1] = "Give me the arcana and I shall craft the amalgamation, mortal." },
        ["text"] = "Дай мені аркану, смертний, і я створю сплав.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1908866213] = {
        ["english"] = { [1] = "How many cooked goods have the Alliance collected so far?" },
        ["text"] = "Скільки готової їжі вже зібрав Альянс?",
        ["npcs"] = { [1] = 15458, [2] = 15701 },
        ["roles"] = { ["reply"] = true },
    },
    [2296527452] = {
        ["english"] = { [1] = "I am diseased. Please cure me, medic." },
        ["text"] = "Я хворий. Вилікуйте мене, медику.",
        ["npcs"] = { [1] = 16284 },
        ["roles"] = { ["reply"] = true },
    },
    [4069625159] = {
        ["english"] = { [1] = "I am free!  But the secret... is now in peril.  Akama must be warned!" },
        ["text"] = "Я вільний! Але таємниця... тепер у небезпеці. Акаму треба попередити!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2283558207] = {
        ["english"] = { [1] = "Give me the contract." },
        ["text"] = "Дай мені контракт.",
        ["npcs"] = { [1] = 12944 },
        ["roles"] = { ["reply"] = true },
    },
    [3922539244] = {
        ["english"] = { [1] = "Greetings, $c.$B$BThose Sentinels over there have allowed me to share their camp as long as I promise no trouble will follow--I am sure you can appreciate the need for diplomacy while here, yes?$B$BI am here investigating disturbances to the land, and since it aids their cause also, they have agreed that my presence here could only aid the tenuous alliance between all of Azeroth's races. If you wish to aid me, then I would appreciate it, but regardless, please try not to cause any trouble." },
        ["text"] = "Вітаю, $c.$B$BТі Вартові дозволили мені ділити з ними табір, якщо я пообіцяю не накликати біди — певен, ти розумієш, навіщо тут потрібна дипломатія, еге ж?$B$BЯ досліджую порушення в цих землях, і оскільки це також допомагає їхній справі, вони погодилися, що моя присутність може лише зміцнити крихкий союз між усіма расами Азероту. Якщо хочеш допомогти — буду вдячний, але в будь-якому разі не спричиняй проблем.",
        ["npcs"] = { [1] = 11548 },
        ["roles"] = { ["greeting"] = true },
    },
    [3866404166] = {
        ["english"] = { [1] = "Elder Dawnstrider can be found at Flame Crest on the Burning Steppes." },
        ["text"] = "Старійшину Світанкового Мандрівника можна знайти на Жевріючій Вершині в Палаючому степу.",
        ["npcs"] = { [1] = 15557 },
        ["roles"] = { ["greeting"] = true },
    },
    [2478317220] = {
        ["english"] = { [1] = "I am certain. Please proceed." },
        ["text"] = "Я впевнений. Продовжуйте.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2244767287] = {
        ["english"] = { [1] = "Hmm... the things you need to learn are a little above my head. Have a talk with Sellandus over at Larson's Clothiers just up the path to the right. He taught me everything I know!" },
        ["text"] = "Гм... те, що тобі треба вивчити, вже трохи вище мого рівня. Поговори із Селландусом у «Тканинах Ларсона» трохи далі праворуч по стежці. Він навчив мене всього, що я знаю!",
        ["npcs"] = { [1] = 1300 },
        ["roles"] = { ["greeting"] = true },
    },
    [4249198493] = {
        ["english"] = { [1] = "Emissary Taluun brought me with him hoping I could teach our new allies about the elements of this world... but no one will listen." },
        ["text"] = "Емісар Талуун привів мене сюди, сподіваючись, що я навчу наших нових союзників про стихії цього світу... але ніхто не слухає.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3280992281] = {
        ["english"] = { [1] = "I am bound eternally to this cursed world. What is it you desire, mortal?" },
        ["text"] = "Я навіки прикутий до цього проклятого світу. Чого ти бажаєш, смертний?",
        ["npcs"] = { [1] = 8816 },
        ["roles"] = { ["greeting"] = true },
    },
    [3874716953] = {
        ["english"] = { [1] = "Hi, $N!  Enjoying the party?" },
        ["text"] = "Привіт, $N! Подобається вечірка?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [28261637] = {
        ["english"] = { [1] = "Hail, $c!" },
        ["text"] = "Вітаю, $c!",
        ["npcs"] = { [1] = 11178 },
        ["roles"] = { ["greeting"] = true },
    },
    [1779945546] = {
        ["english"] = { [1] = "Gryphons, eh? Never really cared for the beasts but to each their own.\010\010You can find Dungar Longdrink on the rampart in the Trade District." },
        ["text"] = "Грифони, еге ж? Ніколи особливо їх не любив, але кожному своє.\010\010Дунґара Довгопива знайдеш на мурі в Торговому районі.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3985055806] = {
        ["english"] = { [1] = "Find the Wind Rider Master at the top of The Sky Tower in the Valley of Strength. Doras will make sure you find your way to the battle you seek." },
        ["text"] = "Знайди майстра вершників на вивернах на вершині Небесної Вежі в Долині Сили. Дорас подбає, щоб ти потрапив до битви, якої шукаєш.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1662747599] = {
        ["english"] = { [1] = "Hey. I'm on break." },
        ["text"] = "Гей. У мене перерва.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [451874673] = {
        ["english"] = { [1] = "Hazza'rah, the Dreamweaver.$B$BHis is the power of nightmares, and may his foes ever sleep.$B$BHazza'rah now dreams near the edge of madness." },
        ["text"] = "Газза'ра, Ткач Снів.$B$BЙому належить сила кошмарів, і нехай його вороги сплять вічно.$B$BНині Газза'ра снить біля межі божевілля.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [670162414] = {
        ["english"] = { [1] = "Hello, $n.  Welcome to Thelsamar, and while you're here don't forget to visit our local brewery!" },
        ["text"] = "Привіт, $n. Ласкаво просимо до Телсамара, і не забудь завітати до нашої місцевої броварні!",
        ["npcs"] = { [1] = 1340 },
        ["roles"] = { ["greeting"] = true },
    },
    [3716816003] = {
        ["english"] = { [1] = "Don't tell anyone else I said this, but even I don't know everything! If you want to keep learning, you should talk to the owner of the shop, Springspindle Fizzlegear." },
        ["text"] = "Нікому не кажи, що я це визнав, але навіть я знаю не все! Якщо хочеш учитися далі, поговори з власником крамниці, Спрінґспінделем Фіззлеґіром.",
        ["npcs"] = { [1] = 11029 },
        ["roles"] = { ["greeting"] = true },
    },
    [1676905923] = {
        ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Ironforge.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Ironforge for your duty and service.", [2] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Ironforge.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Ironforge for your duty and service.\010" },
        ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Залізогарт. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Альянсу.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Залізогарта.",
        ["npcs"] = { [1] = 15734, [2] = 15764 },
        ["roles"] = { ["greeting"] = true },
    },
    [3177901651] = {
        ["english"] = { [1] = "Elder Skygleam can be found near the Ravencrest Monument in Azshara." },
        ["text"] = "Старійшину Небосвіт можна знайти біля пам'ятника Воронячому Гребеню в Азшарі.",
        ["npcs"] = { [1] = 15595, [2] = 15598, [3] = 15603, [4] = 15605 },
        ["roles"] = { ["greeting"] = true },
    },
    [701024695] = {
        ["english"] = { [1] = "I am an officer of the city, working in the capacity of the Undercity's census.  Since our liberation from the Scourge, we have tried to keep an accurate track of our city's populace.  Through arcane methods and sharpened mental discipline, I am able to access these records.  If you have business with me accordingly, please proceed.  You should know if you do, at any rate." },
        ["text"] = "Я міський службовець і веду перепис населення Підміста. Відтоді як ми звільнилися від Скверни, ми намагаємося точно обліковувати мешканців міста. За допомогою арканічних методів і загостреної дисципліни розуму я можу звертатися до цих записів. Якщо у вас до мене справа саме з цього приводу — продовжуйте. Власне, ви й самі маєте знати, чи це так.",
        ["npcs"] = { [1] = 10781 },
        ["roles"] = { ["greeting"] = true },
    },
    [687951366] = {
        ["english"] = { [1] = "Finally, someone came down to talk to me! Want to hear some of my rhymes?" },
        ["text"] = "Нарешті хтось спустився поговорити зі мною! Хочеш послухати мої рими?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1348746964] = {
        ["english"] = { [1] = "I am so glad that you asked.  You will find Sir Malory Wheeler at the Royal Quarter in the presence of our Dark Lady." },
        ["text"] = "Радий, що питаєш. Сера Мелорі Вілера знайдеш у Королівському кварталі поруч із нашою Темною Пані.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1560261290] = {
        ["english"] = { [1] = "I am Aesom, third of the Triumvirate." },
        ["text"] = "Я Есом, третій із Тріумвірату.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1415567275] = {
        ["english"] = { [1] = "I am Adamant Ironheart of the great city of Ironforge. As you could probably guess by looking at my uniform, I was once part of the Ironforge elite guard. Yep, I was Magni's right hand man! At least until I retired. Now I dabble in archaeology. It's a hobby really; plus I figured it would be a great way to see the world!" },
        ["text"] = "Я Адамант Залізне Серце з великого міста Залізогарта. Як можна здогадатися з моєї уніформи, колись я служив в елітній варті Залізогарта. Ага, був правою рукою Маґні! Принаймні до виходу у відставку. Тепер потроху займаюся археологією. Це радше хобі, а ще я подумав, що так чудово побачу світ!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [968120162] = {
        ["english"] = { [1] = "Hmm... I think this year's Suntouched Special isn't so special afterall.  Wouldn't you agree, $N?" },
        ["text"] = "Гм... здається, цьогорічна «Сонцеторкнута особлива» вже не така й особлива. Хіба ні, $N?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [589353608] = {
        ["english"] = { [1] = "Greatfather Winter can be found in front of the Ironforge bank. The tree near him is where presents are given out." },
        ["text"] = "Дідуся Зиму можна знайти перед банком Залізогарта. Біля дерева поруч із ним роздають подарунки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2895820662] = {
        ["english"] = { [1] = "Greetings." },
        ["text"] = "Вітаю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3140044522] = {
        ["english"] = { [1] = "Gun" },
        ["text"] = "Рушниця",
        ["npcs"] = { [1] = 2704, [2] = 11866, [3] = 11867, [4] = 11868, [5] = 11870, [6] = 13084 },
        ["roles"] = { ["reply"] = true },
    },
    [3556568180] = {
        ["english"] = { [1] = "Duncan's Textiles employs one of the finest tailors in Stormwind, Georgio Bolero. Look for the shop over in the Mage Quarter." },
        ["text"] = "У «Тканинах Дункана» працює один із найкращих кравців Штормовію — Джорджіо Болеро. Шукай крамницю в Кварталі магів.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [3146331551] = {
        ["english"] = { [1] = "I am a night elf, stranger. While you may know nothing of my kind, we know much of you and your progenitors. You may not call yourself eredar but, in appearance, you share many similarities.$B$BYou have helped my allies, and for that I am thankful; but for the time being, you walk a tenuous path. Perhaps in time, you will be able to dissolve the doubts and fears that I hold in my heart." },
        ["text"] = "Я нічний ельф, чужинцю. Ти можеш нічого не знати про мій народ, але ми чимало знаємо про тебе й твоїх предків. Можливо, ти не називаєш себе ередаром, але зовні між вами багато спільного.$B$BТи допоміг моїм союзникам, і за це я вдячний; та поки що ступаєш крихким шляхом. Можливо, з часом тобі вдасться розвіяти сумніви й страхи в моєму серці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [422979031] = {
        ["english"] = { [1] = "Greetings, traveler. As long as you remain within the walls of the Cenarion Hold, you will be safe from harm.$B$BBe wary when leaving the protection of the Hold as the silithid have been swarming as of late." },
        ["text"] = "Вітаю, мандрівнику. Поки ти в межах мурів Кенарійської цитаделі, тобі нічого не загрожує.$B$BБудь обережний за межами її захисту — останнім часом силітиди рояться всюди.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1175099180] = {
        ["english"] = { [1] = "I am a master tailor, Omarion." },
        ["text"] = "Я майстер-кравець, Омаріоне.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [2773629920] = {
        ["english"] = { [1] = "Gorth is confused sometimes.  Gorth is good at killing people so Gorth is made sergeant.  But now Gorth never gets to kill nothing!" },
        ["text"] = "Ґорт інколи плутатися. Ґорт добре вбивати людей, тому Ґорт став сержант. Але тепер Ґорт ніколи нікого не вбивати!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1669748469] = {
        ["english"] = { [1] = "I am a master blacksmith, Omarion." },
        ["text"] = "Я майстер-коваль, Омаріоне.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [2448629915] = {
        ["english"] = { [1] = "Have you heard of the brood mother of the Black Flight? I believe she is called Onyxia..." },
        ["text"] = "Чув про матір виводка Чорної зграї? Здається, її звати Оніксія...",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["greeting"] = true },
    },
    [3398832840] = {
        ["english"] = { [1] = "Greetings, traveler." },
        ["text"] = "Вітаю, мандрівнику.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3304593058] = {
        ["english"] = { [1] = "Feeling underpowered" },
        ["text"] = "Бракує сили",
        ["npcs"] = { [1] = 10578 },
        ["roles"] = { ["reply"] = true },
    },
    [2084428223] = {
        ["english"] = { [1] = "Herbs... you need to speak to Jandi at her arboretum in The Drag.  There are some wooden steps behind Asoran's Market in the Valley of Wisdom.  Follow them to the upper level of The Drag and you'll find her." },
        ["text"] = "Трави... тобі треба поговорити з Джанді в її дендрарії в Хитрому провулку. Позаду ринку Асорана в Долині мудрості є дерев'яні сходи. Підіймися ними на верхній рівень Хитрого провулка — там її й знайдеш.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [769401621] = {
        ["english"] = { [1] = "Does my name sound familiar to you? Maybe we knew each other a long time ago...$B$BI think I'm named after someone important..." },
        ["text"] = "Моє ім'я здається вам знайомим? Можливо, ми знали одне одного дуже давно...$B$BГадаю, мене назвали на честь когось важливого...",
        ["npcs"] = { [1] = 8737 },
        ["roles"] = { ["greeting"] = true },
    },
    [868535934] = {
        ["english"] = { [1] = "Hello, $r. How can I help you today?" },
        ["text"] = "Привіт, $r. Чим можу допомогти сьогодні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3547072706] = {
        ["english"] = { [1] = "Hmm, well, I can see that you have a little skill at making potions. Whether you're worthy to be my student remains to be seen, however. I have a job for you. Impress me." },
        ["text"] = "Гм, бачу, ти трохи вмієш варити зілля. Але чи гідний стати моїм учнем — ще питання. У мене є для тебе робота. Врази мене.",
        ["npcs"] = { [1] = 1386 },
        ["roles"] = { ["greeting"] = true },
    },
    [3334331673] = {
        ["english"] = { [1] = "Fill yer tankard and pull up a chair. We've stories to tell and kegs to empty." },
        ["text"] = "Наповнюй кухоль і сідай ближче. У нас є історії, які треба розповісти, і барильця, які треба спорожнити.",
        ["npcs"] = { [1] = 1247, [2] = 1464, [3] = 5111, [4] = 6734, [5] = 7744 },
        ["roles"] = { ["greeting"] = true },
    },
    [3906808612] = {
        ["english"] = { [1] = "Funny you should ask... I just received an update on that. Thus far, the Alliance has gathered $2060w of $2061w light leather, $2063w out of $2064w medium leather and $2069w of $2071w thick leather skins." },
        ["text"] = "Добре, що питаєш... Я щойно отримав свіжі дані. Наразі Альянс зібрав $2060w із $2061w легкої шкіри, $2063w із $2064w середньої шкіри та $2069w із $2071w товстої шкіри.",
        ["npcs"] = { [1] = 15458 },
        ["roles"] = { ["greeting"] = true },
    },
    [2195295015] = {
        ["english"] = { [1] = "Food, now there's a subject that I can sink my fangs into! I am told that we have $2095w of $2096w lean wolf steaks, $2102w out of $2103w spotted yellowtail, and $2105w of $2106w baked salmon on ice and stored away." },
        ["text"] = "Їжа — ось тема, у яку я можу вп'ястися іклами! Кажуть, у нас є $2095w із $2096w пісних вовчих стейків, $2102w із $2103w плямистих жовтохвостів і $2105w із $2106w запечених лососів, охолоджених і складених на зберігання.",
        ["npcs"] = { [1] = 15700 },
        ["roles"] = { ["greeting"] = true },
    },
    [3601104501] = {
        ["english"] = { [1] = "Hey!  Thanks for saving my hide!  I think I'll be lying down for a while until I recover my strength." },
        ["text"] = "Гей! Дякую, що врятував мою шкуру! Полежу трохи, поки сили не повернуться.",
        ["npcs"] = { [1] = 15190 },
        ["roles"] = { ["greeting"] = true },
    },
    [838720108] = {
        ["english"] = { [1] = "Hah!  This tauren wants a kiss!" },
        ["text"] = "Ха! Цей таурен хоче поцілунка!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [929320058] = {
        ["english"] = { [1] = "Greetings, $N.", [2] = "Greetings, $N. " },
        ["text"] = "Вітаю, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [932881122] = {
        ["english"] = { [1] = "Hundreds of years ago, the great city of Thaurissan stood proudly in a lush expanse of land that is now the dilapidated Burning Steppes.$B$BThaurissan was home to the nation of Dark Iron dwarves and at the time, in the midst of a civil war among the dwarven nation at large.$B$BYou see, that area of the world was at one point in time part of the Redridge Mountains - until the day that Thaurissan was consumed by a gigantic explosion. The city lay in ruin, the surrounding areas reduced to an ashy wasteland.\010" },
        ["text"] = "Сотні років тому величне місто Тауріссан гордо стояло серед родючих земель, які нині перетворилися на занепалий Палаючий степ.$B$BТауріссан був домівкою народу дворфів Темного Заліза й тоді опинився в самому центрі громадянської війни серед усіх дворфів.$B$BКолись ця частина світу належала до Східногір'я — аж до дня, коли Тауріссан поглинув велетенський вибух. Місто лежало в руїнах, а навколишні землі перетворилися на попелясту пустку.\010",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["greeting"] = true },
    },
    [299037405] = {
        ["english"] = { [1] = "Hoary Templar! I hold your signet! Heed my call!" },
        ["text"] = "Сивий храмовнику! Я тримаю твою печатку! Почуй мій поклик!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [974881412] = {
        ["english"] = { [1] = "Elder Moonwarden is observing the Crossroads in the Barrens." },
        ["text"] = "Старійшина Місячний Вартовий спостерігає за Роздоріжжям у Степах.",
        ["npcs"] = { [1] = 15572, [2] = 15575, [3] = 15582, [4] = 15588, [5] = 15604 },
        ["roles"] = { ["greeting"] = true },
    },
    [4174888839] = {
        ["english"] = { [1] = "Give a bull a fish and feed him for a day.  Teach a bull to fish and feed him for life.  Uthan Stillwater can teach you how to fish.  Seek his wisdom west of Bloodhoof Village along the banks of Stonebull Lake." },
        ["text"] = "Дай бику рибу — нагодуєш його на день. Навчи бика рибалити — нагодуєш на все життя. Утан Тиховод навчить тебе рибальства. Шукай його мудрості на захід від селища Криваве Копито, на березі Кам'янобичачого озера.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [1049946844] = {
        ["english"] = { [1] = "Haha, you're back?  You don't seriously expect me to change my mind do you?$B$BGet lost." },
        ["text"] = "Ха-ха, ти знову? Невже серйозно думаєш, що я передумаю?$B$BЗабирайся.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2131965002] = {
        ["english"] = { [1] = "How many bandages have the Alliance collected so far?" },
        ["text"] = "Скільки бинтів уже зібрав Альянс?",
        ["npcs"] = { [1] = 15458, [2] = 15701 },
        ["roles"] = { ["reply"] = true },
    },
    [323225301] = {
        ["english"] = { [1] = "Hey, $gmister:miss;.  You look like a $C with discerning tastes in wine.  I have a favor to ask, and I think I can make you an offer you can't refuse...forget about it!" },
        ["text"] = "Гей, $gпане:пані;. Виглядаєш як $C із вишуканим смаком до вина. Маю прохання й, здається, можу зробити пропозицію, від якої ти не відмовишся... забудь про це!",
        ["npcs"] = { [1] = 1432 },
        ["roles"] = { ["greeting"] = true },
    },
    [2683797802] = {
        ["english"] = { [1] = "Don't they teach you new recruits anything?  These manaforges were built from parts of Tempest Keep designed to siphon energy from the nether.$B$BThe naaru used this technology to power their vessel during its travels.  Some said the technology might not be safe to use on land.  They were promptly silenced." },
        ["text"] = "Вас, новобранців, хіба нічого не вчать? Ці манакузні збудовано з частин Фортеці Бурі, призначених для висмоктування енергії з Крутоверті.$B$BНаару використовували цю технологію, щоб живити свій корабель у подорожах. Дехто казав, що на землі вона може бути небезпечною. Їх швидко змусили замовкнути.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2095359173] = {
        ["english"] = { [1] = "I almost made it!$B$BI came in here to prove the existence of Quagmirran, that most mythical of fungal giants.  I got my wish, sort of.$B$BYou must let me free!  In return I will grant you a boon to help you to deal with Quagmirran." },
        ["text"] = "Я майже дістався!$B$BЯ прийшов сюди, щоб довести існування Кваґмірана, того найміфічнішого з грибних велетнів. І, можна сказати, домігся свого.$B$BВи мусите мене звільнити! Натомість я дам вам благословення, яке допоможе впоратися з Кваґміраном.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [318220283] = {
        ["english"] = { [1] = "He'll bring you mead$bHe'll bring you beer$bA grinning face from ear to ear$bHe's served us all from year to year$bWe call him Smiling Jim." },
        ["text"] = "Він принесе тобі мед$bВін принесе тобі ель$bУсмішка від вуха до вуха$bВін служить нам рік за роком$bМи звемо його Усміхнений Джим.",
        ["npcs"] = { [1] = 4895 },
        ["roles"] = { ["greeting"] = true },
    },
    [1819474475] = {
        ["english"] = { [1] = "I almost have enough supplies to upgrade our troops." },
        ["text"] = "Мені майже вистачає припасів, щоб покращити наші війська.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1710474101] = {
        ["english"] = { [1] = "I allow the man to take enough corn to feed his family for a couple of days, encouraging him to leave the land." },
        ["text"] = "Я дозволяю чоловікові взяти достатньо кукурудзи, щоб годувати родину кілька днів, і заохочую його покинути ці землі.",
        ["npcs"] = { [1] = 14822 },
        ["roles"] = { ["reply"] = true },
    },
    [256843860] = {
        ["english"] = { [1] = "Have you come from the Burning Steppes?  Do you have my black dragon eggs?" },
        ["text"] = "Ти з Палаючого степу? Маєш мої яйця чорного дракона?",
        ["npcs"] = { [1] = 10432 },
        ["roles"] = { ["greeting"] = true },
    },
    [157350973] = {
        ["english"] = { [1] = "Hello, $c!  Are you reporting for a flight mission?" },
        ["text"] = "Привіт, $c! Ти на льотне завдання?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [995635004] = {
        ["english"] = { [1] = "I advise the captain on matters that he chooses to share with me, but I have a feeling that he'd rather hear from you." },
        ["text"] = "Я раджу капітанові в тих справах, якими він вирішує зі мною ділитися, але маю відчуття, що він радше вислухає тебе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1245304314] = {
        ["english"] = { [1] = "Gaze upon the enemy, $r. See what the might of the Horde reduces even the most powerful of dragons to! All that oppose us shall meet a similar fate!" },
        ["text"] = "Поглянь на ворога, $r. Дивися, до чого міць Орди доводить навіть найсильніших драконів! Така доля спіткає всіх, хто стане проти нас!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3207152335] = {
        ["english"] = { [1] = "Here in Ogri'la we have time to contemplate the riddle of steel. But enough of that, how can we help?" },
        ["text"] = "Тут, в Оґріла, ми маємо час розмірковувати над загадкою сталі. Але досить про це — чим допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2168647839] = {
        ["english"] = { [1] = "I admire the skill that torch jugglers have." },
        ["text"] = "Я захоплююся майстерністю жонглерів зі смолоскипами.",
        ["npcs"] = { [1] = 16781 },
        ["roles"] = { ["greeting"] = true },
    },
    [1201889045] = {
        ["english"] = { [1] = "Hello, Eitrigg. I bring news from Blackrock Spire." },
        ["text"] = "Привіт, Айтріґу. Я приніс звістки з Чорнокамінного Шпиля.",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["reply"] = true },
    },
    [2486693825] = {
        ["english"] = { [1] = "Hurry, $g brother : sister;. I'm leaking here...." },
        ["text"] = "Швидше, $g брате : сестро;. Я тут витікаю....",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1768393886] = {
        ["english"] = { [1] = "Do you? Perhaps you should tell me what it is that is bothering you." },
        ["text"] = "Справді? Можливо, вам варто розповісти, що саме вас турбує.",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["reply"] = true },
    },
    [3401910057] = {
        ["english"] = { [1] = "First Aid is always a nice skill to have.  Many a time during battle has it saved my hide.  Visit Spiritual Healing on the Spirit Rise.  Pand Stonebinder can teach you all you need to know to save your hide as well." },
        ["text"] = "Перша допомога — завжди корисна навичка. У бою вона не раз рятувала мені шкуру. Завітай до «Духовного зцілення» на Верхів'ї Духів. Панд Каменев'яз навчить усього, що треба, аби й ти рятував свою шкуру.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [673077324] = {
        ["english"] = { [1] = "Hello, overseer.  Ready for the attack?" },
        ["text"] = "Привіт, наглядачу. Готовий до атаки?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [545048292] = {
        ["english"] = { [1] = "Hunter" },
        ["text"] = "Мисливець",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 3084, [7] = 3212, [8] = 3215, [9] = 3217, [10] = 3218, [11] = 3219, [12] = 3220, [13] = 3221, [14] = 3222, [15] = 3223, [16] = 3224, [17] = 3296, [18] = 3571, [19] = 4262, [20] = 5595, [21] = 5953, [22] = 6272, [23] = 6740, [24] = 8931, [25] = 12996, [26] = 13076, [27] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [4096676418] = {
        ["english"] = { [1] = "Friendly" },
        ["text"] = "Дружелюбність",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["reply"] = true },
    },
    [586442197] = {
        ["english"] = { [1] = "Don't let me catch you stealing anything!  Look for Shenthul and his Shadowswift Brotherhood in the underground Cleft of Shadow.  Find the tunnel leading down into it south of the Valley of Wisdom." },
        ["text"] = "Щоб я не спіймав тебе на крадіжці! Шукай Шентула та його Братство Тіньового Кроку в підземній Розколині Тіні. Тунель до неї знайдеш на південь від Долини мудрості.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [2415596888] = {
        ["english"] = { [1] = "Enchanted thorium is a highly sought-after metal. You best chance of finding some of it is to speak with an artisan blacksmith or miner." },
        ["text"] = "Зачарований торій — дуже цінний метал. Найкраще запитати про нього майстра-коваля або гірника.",
        ["npcs"] = { [1] = 10304 },
        ["roles"] = { ["greeting"] = true },
    },
    [864571347] = {
        ["english"] = { [1] = "Greetings, $c.  I pity your kind, for the secrets of true magic are beyond you..." },
        ["text"] = "Вітаю, $c. Мені шкода ваш народ, адже таємниці справжньої магії вам недоступні...",
        ["npcs"] = { [1] = 5880, [2] = 5882, [3] = 5883, [4] = 5884, [5] = 5885, [6] = 7311 },
        ["roles"] = { ["greeting"] = true },
    },
    [2068518326] = {
        ["english"] = { [1] = "Enjoying the Fire Festival?" },
        ["text"] = "Подобається Свято Вогню?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1832563616] = {
        ["english"] = { [1] = "Elder Goldwell spends his time in the village of Kharanos in Dun Morogh." },
        ["text"] = "Старійшина Золоте Джерело проводить час у селищі Харанос у Дун-Морозі.",
        ["npcs"] = { [1] = 15558, [2] = 15567, [3] = 15871 },
        ["roles"] = { ["greeting"] = true },
    },
    [482274204] = {
        ["english"] = { [1] = "Good to see you again, $g man! : gorgeous!; We work well together; $g see you around. : I hope we get to continue to do so.;" },
        ["text"] = "Радий знову тебе бачити, $g друже! : красуне!; Ми добре працюємо разом; $g ще побачимось. : сподіваюся, ми ще попрацюємо разом.;",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1636331758] = {
        ["english"] = { [1] = "Hey citizen! You look like a stout one. We guards are spread a little thin out here, and I could use you help..." },
        ["text"] = "Гей, громадянине! На вигляд ти міцний. Нас, вартових, тут замало, і мені б не завадила твоя допомога...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1537714559] = {
        ["english"] = { [1] = "Heya Heya Heya!   If you want to test your fishing skills then I have just the place for you!   This Sunday we have a fishing tournament in Stranglethorn!\010\010" },
        ["text"] = "Гей-гей-гей! Якщо хочеш випробувати рибальські навички, я знаю саме місце! Цієї неділі в Тернистій долині відбудеться рибальський турнір!\010\010",
        ["npcs"] = { [1] = 15116 },
        ["roles"] = { ["greeting"] = true },
    },
    [3225953264] = {
        ["english"] = { [1] = "Hundreds of various diagrams and schematics begin to take shape on the pages of the book. You recognize some of the diagrams while others remain foreign but familiar." },
        ["text"] = "На сторінках книги починають проступати сотні різних креслень і схем. Деякі діаграми вам знайомі, інші здаються чужими, але дивно знайомими.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1047468409] = {
        ["english"] = { [1] = "Give me a couple minutes, $N. There was some excitement in here a moment ago, and I just want to make sure things have died back down. I'll talk to you soon enough." },
        ["text"] = "Дай мені кілька хвилин, $N. Тут щойно була невеличка метушня, хочу впевнитися, що все справді стихло. Скоро поговоримо.",
        ["npcs"] = { [1] = 4963 },
        ["roles"] = { ["greeting"] = true },
    },
    [1623141897] = {
        ["english"] = { [1] = "Huh?  You'll find the bank in Orgrimmar.  Head north up the road to get there and then talk to one of their grunts." },
        ["text"] = "Га? Банк знайдеш в Орґріммарі. Іди дорогою на північ, а там спитай когось із рубак.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [1272077262] = {
        ["english"] = { [1] = "Huh?  What?!  Go away." },
        ["text"] = "Га? Що?! Іди геть.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [534425904] = {
        ["english"] = { [1] = "Hail to thee $N.  Do you wish me to aid you in your journey to Warsong Gulch?" },
        ["text"] = "Вітаю тебе, $N. Бажаєш, щоб я допоміг тобі дістатися Ущелини Пісні Війни?",
        ["npcs"] = { [1] = 14981 },
        ["roles"] = { ["greeting"] = true },
    },
    [2546969144] = {
        ["english"] = { [1] = "Greetings, $r.$b$bMy shop is finally open. I hope you like what you see!" },
        ["text"] = "Вітаю, $r.$b$bМоя крамниця нарешті відкрита. Сподіваюся, тобі сподобається те, що побачиш!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2066361069] = {
        ["english"] = { [1] = "Elder Bronzebeard can be found in the ancestral home of the Bronzebeards, Ironforge." },
        ["text"] = "Старійшину Бронзобородого можна знайти в прабатьківському домі Бронзобородих — Залізогарті.",
        ["npcs"] = { [1] = 15562, [2] = 15567, [3] = 15569, [4] = 15598 },
        ["roles"] = { ["greeting"] = true },
    },
    [3250269763] = {
        ["english"] = { [1] = "Have you tried that Thunderbrew Lager?  It's good stuff!" },
        ["text"] = "Пробував лагер Громовара? Добряча річ!",
        ["npcs"] = { [1] = 9547 },
        ["roles"] = { ["greeting"] = true },
    },
    [2995542672] = {
        ["english"] = { [1] = "Heading home, $c? The Mighty Wind will get you there, if home's in Kalimdor. She flies straight from here to Durotar." },
        ["text"] = "Додому, $c? «Могутній Вітер» доправить тебе, якщо дім у Калімдорі. Він летить звідси просто в Дуротар.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2611935702] = {
        ["english"] = { [1] = "How?? Well, it's a long story." },
        ["text"] = "Як?? Ну, це довга історія.",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["greeting"] = true },
    },
    [4131327937] = {
        ["english"] = { [1] = "How's it going? I love the smell of leather; don't you?" },
        ["text"] = "Як справи? Я люблю запах шкіри, а ти?",
        ["npcs"] = { [1] = 1632 },
        ["roles"] = { ["greeting"] = true },
    },
    [415107107] = {
        ["english"] = { [1] = "How could the altar and the statues be related?" },
        ["text"] = "Як можуть бути пов'язані вівтар і статуї?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2833361709] = {
        ["english"] = { [1] = "Help!$B$BIf you get me out of here, I can blow up the door that leads to the chief of Zul'Farrak!" },
        ["text"] = "Допоможіть!$B$BЯкщо витягнете мене звідси, я підірву двері, що ведуть до ватажка Зул'Фаррака!",
        ["npcs"] = { [1] = 7607 },
        ["roles"] = { ["greeting"] = true },
    },
    [4247528834] = {
        ["english"] = { [1] = "How unfortunate; it would appear that we have collected all of the mageweave bandages necessary. Perhaps you can go sell them on the auction house? But before you go, be a good $g boy : girl; and check with the other collectors present. They may have an errand to send you off on." },
        ["text"] = "Шкода; схоже, ми вже зібрали всі потрібні бинти з маготканини. Може, продаси їх на аукціоні? Але перед цим будь хорошим $g хлопчиком : дівчинкою; і спитай інших збирачів тут. Можливо, у них знайдеться для тебе доручення.",
        ["npcs"] = { [1] = 15529 },
        ["roles"] = { ["greeting"] = true },
    },
    [3428957180] = {
        ["english"] = { [1] = "Hanashi here knows staves. If you want a sturdier instructor, go to Thunder Bluff. Ansekhwa will teach you on the lower central rise there." },
        ["text"] = "Ханаші знається на посохах. Якщо хочеш міцнішого наставника, вирушай до Громового Бескиду. Ансеква навчатиме тебе на нижньому центральному ярусі.",
        ["npcs"] = { [1] = 11868 },
        ["roles"] = { ["greeting"] = true },
    },
    [1734946501] = {
        ["english"] = { [1] = "How the hell did you get in there to begin with?", [2] = "How the hell did you get in there to begin with?\010" },
        ["text"] = "Як, у біса, ти взагалі туди потрапив?",
        ["npcs"] = { [1] = 10776 },
        ["roles"] = { ["reply"] = true },
    },
    [3561540028] = {
        ["english"] = { [1] = "For ages, I was lost.  Now, finally, I see how dark my soul had become..." },
        ["text"] = "Довгі віки я блукав у темряві. А тепер нарешті бачу, якою темною стала моя душа...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3849839773] = {
        ["english"] = { [1] = "How may I serve?" },
        ["text"] = "Чим можу служити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3517756615] = {
        ["english"] = { [1] = "How may I serve you?" },
        ["text"] = "Чим можу вам служити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3919923116] = {
        ["english"] = { [1] = "How may I help you?" },
        ["text"] = "Чим можу допомогти?",
        ["npcs"] = { [1] = 3079, [2] = 3881 },
        ["roles"] = { ["greeting"] = true },
    },
    [3498192803] = {
        ["english"] = { [1] = "Grumble, grumble..." },
        ["text"] = "Бур-бур...",
        ["npcs"] = { [1] = 9467 },
        ["roles"] = { ["greeting"] = true },
    },
    [1486892964] = {
        ["english"] = { [1] = "Don't think, $c.$b$bJust... do it...." },
        ["text"] = "Не думай, $c.$b$bПросто... зроби це....",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1680023058] = {
        ["english"] = { [1] = "Here to learn about potions? I've got plenty to teach you. I might be dead, but I haven't lost my brains. Yet." },
        ["text"] = "Прийшов учитися зіллям? Мені є чого тебе навчити. Я, може, й мертвий, але мізків ще не втратив. Поки що.",
        ["npcs"] = { [1] = 2132 },
        ["roles"] = { ["greeting"] = true },
    },
    [972907128] = {
        ["english"] = { [1] = "Hi there!$B$BSorry, friend, but only champions of Gnomeregan can buy what I've got." },
        ["text"] = "Привіт!$B$BВибач, друже, але купувати мій товар можуть лише чемпіони Ґномреґана.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1704925232] = {
        ["english"] = { [1] = "How many more supplies are needed to send ground assaults?" },
        ["text"] = "Скільки ще припасів потрібно для наземного наступу?",
        ["npcs"] = { [1] = 12096 },
        ["roles"] = { ["reply"] = true },
    },
    [2666662603] = {
        ["english"] = { [1] = "Hippogryph Master" },
        ["text"] = "Майстер гіпогрифів",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["reply"] = true },
    },
    [3586590239] = {
        ["english"] = { [1] = "I am Moordo, elder hunter of Stillpine." },
        ["text"] = "Я Мурдо, старший мисливець Тихохвоїх.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [541624602] = {
        ["english"] = { [1] = "Don't ask..." },
        ["text"] = "Не питай...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1439354161] = {
        ["english"] = { [1] = "Greetings, $N. Have you come to learn of the history of Ironforge?" },
        ["text"] = "Вітаю, $N. Прийшов дізнатися історію Залізогарта?",
        ["npcs"] = { [1] = 8879 },
        ["roles"] = { ["greeting"] = true },
    },
    [942638148] = {
        ["english"] = { [1] = "How many metal bars you say? As of my last update on the situation, here is what I know. The Horde has collected $2018w copper bars out of $1998w needed, $2005w tin bars out of $2006w and of $2009w mithril bars sought, $2008w have been gathered." },
        ["text"] = "Скільки зливків, кажеш? За останніми даними маю таку інформацію. Орда зібрала $2018w мідних зливків із потрібних $1998w, $2005w олов'яних із $2006w, а з потрібних $2009w мітрилових зливків зібрано $2008w.",
        ["npcs"] = { [1] = 15539 },
        ["roles"] = { ["greeting"] = true },
    },
    [996424830] = {
        ["english"] = { [1] = "Greetings, $r." },
        ["text"] = "Вітаю, $r.",
        ["npcs"] = { [1] = 11146 },
        ["roles"] = { ["greeting"] = true },
    },
    [673216165] = {
        ["english"] = { [1] = "Don't bother me, $c!  I have two whole cauldrons of bubbling brew here and I must ensure they taste just right!$B$BIf they don't, then Master Coren Direbrew will flay and boil me!" },
        ["text"] = "Не заважай мені, $c! Тут у мене два казани булькотливого варива, і я мушу стежити, щоб смак був як слід!$B$BА як ні, майстер Корен Худовар здере з мене шкіру й зварить живцем!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1203287708] = {
        ["english"] = { [1] = "Hello!  You're just the person I was looking for.  Take a seat and listen, because I have a plan that will make us both rich!" },
        ["text"] = "Привіт! Ти саме той, кого я шукав. Сідай і слухай, бо в мене є план, який зробить нас обох багатими!",
        ["npcs"] = { [1] = 9543 },
        ["roles"] = { ["greeting"] = true },
    },
    [2355284940] = {
        ["english"] = { [1] = "Hail, $c!  Welcome to the celebration!" },
        ["text"] = "Вітаю, $c! Ласкаво просимо на святкування!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [703860133] = {
        ["english"] = { [1] = "I am the leader of the Blood Watch defenses. What can I help you with?" },
        ["text"] = "Я очолюю оборону Кривавої застави. Чим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2779030178] = {
        ["english"] = { [1] = "How many metal bars have the Alliance collected so far?" },
        ["text"] = "Скільки металевих зливків уже зібрав Альянс?",
        ["npcs"] = { [1] = 15458, [2] = 15701 },
        ["roles"] = { ["reply"] = true },
    },
    [1564184721] = {
        ["english"] = { [1] = "Hail, champion. The tale of your deeds will be told throughout the ages. Perhaps one day, a statue of you will stand amongst the heroes of Stormwind." },
        ["text"] = "Вітаю, чемпіоне. Про твої подвиги говоритимуть упродовж віків. Можливо, одного дня твоя статуя стоятиме серед героїв Штормовію.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1526056489] = {
        ["english"] = { [1] = "Hazza'rah, the Dreamweaver.$B$BHis is the power of nightmares, and may his foes ever sleep.  $B$BHazza'rah now dwells far from here.  One day, he may return..." },
        ["text"] = "Газза'ра, Ткач Снів.$B$BЙому належить сила кошмарів, і нехай його вороги сплять вічно.  $B$BНині Газза'ра мешкає далеко звідси. Одного дня він може повернутися...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [13716886] = {
        ["english"] = { [1] = "How many leather skins have the Horde collected so far?" },
        ["text"] = "Скільки шкір уже зібрала Орда?",
        ["npcs"] = { [1] = 15539, [2] = 15700 },
        ["roles"] = { ["reply"] = true },
    },
    [830568918] = {
        ["english"] = { [1] = "Few around here are as skilled with a blade as Lyria Du Lac.  Check for her out behind the smithy and see if she's in the mood to teach you something new." },
        ["text"] = "Мало хто тут володіє клинком так майстерно, як Лірія Дю Лак. Пошукай її за кузнею — може, вона буде в настрої навчити тебе чогось нового.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [802704445] = {
        ["english"] = { [1] = "How may I be of service?" },
        ["text"] = "Чим можу прислужитися?",
        ["npcs"] = { [1] = 2858, [2] = 4551 },
        ["roles"] = { ["greeting"] = true },
    },
    [4145191499] = {
        ["english"] = { [1] = "How many herbs have the Horde collected so far?" },
        ["text"] = "Скільки трав уже зібрала Орда?",
        ["npcs"] = { [1] = 15539, [2] = 15700 },
        ["roles"] = { ["reply"] = true },
    },
    [3958524771] = {
        ["english"] = { [1] = "How many cooked goods have the Horde collected so far?" },
        ["text"] = "Скільки готової їжі вже зібрала Орда?",
        ["npcs"] = { [1] = 15539, [2] = 15700 },
        ["roles"] = { ["reply"] = true },
    },
    [3720564382] = {
        ["english"] = { [1] = "Hah!  Tirth's been looking for him for days, but he doesn't want to be found.  He's chicken!" },
        ["text"] = "Ха! Тірт шукає його вже кілька днів, але той не хоче, щоб його знайшли. Боягуз!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3444420878] = {
        ["english"] = { [1] = "Has the sun risen already?  There are just never enough hours in the night!  Well, Saelienne will take good care of you.  You can find her tending to her guests over in the Craftsmen's Terrace in northeastern Darnassus." },
        ["text"] = "Сонце вже зійшло? У ночі ніколи не вистачає годин! Що ж, Саелієнна добре про тебе подбає. Знайдеш її серед гостей на Ремісничій терасі в північно-східному Дарнасі.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [2369916921] = {
        ["english"] = { [1] = "I am dishonored. I should have died with the farseer at Magmoth." },
        ["text"] = "Я зганьблений. Мав загинути разом із провидцем у Маґмоті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3566572195] = {
        ["english"] = { [1] = "How dare you! Get out of my sight!" },
        ["text"] = "Як ти смієш! Геть із моїх очей!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1319199652] = {
        ["english"] = { [1] = "Greetings, $c.$B$BThe Alliance currently control Wintergrasp Fortress, but the battle has begun!  Hurry to Wintergrasp and support our forces!" },
        ["text"] = "Вітаю, $c.$B$BАльянс зараз контролює фортецю Зимохвату, але битва вже почалася! Поспішай до Зимохвату й підтримай наші сили!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1571454171] = {
        ["english"] = { [1] = "He... hello, $N. Sorry, I'm recovering from my wounds.$B$BThose Scarlet Crusaders are tougher than I had given them credit for. They almost did me in.$B$BYou should be careful too. I'd hate to see them get the jump on you." },
        ["text"] = "П-п-привіт, $N. Вибач, я ще оговтуюся від ран.$B$BТі Багряні Хрестоносці виявилися міцнішими, ніж я думав. Ледь мене не прикінчили.$B$BТи теж будь обережний. Не хотілося б, щоб вони застали тебе зненацька.",
        ["npcs"] = { [1] = 11610 },
        ["roles"] = { ["greeting"] = true },
    },
    [1053411064] = {
        ["english"] = { [1] = "I am a master leatherworker, Omarion." },
        ["text"] = "Я майстер-шкіряник, Омаріоне.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [2190995249] = {
        ["english"] = { [1] = "Drakes is my business, $N. I'm authorized to sell them to our highest ranking officers." },
        ["text"] = "Драки — моя справа, $N. Я маю дозвіл продавати їх нашим найвищим за рангом офіцерам.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [608075637] = {
        ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Orgrimmar.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Orgrimmar for your duty and service.\010", [2] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Orgrimmar.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Orgrimmar for your duty and service.\010\010" },
        ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Орґріммар. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Орди.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Орґріммара.\010",
        ["npcs"] = { [1] = 15736, [2] = 15765 },
        ["roles"] = { ["greeting"] = true },
    },
    [935314225] = {
        ["english"] = { [1] = "How is the edge of your steel? Good enough to cut through the belly of your enemy? Let me show you some things to make it even sharper." },
        ["text"] = "Наскільки гостра твоя сталь? Досить, щоб розпороти ворогові черево? Дозволь показати кілька прийомів, щоб зробити її ще гострішою.",
        ["npcs"] = { [1] = 4596 },
        ["roles"] = { ["greeting"] = true },
    },
    [1642581320] = {
        ["english"] = { [1] = "E'ko is da power dat each creatures possesses. Da charm I made for ya allows you ta capture it in a physical manifestation.$B$BI know an incantation dat can transform da e'ko you find, and turn it into juju.$B$BYou can den take the Cache of Mau'ari, an' use it ta reflect da power of da juju onto yourself.$B$BC'mon, give it a try. Bring da e'ko ta Mau'ari an' we have some fun." },
        ["text"] = "Е'ко — то сила, шо є в кожній істоті. Оберіг, шо я зробила для тебе, дає змогу вловити її у фізичній формі.$B$BЯ знаю закляття, шо може перетворити знайдене е'ко на джуджу.$B$BТоді береш Сховок Мау'арі й відбиваєш силою джуджу на себе.$B$BНу ж бо, спробуй. Принеси е'ко Мау'арі — повеселимося.",
        ["npcs"] = { [1] = 10307 },
        ["roles"] = { ["greeting"] = true },
    },
    [797655255] = {
        ["english"] = { [1] = "How I yearn to join you in glorious battle, but instead I am stuck here on duty. Go to the Hall of the Brave in Orgrimmar's Valley of Honor and speak to Kartra Bloodsnarl. She will help you get to Alterac Valley. Make us proud $N!" },
        ["text"] = "Як же я прагну приєднатися до тебе в славетній битві, але мушу стирчати тут на службі. Іди до Зали Відважних у Долині Честі Орґріммара й поговори з Картою Кривавий Рик. Вона допоможе тобі дістатися Альтерацької долини. Зроби нас гордими, $N!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1046551855] = {
        ["english"] = { [1] = "Don't be shy, buy a round for everyone!" },
        ["text"] = "Не соромтеся, пригостіть усіх по кухлю!",
        ["npcs"] = { [1] = 14844 },
        ["roles"] = { ["greeting"] = true },
    },
    [499478784] = {
        ["english"] = { [1] = "Hi there! We're being blockaded by those good-for-nothing pirates out in the bay! Do you think you can help us out by dropping a few bombs on them?!$B$BOur stolen zeppelin's less than $3078w minutes away.  Make sure you're onboard when she leaves!" },
        ["text"] = "Привіт! Ті нікчемні пірати в затоці взяли нас у блокаду! Допоможеш скинути на них кілька бомб?!$B$BНаш украдений дирижабль прибуде менш ніж за $3078w хвилин. Не проґав відправлення!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3015696936] = {
        ["english"] = { [1] = "Greetings, $N. My fellow Sons of Lothar and I have been stuck on this miserable world for close to twenty years now. We held on as best we could, but it still amazes me that the threats we face today are just the shadows of our past failures.$B$BPerhaps you will help us atone for them?  $B" },
        ["text"] = "Вітаю, $N. Ми з іншими Синами Лотара застрягли в цьому жалюгідному світі вже майже двадцять років. Ми трималися як могли, але мене досі вражає, що загрози, з якими ми боремося сьогодні, — лише тіні наших минулих невдач.$B$BМожливо, ти допоможеш нам їх спокутувати?  $B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [68367994] = {
        ["english"] = { [1] = "How else could this have happened? Someone must have tipped the Dark Irons off.$B$B<Kharan shakes his fist at you.>$B$BSo help me, if I ever get out of here, I will spend the rest of my days finding the traitor." },
        ["text"] = "Як іще це могло статися? Хтось мав попередити Темне Залізо.$B$B<Каран трясе перед вами кулаком.>$B$BКлянуся, якщо виберуся звідси, до кінця своїх днів шукатиму зрадника.",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["greeting"] = true },
    },
    [1275296405] = {
        ["english"] = { [1] = "How do you like the war, $n?  Just remember why we're here...that makes the fighting, and the dying, a lot easier." },
        ["text"] = "Ну як тобі війна, $n? Просто пам'ятай, навіщо ми тут... тоді і битися, і вмирати набагато легше.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [333950535] = {
        ["english"] = { [1] = "Happy Hallow's End!  How do you like my mask?  Very scary!" },
        ["text"] = "Щасливого Тиквовину! Ну як моя маска? Дуже страшна!",
        ["npcs"] = { [1] = 15354 },
        ["roles"] = { ["greeting"] = true },
    },
    [904866361] = {
        ["english"] = { [1] = "Hello, $c. These are troubling times indeed if this is what is to become of our beloved Quel'Thalas." },
        ["text"] = "Привіт, $c. Якщо ось це чекає на наш улюблений Квел'Талас, то часи справді тривожні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2193433070] = {
        ["english"] = { [1] = "Do you require an illusion?$B$BShould your illusion falter in the midst of your quest, return to me and I shall reapply the guise.$B$BShould you fail in your endeavors, do not give up! Return to me. I shall assist you until you have completed your objectives." },
        ["text"] = "Чи потрібна вам ілюзія?$B$BЯкщо під час вашого завдання ілюзія розвіється, поверніться до мене, і я знову накладу маскування.$B$BЯкщо зазнаєте невдачі, не здавайтеся! Поверніться до мене. Я допомагатиму вам, доки ви не виконаєте свої цілі.",
        ["npcs"] = { [1] = 11872 },
        ["roles"] = { ["greeting"] = true },
    },
    [1400747199] = {
        ["english"] = { [1] = "Greetings, $C.  If I might be so bold, may I remind you that -- while I attune myself to the magics of Hellfire Citadel -- there will undoubtedly be Hellfire wardens biting at my proverbial heels!$B$BSo, do be an upstanding member of your Horde and play the part of the hero... and protect me!" },
        ["text"] = "Вітаю, $C. Дозвольте нагадати: поки я налаштовуюся на магію Цитаделі Пекельного Вогню, вартові Пекельного Вогню неодмінно висітимуть у мене на п'ятах!$B$BТож будьте гідним представником Орди, зіграйте героя... і захистіть мене!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2207631025] = {
        ["english"] = { [1] = "Gubber, I don't have a fishing pole." },
        ["text"] = "Ґаббере, у мене немає вудки.",
        ["npcs"] = { [1] = 10216 },
        ["roles"] = { ["reply"] = true },
    },
    [3564075071] = {
        ["english"] = { [1] = "Every day is a test, and this day is no different. If you pass this test, I will share some of my knowledge..." },
        ["text"] = "Кожен день — випробування, і цей не виняток. Якщо пройдеш його, я поділюся частиною своїх знань...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2117018043] = {
        ["english"] = { [1] = "Hello, young $c. Are you here to bring me a batch of peacebloom? We are collecting them to make potions and elixirs for the Ahn'Qiraj war effort. Though tragic that we are forced into this war, the results will be even more terrible if we do not prepare properly.$B$BThe Horde has tasked me with the collection of $2020w peacebloom, and so far we've managed to put together $2021w. If you have it within your ability, please gather up all that you can and return them to me here." },
        ["text"] = "Привіт, юний $c. Приніс мені партію мироцвіту? Ми збираємо його для зіль та еліксирів на війну в Ан'Кіражі. Прикро, що нас змушують воювати, але наслідки будуть ще гіршими, якщо ми не підготуємося.$B$BОрда доручила мені зібрати $2020w мироцвіту, а поки ми назбирали $2021w. Якщо можеш, збери все, що знайдеш, і принеси сюди.",
        ["npcs"] = { [1] = 15477 },
        ["roles"] = { ["greeting"] = true },
    },
    [397240979] = {
        ["english"] = { [1] = "How do you compete with these pythons? Ooooooh yaaaaa, brother!" },
        ["text"] = "Як змагатися з такими пітонами? Ооооо так, брате!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [567715235] = {
        ["english"] = { [1] = "I am in need of training." },
        ["text"] = "Мені потрібне навчання.",
        ["npcs"] = { [1] = 3601 },
        ["roles"] = { ["reply"] = true },
    },
    [613075056] = {
        ["english"] = { [1] = "Greetings, $c.  I am Miranda Breechlock - one of but a few authorized equipment and materiel quartermasters for the Dawn.$B$BAs you fight evil under our commission - all the while earning our respect and trust - you'll earn valor tokens from Duke Zverenhoff.  Tokens serve two purposes: use them to gain increased standing within our ranks, or use them as tender in acquiring special items.$B$BAs you improve your standing with the Dawn, you'll discover that more items will be made available to you." },
        ["text"] = "Вітаю, $c. Я Міранда Брічлок — одна з небагатьох уповноважених інтендантів спорядження та припасів Світанку.$B$BБорючись зі злом за нашим дорученням і водночас здобуваючи нашу повагу та довіру, ви отримуватимете жетони доблесті від герцога Зверенгоффа. Жетони мають дві мети: ними можна підвищувати свій статус у наших лавах або розраховуватися за особливі предмети.$B$BЩо вищим буде ваш статус у Світанку, то більше предметів стане вам доступно.",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["greeting"] = true },
    },
    [3266989814] = {
        ["english"] = { [1] = "Friendly." },
        ["text"] = "Дружелюбність.",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["reply"] = true },
    },
    [1696374770] = {
        ["english"] = { [1] = "Greetings, $c. For some, the hunter is a way of life, a chosen profession. For others, it is something of a pastime, a badge of courage, or a rite of passage depending on your tribe.$B$BFor me, race and profession mean nothing--it is the testing of your spirit and mind that I respect. For one to stand against the forces of nature and test all of their skills is the true mark of honor.$B$BIf you wish to test yourself and earn my respect, then speak to me more." },
        ["text"] = "Вітаю, $c. Для когось мисливство — спосіб життя, обрана професія. Для інших — розвага, знак відваги або обряд посвяти, залежно від племені.$B$BДля мене раса й професія нічого не означають — я поважаю випробування духу й розуму. Вистояти проти сил природи й випробувати всі свої вміння — ось справжній знак честі.$B$BЯкщо хочеш випробувати себе й заслужити мою повагу, поговори зі мною ще.",
        ["npcs"] = { [1] = 9619 },
        ["roles"] = { ["greeting"] = true },
    },
    [2675746284] = {
        ["english"] = { [1] = "Greetings!  Do you need something?" },
        ["text"] = "Вітаю! Вам щось потрібно?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1546581269] = {
        ["english"] = { [1] = "Few bouts are won by sheer strength.  It is cunning, reflexes and knowledge of your weapon that wins the day in the end." },
        ["text"] = "Мало боїв виграють самою лише силою. Зрештою перемагають хитрість, реакція та знання своєї зброї.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3970638809] = {
        ["english"] = { [1] = "Goodbye." },
        ["text"] = "До побачення.",
        ["npcs"] = { [1] = 14348 },
        ["roles"] = { ["reply"] = true },
    },
    [3623130825] = {
        ["english"] = { [1] = "Good! I can tell that my efforts will not be wasted!" },
        ["text"] = "Добре! Бачу, мої зусилля не пропадуть марно!",
        ["npcs"] = { [1] = 1346, [2] = 4576 },
        ["roles"] = { ["greeting"] = true },
    },
    [3076844734] = {
        ["english"] = { [1] = "Greetings, $N.  We've travelled from Moonglade to spread the spirit of the Lunar Festival far and wide.$B$BWon't you join us in our celebration?" },
        ["text"] = "Вітаю, $N. Ми прибули з Місячної Галявини, щоб рознести дух Місячного фестивалю далеко й широко.$B$BПриєднаєшся до святкування?",
        ["npcs"] = { [1] = 15895 },
        ["roles"] = { ["greeting"] = true },
    },
    [1882578167] = {
        ["english"] = { [1] = "Excellent!  You shall be doing the League of Arathor a great service in ridding Arathi Basin of The Defilers and their Horde thugs.  Seek out the Lady Hoteshem in the royal audience chamber of Stormwind Keep.  She has been expecting you $N." },
        ["text"] = "Чудово! Ви дуже прислужитеся Лізі Аратора, очистивши Низину Араті від Осквернителів та їхніх головорізів з Орди. Знайдіть пані Готешем у королівській залі аудієнцій фортеці Штормовію. Вона чекає на вас, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4201152426] = {
        ["english"] = { [1] = "Good question, $c. Last I was informed; we have managed to collect $1997w copper bars out of $1998w needed. Additionally, I am told that we have $2002w iron bars out of $2003w, and $2011w out of $2012w thorium bars requested." },
        ["text"] = "Гарне питання, $c. За останніми даними ми зібрали $1997w із потрібних $1998w мідних зливків. Крім того, маємо $2002w із $2003w залізних зливків і $2011w із потрібних $2012w торієвих зливків.",
        ["npcs"] = { [1] = 15701 },
        ["roles"] = { ["greeting"] = true },
    },
    [2178875214] = {
        ["english"] = { [1] = "How do I form a guild?" },
        ["text"] = "Як створити гільдію?",
        ["npcs"] = { [1] = 3370, [2] = 4161, [3] = 4974, [4] = 5054, [5] = 5130 },
        ["roles"] = { ["reply"] = true },
    },
    [2340710306] = {
        ["english"] = { [1] = "Have you come seeking training in the ways of armed combat?" },
        ["text"] = "Прийшов навчатися збройного бою?",
        ["npcs"] = { [1] = 11867 },
        ["roles"] = { ["greeting"] = true },
    },
    [1300076856] = {
        ["english"] = { [1] = "Dwarves don't get drunk, $g mister:missy;. I'm just a little sloppy.$B$BAnyhow, Windsor? I figure he's somewhere in Blackrock Depths. That's the Dark Iron city for you unedumecated peoples." },
        ["text"] = "Дворфи не напиваються, $g пане:панночко;. Я просто трохи розхристаний.$B$BА щодо Віндзора? Гадаю, він десь у Глибинах Чорнокамінної гори. Це місто Темного Заліза — для таких неосвічених, як ви.",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [3610548955] = {
        ["english"] = { [1] = "Greetings.  If you are here for leather goods, then you will find my wares well crafted." },
        ["text"] = "Вітаю. Якщо вам потрібні шкіряні вироби, мої товари зроблено на совість.",
        ["npcs"] = { [1] = 8359 },
        ["roles"] = { ["greeting"] = true },
    },
    [3175228697] = {
        ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of the Darkspear tribe.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from the Darkspear tribe for your duty and service.\010" },
        ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє плем'я Темного Списа. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Орди.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання племені Темного Списа.\010",
        ["npcs"] = { [1] = 15737, [2] = 15761 },
        ["roles"] = { ["greeting"] = true },
    },
    [2388112038] = {
        ["english"] = { [1] = "Emerald Drakes excel at healing themselves while poisoning their enemies.$B$BUsing Leeching Poison, they can steal health from their enemies.  Repeated applications of this poison can increase the effect.$B$BWith Touch the Nightmare, Emerald Drakes can reach into the Dream, converting a portion of their life energy into a highly damaging attack that leaves the target weakened, reducing its damage for a short time." },
        ["text"] = "Смарагдові драки чудово зцілюють себе, водночас отруюючи ворогів.$B$BЗа допомогою «Висмоктувальної отрути» вони можуть красти здоров'я у ворогів. Повторні застосування цієї отрути посилюють ефект.$B$B«Дотиком Кошмару» смарагдові драки можуть сягнути Сну, перетворюючи частину своєї життєвої сили на потужну атаку, що послаблює ціль і на короткий час зменшує її шкоду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [452165146] = {
        ["english"] = { [1] = "How do I do that?" },
        ["text"] = "Як це зробити?",
        ["npcs"] = { [1] = 14469 },
        ["roles"] = { ["reply"] = true },
    },
    [1120265174] = {
        ["english"] = { [1] = "Here you go, $g lad : lass;. Make 'em count!" },
        ["text"] = "Ось, $g хлопче : дівчино;. Не змарнуй їх!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1104146787] = {
        ["english"] = { [1] = "Find Kaplak on top of the burrow in the southwest section of town." },
        ["text"] = "Знайди Каплака на вершині нори в південно-західній частині міста.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [3597742016] = {
        ["english"] = { [1] = "How did you know? I mean, yes... Yes I am looking for that shard. Do you have it?" },
        ["text"] = "Як ти дізнався? Тобто... так. Так, я шукаю той уламок. Він у тебе?",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [695283997] = {
        ["english"] = { [1] = "Hey there, $c. We're in the middle of a battle here." },
        ["text"] = "Привіт, $c. Ми тут посеред битви.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1349586996] = {
        ["english"] = { [1] = "Greetings!  If you are here to access goblin engineering schemata, please have your goblin engineer membership card ready for verification." },
        ["text"] = "Вітаю! Якщо ви прийшли по схеми гоблінської інженерії, приготуйте членську картку гоблінського інженера для перевірки.",
        ["npcs"] = { [1] = 8738 },
        ["roles"] = { ["greeting"] = true },
    },
    [3006864388] = {
        ["english"] = { [1] = "Greetings, $c. I am Leoren, stable master of Cenarion Hold." },
        ["text"] = "Вітаю, $c. Я Леорен, наглядач стаєнь Кенарійської цитаделі.",
        ["npcs"] = { [1] = 15722 },
        ["roles"] = { ["greeting"] = true },
    },
    [2007747347] = {
        ["english"] = { [1] = "Elder Proudhorn is enjoying the vistas above Mulgore at Thunder Bluff." },
        ["text"] = "Старійшина Гордий Ріг милується краєвидами Мулґору з Громового Бескиду.",
        ["npcs"] = { [1] = 15564, [2] = 15575, [3] = 15579, [4] = 15582 },
        ["roles"] = { ["greeting"] = true },
    },
    [2792836422] = {
        ["english"] = { [1] = "Genius is often misunderstood, $r. Now, about the scepter shard... If you want that shard and do not wish to spend the next ten thousand years searching for it, you are going to have to listen very carefully." },
        ["text"] = "Геніїв часто не розуміють, $r. А тепер про уламок скіпетра... Якщо хочеш його отримати й не бажаєш шукати наступні десять тисяч років, слухай дуже уважно.",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [1445854369] = {
        ["english"] = { [1] = "Have you seen the Headless Horseman?  The matron says if I look at him, then he'll turn me into a pumpkin!" },
        ["text"] = "Бачив Вершника без Голови? Матрона каже, що якщо я на нього подивлюся, він перетворить мене на гарбуз!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1904626904] = {
        ["english"] = { [1] = "How wonderful to see another person in this remote region of the world. Come, walk with me. Let our bodies keep each other warm." },
        ["text"] = "Як чудово побачити ще когось у такому віддаленому куточку світу. Ходімо, прогуляйся зі мною. Зігріймо одне одного.",
        ["npcs"] = { [1] = 14531 },
        ["roles"] = { ["greeting"] = true },
    },
    [1148433489] = {
        ["english"] = { [1] = "Gorzeeki tells me that you have brought him all that he needs for the Bell of Dethmoora, the Wheel of the Black March and the Doomsday Candle.$B$BWell done, $N!  You are almost ready to perform your ritual and bind a dreadsteed!" },
        ["text"] = "Ґорзікі каже, що ти приніс усе потрібне для Дзвона Детмури, Колеса Чорного Походу та Свічки Судного Дня.$B$BЧудово, $N! Ти майже готовий провести ритуал і підкорити жахонога!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4027553437] = {
        ["english"] = { [1] = "Glumrggl?" },
        ["text"] = "Ґлумрґґл?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2914636603] = {
        ["english"] = { [1] = "How can we help you?" },
        ["text"] = "Чим ми можемо допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4090002474] = {
        ["english"] = { [1] = "Forgetting your skill in Transmutation Mastery is not something to do lightly.$B$BAre you absolutely sure?" },
        ["text"] = "Відмова від майстерності трансмутації — серйозний крок.$B$BТи цілком упевнений?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [699037205] = {
        ["english"] = { [1] = "How can I work under these conditions?! And all of these disgusting Forsaken around here! I weep for Tranquillien and Quel'Thalas!" },
        ["text"] = "Як я маю працювати в таких умовах?! І всі ці гидкі Відречені навколо! Серце болить за Транквіліон і Квел'Талас!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2162671499] = {
        ["english"] = { [1] = "Have you danced at the ribbon pole yet?" },
        ["text"] = "Ти вже танцював біля стрічкового стовпа?",
        ["npcs"] = { [1] = 16781 },
        ["roles"] = { ["greeting"] = true },
    },
    [2796607732] = {
        ["english"] = { [1] = "Have you seen the befouled water elementals in our lake, $N? It is a sorry sight, but I do not know where they are coming from.$B$BYour name has been mentioned in conversations past, perhaps you could help me with this problem.$B$BThe first thing we must learn is who is in control of these elementals." },
        ["text"] = "Бачив осквернених водяних елементалів у нашому озері, $N? Видовище сумне, але я не знаю, звідки вони беруться.$B$BТвоє ім'я вже звучало в попередніх розмовах, можливо, допоможеш розібратися.$B$BСпершу треба з'ясувати, хто керує цими елементалями.",
        ["npcs"] = { [1] = 3885 },
        ["roles"] = { ["greeting"] = true },
    },
    [1022414218] = {
        ["english"] = { [1] = "Have a spare bunch of bananas?" },
        ["text"] = "Є зайва в'язка бананів?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [224986034] = {
        ["english"] = { [1] = "How can I share my secrets with a beginner? Try speaking with Victor Ward first." },
        ["text"] = "Як я можу ділитися таємницями з новачком? Спочатку поговори з Віктором Вардом.",
        ["npcs"] = { [1] = 11049 },
        ["roles"] = { ["greeting"] = true },
    },
    [1242354947] = {
        ["english"] = { [1] = "Glory to the naaru, $N.  The Light will soon triumph over its enemies." },
        ["text"] = "Слава наару, $N. Світло незабаром переможе своїх ворогів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [298853482] = {
        ["english"] = { [1] = "Godan's Runeworks is where you'll go.  Look for it on the west end of The Drag, right next to the Valley of Wisdom." },
        ["text"] = "Тобі до «Рунних робіт Ґодана». Шукай їх у західній частині Хитрого провулка, просто біля Долини мудрості.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [3650961572] = {
        ["english"] = { [1] = "I am in charge of recruitment for the Frostwolf Clan. As a soldier of Frostwolf, it is your responsibility to check in with me as your rank among the clan rises.$B$BHonor and respect are earned on this frigid field." },
        ["text"] = "Я відповідаю за набір до клану Морозних Вовків. Як солдат Морозних Вовків, ти маєш приходити до мене, коли зростає твій ранг у клані.$B$BЧесть і повага заробляються на цьому крижаному полі.",
        ["npcs"] = { [1] = 13840 },
        ["roles"] = { ["greeting"] = true },
    },
    [2548137179] = {
        ["english"] = { [1] = "How are your travels, $N? $g Sumi and Tumi missed you, you should say hi after your lesson : I have heard tales of your adventures, sounds like you have been busy;. Now let's see what you've learned while you were away." },
        ["text"] = "Як мандри, $N? $g Сумі й Тумі сумували за тобою, привітайся після уроку : Я чув історії про твої пригоди — схоже, часу ти не марнував;. А тепер побачимо, чого ти навчився за цей час.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2626532443] = {
        ["english"] = { [1] = "How can I help you, $c?" },
        ["text"] = "Чим можу допомогти, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1233630989] = {
        ["english"] = { [1] = "Hey Bly!  Bilgewizzle wants his divino-matic rod back!" },
        ["text"] = "Гей, Блай! Білджвіззл хоче свій дивіноматичний жезл назад!",
        ["npcs"] = { [1] = 7604 },
        ["roles"] = { ["reply"] = true },
    },
    [52121232] = {
        ["english"] = { [1] = "Expertly accomplished! Now, let us continue your education..." },
        ["text"] = "Виконано майстерно! А тепер продовжмо твоє навчання...",
        ["npcs"] = { [1] = 3704 },
        ["roles"] = { ["greeting"] = true },
    },
    [2298352000] = {
        ["english"] = { [1] = "For 10,000 years I have ruled this kingdom. In that time, I have heard many fascinating tales from those that would walk the hallowed grounds of the House of Shen'dralar.$B$BAs I am bound to this place, I often exchange stories with visitors. Do you have a story for me or perhaps you would like to hear a story?" },
        ["text"] = "Десять тисяч років я правлю цим королівством. За цей час я почув безліч захопливих історій від тих, хто ступав священними землями дому Шен'дралар.$B$BЯ прив'язаний до цього місця, тож часто обмінююся історіями з відвідувачами. Маєш історію для мене чи, можливо, хочеш почути одну?",
        ["npcs"] = { [1] = 11486 },
        ["roles"] = { ["greeting"] = true },
    },
    [667206122] = {
        ["english"] = { [1] = "Gawurgggl! Blrgl-brgl grgl!" },
        ["text"] = "Ґавурррґл! Блрґл-брґл ґрґл!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1412709125] = {
        ["english"] = { [1] = "How are we ever going to get out of here?" },
        ["text"] = "Як ми взагалі звідси виберемося?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2128462393] = {
        ["english"] = { [1] = "Don't listen to the hearts of the world - the answer lies within.  You know the truth." },
        ["text"] = "Не слухай сердець світу — відповідь усередині. Ти знаєш правду.",
        ["npcs"] = { [1] = 11801 },
        ["roles"] = { ["greeting"] = true },
    },
    [2629319102] = {
        ["english"] = { [1] = "Glacial Gloves." },
        ["text"] = "Льодовикові рукавиці.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [3915800727] = {
        ["english"] = { [1] = "Horrifying." },
        ["text"] = "Жахливо.",
        ["npcs"] = { [1] = 10740 },
        ["roles"] = { ["reply"] = true },
    },
    [297713621] = {
        ["english"] = { [1] = "Hope you're not looking for those abominations. The apothecaries can't be trusted, and that means none of their little constructs patrolling the halls. We're here to keep things safe." },
        ["text"] = "Сподіваюся, ти не шукаєш тих мерзотищ. Аптекарям не можна довіряти, а значить і їхнім дрібним конструкціям, що тиняються коридорами. Ми тут, щоб підтримувати безпеку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3198417074] = {
        ["english"] = { [1] = "Elder Brightspear can be found wandering amongst the ruins of Kel'Theril in Winterspring." },
        ["text"] = "Старійшина Яскравий Спис мандрує серед руїн Кел'Теріла в Зимоключі.",
        ["npcs"] = { [1] = 15574, [2] = 15603 },
        ["roles"] = { ["greeting"] = true },
    },
    [3176209791] = {
        ["english"] = { [1] = "Greetings, $c.  It is the time of the Harvest Festival - a time of great bounties and a time of remembrance.  We partake of feasts to celebrate all we have to be thankful of, and we remember our ancestors and past heroes to give thanks to the legacy they gave us.$B$BPlease feel free to partake of the feast being offered here.  Also, I am offering some fireworks to help celebrate this joyous time of year." },
        ["text"] = "Вітаю, $c. Настав час Свята Врожаю — час великих дарів і пам'яті. Ми бенкетуємо, дякуючи за все, що маємо, і згадуємо предків та героїв минулого, вшановуючи спадок, який вони нам залишили.$B$BПригощайтеся на бенкеті. Також я роздаю феєрверки, щоб допомогти відсвяткувати цю радісну пору року.",
        ["npcs"] = { [1] = 15011, [2] = 15012 },
        ["roles"] = { ["greeting"] = true },
    },
    [1044501948] = {
        ["english"] = { [1] = "Hope you take it to big-tongues good. It about time they go away." },
        ["text"] = "Сподіваюся, ти добре провчиш тих великоязиких. Давно час їм забиратися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2929931750] = {
        ["english"] = { [1] = "Hello, $N." },
        ["text"] = "Привіт, $N.",
        ["npcs"] = { [1] = 11835 },
        ["roles"] = { ["greeting"] = true },
    },
    [2650266000] = {
        ["english"] = { [1] = "Honored." },
        ["text"] = "Повага.",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["reply"] = true },
    },
    [109534005] = {
        ["english"] = { [1] = "Honored" },
        ["text"] = "Повага",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["reply"] = true },
    },
    [3948439760] = {
        ["english"] = { [1] = "Hey mon! You've ever been diving deep in the ocean? I'll let you in on a little secret, eh. Deep in the ocean you can find bubbly fissures; they'll allow you to breathe air while underwater.  Let's keep this secret between you and me though, eh. I don't need no competition for me shellfish traps elsewhere... if you get my drift!\010" },
        ["text"] = "Гей, мон! Колись пірнав глибоко в океані? Відкрию маленьку таємницю. На великій глибині трапляються бульбашкові тріщини — біля них можна дихати під водою. Але хай це лишиться між нами, гаразд? Мені не потрібні конкуренти біля пасток на молюсків... розумієш, до чого я?\010",
        ["npcs"] = { [1] = 11317 },
        ["roles"] = { ["greeting"] = true },
    },
    [3484488801] = {
        ["english"] = { [1] = "I am blessed to be able to help someone of your skills to learn more of Jewelcrafting. What do you wish to know?" },
        ["text"] = "Для мене благословення допомагати комусь із твоїм рівнем майстерності пізнавати ювелірну справу. Що хочеш знати?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1358682051] = {
        ["english"] = { [1] = "Honor and praise will be yours for the taking $c!  Look for Kurden Bloodclaw in this city's Royal Quarter." },
        ["text"] = "Честь і слава чекають на тебе, $c! Шукай Курдена Кривавого Кігтя в Королівському кварталі цього міста.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [13266686] = {
        ["english"] = { [1] = "Have you not heard of Ysera? Guardian of nature? Aspect of the Dream? She is the matron of all green dragons! Aye, it was Ysera herself that gifted my kingdom with her brood. We stood shoulder to shoulder with the noble creatures and they allowed us to ride them into battle against our enemies. All was well for many centuries... until..." },
        ["text"] = "Хіба ти не чув про Ізеру? Хранительку природи? Аспект Сну? Вона матір усіх зелених драконів! Так, сама Ізера подарувала моєму королівству свій виводок. Ми билися пліч-о-пліч із цими шляхетними створіннями, і вони дозволяли нам верхи вступати в бій проти ворогів. Так тривало багато століть... аж поки...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1863179070] = {
        ["english"] = { [1] = "Greetings, $N. I am Johnny McWeaksauce. I am used as a tool by developers to carry out specific functions for the purpose of testing. For this test period, I am set to do two specific things:$B$B(1) Flag you as having done the Naxxramas attunement quest so that you are able to accept the next quest, \"Echoes of War\" from Commander Eligor Dawnbringer. You must first complete that quest to be able to access the quests for your Tier 3 armor set.$B$B(2) Teleport you to Naxxramas.$B$BWhat is it that you require?" },
        ["text"] = "Вітаю, $N. Я Джонні МакСлабак. Розробники використовують мене як інструмент для виконання певних функцій під час тестування. На цей тестовий період мені призначено дві конкретні функції:$B$B(1) Позначити, що ти виконав завдання налаштування на Наксрамас, щоб ти міг прийняти наступне завдання «Відлуння війни» від командира Еліґора Світанконосця. Спершу треба виконати це завдання, щоб отримати доступ до завдань на комплект обладунків 3-го рівня.$B$B(2) Телепортувати тебе до Наксрамаса.$B$BЩо тобі потрібно?",
        ["npcs"] = { [1] = 16999 },
        ["roles"] = { ["greeting"] = true },
    },
    [3873740940] = {
        ["english"] = { [1] = "Hey mon, you be here ta bring me mithril bars no doubt. There be big trouble brewin' in the Silithus desert at Ahn'Qiraj. We and the Alliance goin' all out this time to stop them bugs, and that be why you seein' everyone here.$B$BThe Horde be askin' me to collect $2009w for the war effort, but I only have $2008w. So ya gonna help me out, or what?" },
        ["text"] = "Гей, мон, ти сюди принести мені мітрилові зливки, без сумніву. У пустелі Силітусу, в Ан'Кіражі, назрівають великі проблеми. Ми з Альянсом цього разу викладаємося на повну, щоб зупинити тих жуків, от чого тут стільки народу.$B$BОрда просить мене зібрати $2009w для війни, а маю лише $2008w. То допоможеш чи як?",
        ["npcs"] = { [1] = 15469 },
        ["roles"] = { ["greeting"] = true },
    },
    [1934702117] = {
        ["english"] = { [1] = "I always be up for a nice three-finger discount. Stealin' be all in the wrist... and when that fails ya, then ya stick somethin' sharp in between the ribs, and that's all in the wrist too.$B$BSkilled hands be worth more than a steady paycheck, ya heard?" },
        ["text"] = "Я завжди за добру знижку на три пальці. Красти — усе в зап'ясті... а коли це не працює, встромляєш щось гостре між ребра — і це теж усе в зап'ясті.$B$BУмілі руки варті більше за стабільну платню, чуєш?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2682834294] = {
        ["english"] = { [1] = "Honor to your house and ancestors $c!  You will find Kartra Bloodsnarl inside the Hall of the Brave in the Valley of Honor." },
        ["text"] = "Честь твоєму дому й предкам, $c! Карту Кривавий Рик знайдеш у Залі Відважних у Долині Честі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3715690900] = {
        ["english"] = { [1] = "I am curious to see what a bucket of bolts has to offer." },
        ["text"] = "Цікаво побачити, що може запропонувати це відро з болтами.",
        ["npcs"] = { [1] = 12245 },
        ["roles"] = { ["reply"] = true },
    },
    [4138374041] = {
        ["english"] = { [1] = "Existing in this area are many creatures considered allies of the night elves. The elves have had access to the power within each of these creatures; it is time that the horde be allowed this same satisfaction. I have devised a way that this power can be captured and used for our benefit.$B$BDo not doubt what I tell you, $N. Help me, and you shall see that I speak truth." },
        ["text"] = "У цих краях мешкає чимало істот, яких вважають союзниками нічних ельфів. Ельфи давно користуються силою цих створінь; настав час, щоб і Орда отримала таку ж можливість. Я винайшов спосіб захопити цю силу й використати її на нашу користь.$B$BНе сумнівайся в моїх словах, $N. Допоможи мені — і побачиш, що я кажу правду.",
        ["npcs"] = { [1] = 8115 },
        ["roles"] = { ["greeting"] = true },
    },
    [2664214604] = {
        ["english"] = { [1] = "Have you come for further training? Shake the dust of the road from your garments, then, and let us get to work." },
        ["text"] = "Прийшов на подальше навчання? Тоді обтруси дорожній пил з одягу — і до роботи.",
        ["npcs"] = { [1] = 3703 },
        ["roles"] = { ["greeting"] = true },
    },
    [1107042949] = {
        ["english"] = { [1] = "Every two years the Spirits of Competition grow especially fervent... and now is that time! We wear this tabard into the Battlegrounds to honor them, seeking to defeat our enemies and earn their favor." },
        ["text"] = "Раз на два роки Духи Змагання стають особливо завзятими... і цей час настав! Ми вдягаємо цю гербову накидку на полях бою, щоб ушанувати їх, перемогти ворогів і здобути їхню прихильність.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2644381939] = {
        ["english"] = { [1] = "Hmm... you show a little promise, I'll give you that. Okay then, where were we?" },
        ["text"] = "Гм... певні задатки є, визнаю. Гаразд, на чому ми зупинилися?",
        ["npcs"] = { [1] = 5153 },
        ["roles"] = { ["greeting"] = true },
    },
    [322516527] = {
        ["english"] = { [1] = "Elortha no Shadra$BGod of Spiders, Mother of Venom, Silk Dancer, Death's Love." },
        ["text"] = "Елорта но Шадра$BБогиня Павуків, Матір Отрути, Танцівниця Шовку, Кохана Смерті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [815176960] = {
        ["english"] = { [1] = "Eunice Burch sell leftover parts.  You find her in Trade Quarter." },
        ["text"] = "Юніс Берч продає зайві частини. Знайдеш її в Торговому кварталі.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1355413031] = {
        ["english"] = { [1] = "Greetings young rogue. What do you seek?" },
        ["text"] = "Вітаю, юний розбійнику. Чого шукаєш?",
        ["npcs"] = { [1] = 917, [2] = 1234, [3] = 3594 },
        ["roles"] = { ["greeting"] = true },
    },
    [4121034198] = {
        ["english"] = { [1] = "I am certain there is a Tailor that could provide you training in Darnassus.  When you arrive, ask one of the Sentinels in Darnassus about seeing a Tailor." },
        ["text"] = "Я певен, у Дарнасі знайдеться кравець, який зможе тебе навчити. Коли прибудеш, спитай когось із Вартових Дарнаса, де знайти кравця.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [2870077063] = {
        ["english"] = { [1] = "Greetings, $N. Proceed with caution..." },
        ["text"] = "Вітаю, $N. Будь обережний...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4081251776] = {
        ["english"] = { [1] = "Hello, young $r." },
        ["text"] = "Привіт, юний $r.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [465321195] = {
        ["english"] = { [1] = "Greetings, $c. I can assist you in recovering lost companions." },
        ["text"] = "Вітаю, $c. Я можу допомогти повернути втрачених супутників.",
        ["npcs"] = { [1] = 6749, [2] = 9976, [3] = 9977, [4] = 9978, [5] = 9979, [6] = 9980, [7] = 9981, [8] = 9982, [9] = 9983, [10] = 9984, [11] = 9985, [12] = 9986, [13] = 9987, [14] = 9988, [15] = 9989, [16] = 10045, [17] = 10046, [18] = 10047, [19] = 10048, [20] = 10049, [21] = 10050, [22] = 10051, [23] = 10052, [24] = 10053, [25] = 10054, [26] = 10055, [27] = 10056, [28] = 10057, [29] = 10058, [30] = 10059, [31] = 10060, [32] = 10061, [33] = 10062, [34] = 10063, [35] = 10085, [36] = 11069, [37] = 11104, [38] = 11105, [39] = 11117, [40] = 11119, [41] = 13616, [42] = 15131, [43] = 16094 },
        ["roles"] = { ["greeting"] = true },
    },
    [4056240451] = {
        ["english"] = { [1] = "Hail, Loramus. I bring word from the Blasted Lands." },
        ["text"] = "Вітаю, Лорамусе. Я приніс звістки зі Спустошених земель.",
        ["npcs"] = { [1] = 7783 },
        ["roles"] = { ["reply"] = true },
    },
    [48412892] = {
        ["english"] = { [1] = "Fascinating, Lorekeeper. Continue please." },
        ["text"] = "Захопливо, хранителю знань. Продовжуйте.",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["reply"] = true },
    },
    [3985565475] = {
        ["english"] = { [1] = "Exactly!" },
        ["text"] = "Саме так!",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [1951594062] = {
        ["english"] = { [1] = "Elder Fargal looks over Frosthold in Storm Peaks." },
        ["text"] = "Старійшина Фарґал споглядає Морозну Твердиню в Грозових вершинах.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1658626148] = {
        ["english"] = { [1] = "Elder Darkcore can be found in the Undercity." },
        ["text"] = "Старійшину Темне Ядро можна знайти в Підмісті.",
        ["npcs"] = { [1] = 15568, [2] = 15579, [3] = 15580, [4] = 15594 },
        ["roles"] = { ["greeting"] = true },
    },
    [3236096241] = {
        ["english"] = { [1] = "I am a treasure hunter in search of powerful artifacts. Give them to me and you will not be harmed." },
        ["text"] = "Я мисливець за скарбами й шукаю могутні артефакти. Віддай їх мені — і не постраждаєш.",
        ["npcs"] = { [1] = 6109 },
        ["roles"] = { ["reply"] = true },
    },
    [2877483645] = {
        ["english"] = { [1] = "Hmm, your work is allright but it's nowhere near the quality I look for in a student. Go talk with Smith Argus in Goldshire, I'm sure he can teach you some basics. Then when you're done, come on back to me and I'll give you a little test to make sure you are ready." },
        ["text"] = "Гм, робота непогана, але до якості, яку я чекаю від учня, ще далеко. Поговори з ковалем Арґусом у Золотозем'ї, він навчить тебе основ. А потім повертайся — дам невелике випробування й перевірю, чи готовий.",
        ["npcs"] = { [1] = 3136 },
        ["roles"] = { ["greeting"] = true },
    },
    [3373712249] = {
        ["english"] = { [1] = "Herbalism requires a gentle touch that few such as Malorne can teach.  Seek him out east of the Inn in Dolanaar." },
        ["text"] = "Травництво потребує ніжного дотику, якому мало хто навчить так, як Малорн. Шукай його на схід від таверни в Доланаарі.",
        ["npcs"] = { [1] = 3571 },
        ["roles"] = { ["greeting"] = true },
    },
    [689463267] = {
        ["english"] = { [1] = "Hmm, you scratch my back, I'll scratch yours. If you do what I ask, and do it well, maybe we can discuss your training." },
        ["text"] = "Гм, послуга за послугу. Зроби те, що я прошу, і зроби добре — тоді, можливо, поговоримо про навчання.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2504586796] = {
        ["english"] = { [1] = "Don't let the humans in the Bazaar fool ye $g lad : lass;, with the subway those gnomes built it's easier than ye might think to transport goods from Ironforge. If they try to tack on import fees just tell them yer gonna buy yer gear from me." },
        ["text"] = "Не дай людям на Базарі тебе надурити, $g хлопче : дівчино;. Завдяки підземці, яку збудували ті гноми, товари зі Залізогарта возити легше, ніж здається. Якщо вони спробують накинути ввізне мито, просто скажи, що купиш спорядження в мене.",
        ["npcs"] = { [1] = 656, [2] = 1472, [3] = 5384, [4] = 5413, [5] = 5509, [6] = 5510, [7] = 5512, [8] = 5514 },
        ["roles"] = { ["greeting"] = true },
    },
    [270294440] = {
        ["english"] = { [1] = "Faith... Some have lost it, others have found it. It cannot be destroyed and it cannot be created.$B$BOr perhaps you speak of the vestments of Faith? Armor worn by our priests and most devout warriors into battle against the Scourge during the last war.$B$BAye, much of it is lost... Stolen by the fiends of Naxxramas." },
        ["text"] = "Віра... Хтось її втратив, хтось знайшов. Її неможливо знищити й неможливо створити.$B$BА може, ви говорите про шати Віри? Обладунки, які наші жерці та найвідданіші воїни носили в битвах зі Скверною під час останньої війни.$B$BТак, більшість утрачено... Їх викрали потвори Наксрамаса.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2564854797] = {
        ["english"] = { [1] = "Hello! What brings you to Winterspring? These cold and vast lands may seem dismal, but this is a place of many secrets..." },
        ["text"] = "Привіт! Що привело тебе в Зимоключ? Ці холодні безкраї землі можуть здаватися похмурими, але тут приховано чимало таємниць...",
        ["npcs"] = { [1] = 9298 },
        ["roles"] = { ["greeting"] = true },
    },
    [2482501309] = {
        ["english"] = { [1] = "Hmm, I guess I can take on another student. Well, don't just stand there. Tell me what you're looking to learn." },
        ["text"] = "Гм, мабуть, можу взяти ще одного учня. Ну, не стій стовпом. Кажи, чого хочеш навчитися.",
        ["npcs"] = { [1] = 5564 },
        ["roles"] = { ["greeting"] = true },
    },
    [1460618817] = {
        ["english"] = { [1] = "Hmm, I don't have any mithril casings. I'm all out. Is that all you need to get to fix A-Me? Oh, that would be fantastic!$B$BMithril casings aren't too hard to find back in civilization. Just ask any skilled engineer to make one for you. I think it takes a few bars of mithril, but if you could help me out, I'll make sure you're well rewarded!" },
        ["text"] = "Гм, мітрилових кожухів у мене немає. Усі закінчилися. Це все, що потрібно, щоб полагодити А-Мі? О, це було б чудово!$B$BМітрилові кожухи не так уже й важко знайти в цивілізованих краях. Просто попроси будь-якого вправного інженера зробити один. Здається, треба кілька мітрилових зливків, а якщо допоможеш, я подбаю, щоб нагорода була щедрою!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1670993205] = {
        ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of the Undercity.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from the Undercity for your duty and service.\010" },
        ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Підмісто. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Орди.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Підміста.\010",
        ["npcs"] = { [1] = 15738, [2] = 15768 },
        ["roles"] = { ["greeting"] = true },
    },
    [3941679811] = {
        ["english"] = { [1] = "Gahk new at Ogri'la like little $r.  It like heaven da other ogres below always talk about.  But, Gahk's heads hurt from crystal making Gahk smarter.$B$B<Both of Gahk's heads nod to each other.>$B$BUs learning ta make da crystalforged darkrune.  When us learn dat, we smash da demon's warp-gate!" },
        ["text"] = "Ґак новий в Оґріла, як маленький $r. Тут як небо, про яке огри внизу весь час говорять. Але голови Ґака болять від кристала, що робить Ґака розумнішим.$B$B<Обидві голови Ґака кивають одна одній.>$B$BМи вчитися робити кристалокований темнорун. Коли навчитися — ми розбити демонську браму викривлення!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2976775982] = {
        ["english"] = { [1] = "Hail $g brother : sister;... I'd like a moment of your time, if I may.$B$BWe tauren have endured much in our trials and tribulations in establishing our homeland.  We now find ourselves in a dire shortage of cloth.  If you have the materials to spare, I ask that you please donate them.  You certainly would earn the gratitude of tauren everywhere in helping us out!" },
        ["text"] = "Вітаю, $g брате : сестро;... Якщо дозволиш, я заберу хвилинку твого часу.$B$BМи, таурени, пережили чимало випробувань, створюючи свою батьківщину. І тепер нам гостро бракує тканини. Якщо маєш зайві матеріали, прошу пожертвувати їх. Допомога принесе тобі вдячність усіх тауренів!",
        ["npcs"] = { [1] = 14728 },
        ["roles"] = { ["greeting"] = true },
    },
    [3738886533] = {
        ["english"] = { [1] = "Good day to you, $c.$B$BI'm waiting to hear from one of the High Thane's advisors about an audience. It was a struggle just to get the opportunity to present my credentials.$B$BI've heard the Wildhammer described as 'wary of outsiders,' but that's proven to be quite an understatement.  Hopefully, things will improve once I've had the opportunity to meet with Featherbeard, whom I'm told favors closer ties with the Alliance." },
        ["text"] = "Добридень, $c.$B$BЯ чекаю звістки від одного з радників Верховного тана щодо аудієнції. Навіть можливість представити свої повноваження далася нелегко.$B$BЯ чув, що Диких Молотів називають «обережними з чужинцями», але це виявилося великим применшенням. Сподіваюся, все зміниться на краще, коли я зустрінуся з Перобородом — кажуть, він підтримує тісніші зв'язки з Альянсом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1305882577] = {
        ["english"] = { [1] = "Hello, $n. If you'd like to learn a thing or two about cooking, please visit me at any time." },
        ["text"] = "Привіт, $n. Якщо хочеш трохи навчитися куховарства, заходь будь-коли.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1379891946] = {
        ["english"] = { [1] = "Good luck, and be safe. Here comes Uther and Jaina now." },
        ["text"] = "Щасти й бережи себе. Он уже йдуть Утер і Джайна.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3314778255] = {
        ["english"] = { [1] = "Here for a ride, $r?$B$BOr, is something else bothering you?" },
        ["text"] = "Прийшов покататися, $r?$B$BЧи тебе турбує щось інше?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [107733613] = {
        ["english"] = { [1] = "Grab your things, $N! I've just gotten word from Nilith Lokrav in the Searing Gorge that the Undermarket has set up operations in the heart of the Cauldron. Find Nilith Lokrav in the Searing Gorge and get the low down!" },
        ["text"] = "Збирай речі, $N! Щойно надійшла звістка від Ніліт Локрав у Випаленій ущелині: Підринок розгорнув справи в самому серці Казана. Знайди Ніліт Локрав у Випаленій ущелині й дізнайся подробиці!",
        ["npcs"] = { [1] = 6568 },
        ["roles"] = { ["greeting"] = true },
    },
    [2006106530] = {
        ["english"] = { [1] = "Have a wondrous Feast of Winter Veil!  Start it off right with treats from Smokywood Pastures!" },
        ["text"] = "Дивовижного Свята Зимового Покрову! Почни його правильно — з ласощів «Пасовищ Димного Лісу»!",
        ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 },
        ["roles"] = { ["greeting"] = true },
    },
    [141072758] = {
        ["english"] = { [1] = "High Enchanter Bardolan may be found in the Seer's Library on Scryer's Tier. A grand master of the art, he is surrounded by his students: masters, artisans, experts, and journeymen." },
        ["text"] = "Верховного зачарувальника Бардолана можна знайти в Бібліотеці Провидців на ярусі Провидців. Великий майстер цього мистецтва оточений учнями: майстрами, ремісниками, експертами й підмайстрами.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1090898029] = {
        ["english"] = { [1] = "Hides for the Horde, mon!  Only the best for our troops!" },
        ["text"] = "Шкури для Орди, мон! Нашим військам — лише найкраще!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3109832486] = {
        ["english"] = { [1] = "Hmmm... only enchanters I know of around here work out of Stormwind.  Why don't you ask one of the guards up in Stormwind?" },
        ["text"] = "Гм... єдині зачарувальники, яких я тут знаю, працюють у Штормовії. Чому б не спитати в когось із тамтешніх вартових?",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [490958648] = {
        ["english"] = { [1] = "Hi!  I'm Kwee Q. Peddlefeet!  I'm here to find out who is the most popular of all the heroes in Azeroth!$B$BIt sure warms my heart to see so many adoring fans greet their leaders, but... do you know what would warm me even more?$B$BA kiss!" },
        ["text"] = "Привіт! Я Кві К. Педдлфіт! Я тут, щоб з'ясувати, хто з усіх героїв Азероту найпопулярніший!$B$BМені так тепло на серці, коли бачу стільки шанувальників, які вітають своїх лідерів, але... знаєш, від чого стало б ще тепліше?$B$BВід поцілунка!",
        ["npcs"] = { [1] = 16075 },
        ["roles"] = { ["greeting"] = true },
    },
    [249282037] = {
        ["english"] = { [1] = "Don't be fooled, $r. They're very elusive. One moment they're there, the next they're gone - virtually inexplicable!$b$bBetween you and me, I actually held a piece of one in my hand once! Sadly, before I could conduct any measurements it was gone! Just disappeared...." },
        ["text"] = "Не дайте себе обдурити, $r. Вони дуже невловимі. Щойно були тут — і вже зникли, майже незбагненно!$b$bМіж нами кажучи, одного разу я навіть тримав шматочок одного в руці! На жаль, перш ніж я встиг щось виміряти, він зник! Просто розчинився....",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2163263888] = {
        ["english"] = { [1] = "Hey there, $c! Looks like the Horde collected the last of their stuff, and now theirs and ours is being shipped over to Silithus as we speak. I'm told it'll be there in less than a day, and then someone can ring that big gong near the Ahn'Qiraj gates to start the war." },
        ["text"] = "Привіт, $c! Схоже, Орда зібрала останні припаси, і тепер їхнє й наше вже перевозять до Силітусу. Кажуть, усе прибуде менш ніж за день, а тоді хтось зможе вдарити у великий гонг біля брам Ан'Кіражу й почати війну.",
        ["npcs"] = { [1] = 15450 },
        ["roles"] = { ["greeting"] = true },
    },
    [2995197156] = {
        ["english"] = { [1] = "I am glad that you ask. Our efforts to take the armory are at $3233w percent of our projections.$B$BI know that Battlemage Arynna and Harbinger Inuuro need your help. Seek them inside the Sun's Reach Sanctum on the Isle of Quel'Danas." },
        ["text"] = "Радий, що питаєш. Наші зусилля із захоплення зброярні виконані на $3233w відсотків від плану.$B$BЗнаю, що бойовий маг Арінна та провісник Інууро потребують твоєї допомоги. Шукай їх у Святилищі Сонячного Краю на острові Квел'Данас.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3313880214] = {
        ["english"] = { [1] = "Hi! How you? We're good... yup, good good. Hi!" },
        ["text"] = "Привіт! Як ти? Ми добре... ага, добре-добре. Привіт!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3676246109] = {
        ["english"] = { [1] = "Greetings, $c.$B$BWhen the Alliance controls Wintergrasp Fortress, I will open a portal for those who wish to travel there.$B$BThe battle currently enues. Hurry to Wintergrasp and support our forces!" },
        ["text"] = "Вітаю, $c.$B$BКоли Альянс контролює фортецю Зимохвату, я відкриваю портал для всіх, хто хоче туди вирушити.$B$BБитва вже триває. Поспішай до Зимохвату й підтримай наші сили!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3208849686] = {
        ["english"] = { [1] = "Does that heart mean you're looking for love?" },
        ["text"] = "Це сердечко означає, що ви шукаєте кохання?",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 15174, [45] = 16256, [46] = 16458 },
        ["roles"] = { ["reply"] = true },
