    [2141290858] = {
        ["english"] = { [1] = "Hi!  Do you think you might help me to get out of here?" },
        ["text"] = "Привіт! Допоможеш мені звідси вибратися?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1509165790] = {
        ["english"] = { [1] = "Hey Vi'el, show me your wares!" },
        ["text"] = "Гей, Ві'ел, покажи свої товари!",
        ["npcs"] = { [1] = 16015 },
        ["roles"] = { ["reply"] = true },
    },
    [2293437576] = {
        ["english"] = { [1] = "Glyx and I have an understanding: he keeps me supplied, and I keep him rich. Seriously! What that pirate charges me for a measly pouch of crumpled kingsblood... it's enough to make a grown goblin cry." },
        ["text"] = "Ми з Ґліксом маємо угоду: він постачає мені товар, а я роблю його багатим. Серйозно! Те, скільки цей пірат бере за жалюгідний мішечок зім'ятого королівського листя... дорослий гоблін заплаче.",
        ["npcs"] = { [1] = 2837 },
        ["roles"] = { ["greeting"] = true },
    },
    [3201443170] = {
        ["english"] = { [1] = "Get the key and unlock these chains! Hitah'ya the Keeper holds it... back of cave... " },
        ["text"] = "Здобудь ключ і розімкни ці кайдани! Він у Хіта'ї Хранителя... в глибині печери... ",
        ["npcs"] = { [1] = 14757 },
        ["roles"] = { ["greeting"] = true },
    },
    [2910942942] = {
        ["english"] = { [1] = "Hi there, $N. How may I help you?" },
        ["text"] = "Привіт, $N. Чим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [452385294] = {
        ["english"] = { [1] = "Greetings, $c.$B$BThe Alliance currently control Wintergrasp Fortress, but the next battle starts soon.   Get ready to head to Wintergrasp and support our forces!$B$BThe next battle begins in $4354k." },
        ["text"] = "Вітаю, $c.$B$BАльянс зараз контролює фортецю Зимохвату, але наступна битва скоро почнеться. Готуйся вирушати до Зимохвату й підтримати наші сили!$B$BНаступна битва почнеться через $4354k.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3718939999] = {
        ["english"] = { [1] = "How many leather skins have the Alliance collected so far?" },
        ["text"] = "Скільки шкір уже зібрав Альянс?",
        ["npcs"] = { [1] = 15458, [2] = 15701 },
        ["roles"] = { ["reply"] = true },
    },
    [3796081361] = {
        ["english"] = { [1] = "Greetings $g lad : lass;, if you're looking for the best deals you'll find outside of Ironforge itself, then you've come to the right place." },
        ["text"] = "Вітаю, $g хлопче : дівчино;. Якщо шукаєш найкращі ціни за межами самого Залізогарта — ти прийшов куди треба.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3629240292] = {
        ["english"] = { [1] = "Fresh cherry pie for sale, looks so good it will bring a tear to your eye." },
        ["text"] = "Свіжий вишневий пиріг! Такий апетитний, що сльоза навертається!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3302938075] = {
        ["english"] = { [1] = "How fares your search for the Mark?" },
        ["text"] = "Як просуваються пошуки Знака?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4114419527] = {
        ["english"] = { [1] = "Ever vigilant in their protection of the natural world, the druids are guided by Arch Druid Fandral Staghelm who resides in the Cenarion Enclave.  You will find him and the other Druid trainers in the northern section of Darnassus." },
        ["text"] = "Друїди невсипно охороняють природний світ під проводом архідруїда Фендрала Оленерога, який мешкає в Кенарієвому анклаві. Його та інших наставників друїдів знайдеш у північній частині Дарнаса.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [3885567717] = {
        ["english"] = { [1] = "Gor'shak is my friend, you can trust me." },
        ["text"] = "Ґор'шак — мій друг, можеш мені довіряти.",
        ["npcs"] = { [1] = 9021 },
        ["roles"] = { ["reply"] = true },
    },
    [3982739992] = {
        ["english"] = { [1] = "Hey there! Miss the Eastern Kingdoms, huh? Well, the Kraken sails back to Stormwind if you're really itching to return. I know I'd enjoy the warmer weather!" },
        ["text"] = "Привіт! Сумуєш за Східними Королівствами, еге ж? «Кракен» повертається до Штормовію, якщо дуже хочеш назад. Я б і сам не відмовився від теплішої погоди!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3178578119] = {
        ["english"] = { [1] = "Greetings my friend, and welcome to the greatest show on Azeroth!$B$BPlease, step right up and take in all we have to offer.  Amaze at the wonders that the Darkmoon Faire has uncovered in this vast and mysterious world!  We have spared no expense in bringing you excitement that children of all ages will delight in!" },
        ["text"] = "Вітаю, друже, і ласкаво просимо на найбільше видовище Азероту!$B$BПідходьте ближче й погляньте на все, що ми пропонуємо. Дивуйтеся чудесам, які ярмарок Темного Місяця відкрив у цьому величезному й загадковому світі! Ми не шкодували коштів, щоб принести вам розваги, від яких будуть у захваті діти будь-якого віку!",
        ["npcs"] = { [1] = 14823 },
        ["roles"] = { ["greeting"] = true },
    },
    [152460222] = {
        ["english"] = { [1] = "Erm... I really don't know you that well, sorry.  I mean, as an authorized Mechano-strider dealer, I really only can sell my mounts to those people who are considered exalted amongst the gnomes.  If you ever are recognized as exalted to Gnomeregan, I'd be happy to show you what I have to offer." },
        ["text"] = "Ем... вибачте, але я вас майже не знаю. Як уповноважений продавець механострайдерів, я можу продавати їх лише тим, хто має піднесену репутацію серед гномів. Якщо вас колись визнають піднесеним у Ґномреґані, я залюбки покажу, що маю.",
        ["npcs"] = { [1] = 7955 },
        ["roles"] = { ["greeting"] = true },
    },
    [2348645830] = {
        ["english"] = { [1] = "Here, I'd like to give you this token of my love." },
