    [2064379706] = {
        ["english"] = { [1] = "Eldrin is the only one in Elwynn Forest that I would call a tailor.  You can find him at the Eastvale Lumber Camp if you're interested in learning the profession." },
        ["text"] = "Елдрін — єдиний в Ельвинському лісі, кого я назвав би кравцем. Якщо хочеш навчитися ремесла, знайдеш його в лісозаготівельному таборі Східнодолу.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [199314648] = {
        ["english"] = { [1] = "He took the unforged rune covered breastplate, used in the making of the demon forged breastplate and ran away without making payment. A fool, I am not, however... the unforged chest piece is useless without knowledge or the recipe to apply said knowledge.$B$BI wonder... does he sit safely in his city of Blackrock Spire and attempt to create the item from the raw material? I know he dare not leave!" },
        ["text"] = "Він забрав невикований, укритий рунами нагрудник, потрібний для створення демонокованого нагрудника, і втік, не заплативши. Але я не дурень... невикована заготовка марна без знань або рецепта, що дає змогу ці знання застосувати.$B$BЦікаво... чи сидить він безпечно у своєму місті, Чорнокамінному Шпилі, й намагається створити предмет із сирої заготовки? Знаю, він не наважиться звідти вийти!",
        ["npcs"] = { [1] = 10918 },
        ["roles"] = { ["greeting"] = true },
    },
    [2090306643] = {
        ["english"] = { [1] = "Hi there! The name's Gregan. What can I do for ya?" },
        ["text"] = "Привіт! Мене звати Ґреґан. Чим можу допомогти?",
        ["npcs"] = { [1] = 7775 },
        ["roles"] = { ["greeting"] = true },
    },
    [2338940319] = {
        ["english"] = { [1] = "Hello, $c. I am collecting linen bandages here for the Ahn'Qiraj war effort; an effort that will put us all to the test, but strengthen us for the war to come. I can assure you that any bandages that you choose to donate will be put to good use in helping to save the lives of our soldiers when the time comes. I am in need of $2077w, and to this point have managed to collect $2076w. Will you assist us?" },
        ["text"] = "Привіт, $c. Я збираю тут лляні бинти для війни в Ан'Кіражі; це випробування для всіх нас, але воно зробить нас сильнішими перед майбутньою битвою. Запевняю, усі пожертвувані бинти підуть на порятунок життів наших солдатів, коли настане час. Нам потрібно $2077w, а поки вдалося зібрати $2076w. Допоможеш?",
        ["npcs"] = { [1] = 15451 },
        ["roles"] = { ["greeting"] = true },
    },
    [397237946] = {
        ["english"] = { [1] = "Hi there! I have a proposition for an adventure-seeker such as you, if you are up to the challenge!$B$BAlong with my invention, the Super Egg-O-Matic, I am hard at work aiding the druids with their campaign to save the hippogryphs. The birds are being affected by the evil effects of the Gordunni ogres inhabiting the ruins of Feralas, and their numbers are dwindling.$B$BI collect many different types of eggs.  Will you help and find some for me?" },
        ["text"] = "Привіт! Маю пропозицію для шукача пригод на кшталт тебе, якщо готовий до випробування!$B$BРазом зі своїм винаходом, Супер Яйце-О-Матиком, я наполегливо допомагаю друїдам у кампанії з порятунку гіпогрифів. Птахи страждають від лихого впливу огрів Ґордунні, що засіли в руїнах Фераласу, і їх стає дедалі менше.$B$BЯ збираю різні види яєць. Допоможеш і знайдеш трохи для мене?",
        ["npcs"] = { [1] = 7763 },
        ["roles"] = { ["greeting"] = true },
    },
    [3360680612] = {
        ["english"] = { [1] = "Have you? Then you know how weak and pathetic the high elf version of troll magic was?$B$BThe high elves could not understand why a people with their magical affinity could not contend with the powers of troll voodoo. This was an inconceivable notion for the pale skins to understand. They were resigned to using the bastardized version of troll enchantments. I believe they called them 'Arcanum.'\010" },
        ["text"] = "Справді? Тоді ти знаєш, наскільки слабкою й жалюгідною була високoельфійська версія тролячої магії?$B$BВисокі ельфи не могли зрозуміти, чому народ із такою природною магічною обдарованістю не здатен протистояти силі тролячого вуду. Для блідошкірих це було незбагненно. Вони змирилися й користувалися спотвореною версією тролячих чар. Здається, називали їх «Арканум».\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3063638951] = {
        ["english"] = { [1] = "Good question, $r. In my younger days I was footloose and fancy free without a care in the world. In those days I would sing in a barber shop quartet out of Stormwind known as the Four Dons. That's where I learned how to craft the Bonescythe digs." },
        ["text"] = "Гарне питання, $r. Замолоду я був безтурботним гулякою й ні про що не переймався. Тоді я співав у штормовійському квартеті цирульників під назвою «Чотири Дони». Саме там я навчився шити вбрання Кістяної Коси.",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["greeting"] = true },
    },
    [1713818073] = {
        ["english"] = { [1] = "Don't mind Skuerto, $N. He doesn't mean to be rude, he's just terribly busy. While we wait for him to finish scouting, why don't we work on something more productive?" },
        ["text"] = "Не зважай на Скуерто, $N. Він не хоче грубити, просто страшенно зайнятий. Поки він не завершив розвідку, чому б нам не зайнятися чимось кориснішим?",
        ["npcs"] = { [1] = 2788 },
        ["roles"] = { ["greeting"] = true },
    },
    [2625654802] = {
        ["english"] = { [1] = "Hey there, hold on just one second.  I see you're not riding a flying mount of your own.$B$BYou probably won't be of much use to the other goblins here if you can't get around.  They've paid me to loan my used mounts to people such as yourself -- at no cost to you.$B$BInterested?" },
        ["text"] = "Привіт, зачекай хвилинку. Бачу, ти не на власному летючому скакуні.$B$BЯкщо не можеш пересуватися, іншим гоблінам тут від тебе користі буде мало. Вони заплатили мені, щоб я безплатно позичав уживаних скакунів таким, як ти.$B$BЦікавить?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2889830231] = {
        ["english"] = { [1] = "Elder Obsidian wanders near the Sepulcher in Silverpine Forest." },
        ["text"] = "Старійшина Обсидіан мандрує поблизу Гробниці в Срібнохвойному лісі.",
        ["npcs"] = { [1] = 15568, [2] = 15594 },
        ["roles"] = { ["greeting"] = true },
    },
    [407299764] = {
        ["english"] = { [1] = "Heya mon.  You come right place learn how ta wield a new weapon." },
        ["text"] = "Гей, мон. Ти прийшов куди треба, щоб навчитися володіти новою зброєю.",
        ["npcs"] = { [1] = 2704 },
        ["roles"] = { ["greeting"] = true },
    },
    [394886683] = {
        ["english"] = { [1] = "Have you seen all the wonderful things here in Ungoro Crater, $N? It's simply amazing. Not as amazing as some of the things I can make with my skill at engineering, but for it being all natural here... it's not too bad.$B$BMy uncle Remtravel loves old stuff like this place. I'm following in his footsteps kinda--I want to discover new things from lost cultures too!" },
        ["text"] = "Бачив усі дивовижі тут, у кратері Ун'Ґоро, $N? Просто неймовірно. Не так неймовірно, як деякі речі, які я можу створити завдяки інженерії, але як для всього природного тут... цілком непогано.$B$BМій дядько Ремтревел обожнює старі штуки на кшталт цього місця. Я наче йду його слідами — теж хочу відкривати нове в загублених культурах!",
        ["npcs"] = { [1] = 9618 },
        ["roles"] = { ["greeting"] = true },
    },
    [1248815474] = {
        ["english"] = { [1] = "First Aid" },
        ["text"] = "Перша допомога",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [40] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [1695379326] = {
        ["english"] = { [1] = "Friend - Stormwind needs your assistance and your generosity!$B$BOur once large stockpile of textiles has run critically low.  Stormwind is now engaged in a multi-pronged effort to rebuild those stocks for the manufacture of textiles and bandages!  Your donation of cloth would help Stormwind immensely, as well as earn the respect of the citizenry!" },
        ["text"] = "Друже, Штормовій потребує твоєї допомоги й щедрості!$B$BНаші колись великі запаси тканин критично вичерпалися. Штормовій проводить масштабну кампанію з відновлення запасів для виробництва тканин і бинтів! Твоя пожертва тканини неабияк допоможе Штормовію й заслужить повагу містян!",
        ["npcs"] = { [1] = 14722 },
        ["roles"] = { ["greeting"] = true },
    },
    [4017546562] = {
        ["english"] = { [1] = "Flowers and seeds and such?  That would be Reyna Stonebranch's area of expertise.  Ye can find her tending to her plants over at the Ironforge Physician on the southern side of The Great Forge." },
        ["text"] = "Квіти, насіння й таке інше? Це спеціалізація Рейни Кам'яної Гілки. Знайдеш її біля «Залізогартського лікаря» з південного боку Великої Кузні — вона там доглядає рослини.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [4237948757] = {
        ["english"] = { [1] = "Heya, $c, don't you know? The Horde is done with all of its collecting. We're just finishing up final preparations while we wait for the Alliance to finish their gathering. Then it will be time to ship everything over to Silithus for the war." },
        ["text"] = "Гей, $c, хіба не знаєш? Орда завершила всі збори. Ми лише закінчуємо останні приготування й чекаємо, поки Альянс завершить свої. Потім настане час відправити все до Силітусу на війну.",
        ["npcs"] = { [1] = 15515 },
        ["roles"] = { ["greeting"] = true },
    },
    [144820595] = {
        ["english"] = { [1] = "Heya, $c! Lookin' like we got all the spotted yellowtail that we be needin' for that war. Maybe you going to some of the other collectors 'round here and askin' them if they be needin' your help?" },
        ["text"] = "Гей, $c! Схоже, плямистого жовтохвоста для війни ми вже зібрали скільки треба. Може, підеш до інших збирачів і спитаєш, чи їм не потрібна допомога?",
        ["npcs"] = { [1] = 15534 },
        ["roles"] = { ["greeting"] = true },
    },
    [3803910437] = {
        ["english"] = { [1] = "Have you talked to my clone--I mean... my twin?" },
        ["text"] = "Ти вже говорив із моїм клоном — тобто... близнюком?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1936399469] = {
        ["english"] = { [1] = "Hey, sweetheart. The zeppelin that parks here'll take ya straight to Thunder Bluff, free of charge. Who needs wyverns when you got us goblins here, am I right?" },
        ["text"] = "Гей, любчику. Цей дирижабль довезе тебе просто до Громового Бескиду — безплатно. Кому потрібні виверни, коли тут є ми, гобліни, правда?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [158826190] = {
        ["english"] = { [1] = "Hey, someone help me catch this thing!" },
        ["text"] = "Гей, хтось, допоможіть мені спіймати цю штуку!",
        ["npcs"] = { [1] = 14860 },
        ["roles"] = { ["greeting"] = true },
    },
    [2162409724] = {
        ["english"] = { [1] = "Greetings, $r. The war materiel is on its way and should be at Cenarion Hold within a day's time. We can only hope that once it is there that someone, having assembled the Scepter of the Shifting Sands, will step forward to ring the gong and open the gates." },
        ["text"] = "Вітаю, $r. Військові припаси вже в дорозі й мають прибути до Кенарійської цитаделі менш ніж за день. Залишається сподіватися, що коли все буде на місці, хтось, зібравши Скіпетр Мінливих Пісків, вийде вперед, ударить у гонг і відчинить брами.",
        ["npcs"] = { [1] = 15457 },
        ["roles"] = { ["greeting"] = true },
    },
    [183625362] = {
        ["english"] = { [1] = "Hey, remember, $N, we'll make this stuff available for you to buy as you do good deeds.  It's like a karma thing, or something.$B$BSo, help out where you can, including with our Skyguard friends just to the north.$B$BAwesome... thanks!" },
        ["text"] = "Гей, пам'ятай, $N: що більше добрих справ робитимеш, то більше цього товару зможеш у нас купувати. Щось на кшталт карми.$B$BТож допомагай, де можеш, зокрема нашим друзям із Небесної варти трохи північніше.$B$BКруто... дякую!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2230452525] = {
        ["english"] = { [1] = "Forgetting your swordsmithing skill is not something to do lightly.  If you choose to abandon it you will forget all recipes that require swordsmithing to create!" },
        ["text"] = "Відмова від майстерності мечника — серйозний крок. Якщо відмовишся, забудеш усі рецепти, що потребують майстерності мечника!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3480112757] = {
        ["english"] = { [1] = "Hey, if people want to run around rooting in the dirt for colored eggs, who am I to judge? I still get a cut of the profits on paint, and I invested in chickens this year." },
        ["text"] = "Гей, якщо людям хочеться бігати й порпатися в землі заради кольорових яєць — хто я такий, щоб судити? Я все одно отримую частку з продажу фарби, а цього року ще й вклався в курей.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1920244145] = {
        ["english"] = { [1] = "Don't try to teleport to one of your enemies' cities.  It won't work - we may all be friendly here, but back home old grudges remain..." },
        ["text"] = "Не намагайтеся телепортуватися до одного з ворожих міст. Не спрацює — тут ми, може, й усі друзі, але вдома старі образи нікуди не поділися...",
        ["npcs"] = { [1] = 15694, [2] = 15719, [3] = 15905, [4] = 15906, [5] = 15907, [6] = 15908 },
        ["roles"] = { ["greeting"] = true },
    },
    [3851362269] = {
        ["english"] = { [1] = "Don't you have some packages to move?" },
        ["text"] = "Хіба тобі не треба переносити якісь пакунки?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2210257539] = {
        ["english"] = { [1] = "Hey, I see ya got some Brewfest tokens.  If ya want, I still got a few Brewfest goods to sell." },
        ["text"] = "Гей, бачу, маєш жетони Хмільного фестивалю. Якщо хочеш, у мене ще лишилося кілька святкових товарів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2345658698] = {
        ["english"] = { [1] = "Go to Orgrimmar, you will find her and her brood in the Valley of Honor." },
        ["text"] = "Іди до Орґріммара, знайдеш її та її виводок у Долині Честі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [242100627] = {
        ["english"] = { [1] = "Greetings, $c. I can help stable your pets or assist you in recovering lost companions." },
        ["text"] = "Вітаю, $c. Я можу розмістити ваших вихованців у стайні або допомогти повернути втрачених супутників.",
        ["npcs"] = { [1] = 6749, [2] = 9976, [3] = 9977, [4] = 9978, [5] = 9979, [6] = 9980, [7] = 9981, [8] = 9982, [9] = 9983, [10] = 9984, [11] = 9985, [12] = 9986, [13] = 9987, [14] = 9988, [15] = 9989, [16] = 10045, [17] = 10046, [18] = 10047, [19] = 10048, [20] = 10049, [21] = 10050, [22] = 10051, [23] = 10052, [24] = 10053, [25] = 10054, [26] = 10055, [27] = 10056, [28] = 10057, [29] = 10058, [30] = 10059, [31] = 10060, [32] = 10061, [33] = 10062, [34] = 10063, [35] = 10085, [36] = 11069, [37] = 11104, [38] = 11105, [39] = 11117, [40] = 11119, [41] = 13616, [42] = 15131, [43] = 16094 },
        ["roles"] = { ["greeting"] = true },
    },
    [2155164847] = {
        ["english"] = { [1] = "Forgive me, heroes. I should have listened to Uther. I... I just had to see for myself. To look into his eyes one last time. I am sorry." },
        ["text"] = "Пробачте мені, герої. Треба було послухати Утера. Я... я просто мусив побачити все на власні очі. Востаннє зазирнути йому в очі. Пробачте.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4085020162] = {
        ["english"] = { [1] = "Hey, don't open the cage!  Okay?$B$BThese ogres have got me right where I want them." },
        ["text"] = "Гей, не відчиняй клітку! Гаразд?$B$BЦі огри саме там, де я їх і хотів бачити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1281666069] = {
        ["english"] = { [1] = "Don't ya have something better ta do, $g lad : lass; than jaw with me?$B$BNow get out there and prove yer mettle!" },
        ["text"] = "Хіба тобі нема чого кращого робити, $g хлопче : дівчино;, ніж теревенити зі мною?$B$BА тепер рушай і доведи, чого вартий!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1499627568] = {
        ["english"] = { [1] = "Hey, citizen!  You look like a stout one.  We guards are spread a little thin out here, and I could use your help..." },
        ["text"] = "Гей, громадянине! На вигляд ти міцний. Нас, вартових, тут замало, і мені б не завадила твоя допомога...",
        ["npcs"] = { [1] = 197 },
        ["roles"] = { ["greeting"] = true },
    },
    [2376464303] = {
        ["english"] = { [1] = "Elder Mistwalker enjoys watching the struggles at the Maul in Feralas." },
        ["text"] = "Старійшина Туманоступ любить спостерігати за сутичками на Молоті у Фераласі.",
        ["npcs"] = { [1] = 15556, [2] = 15581, [3] = 15604 },
        ["roles"] = { ["greeting"] = true },
    },
    [1669758558] = {
        ["english"] = { [1] = "Hey, can't you shee I'm trying to drink here?" },
        ["text"] = "Гей, не бачиш, я тут п'ю?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [384859553] = {
        ["english"] = { [1] = "Hey, $g buddy : ma'am;. I've seen you around.$B$BMind getting me out of here?" },
        ["text"] = "Гей, $g друже : пані;. Я тебе вже бачив.$B$BНе допоможеш мені звідси вибратися?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1474160915] = {
        ["english"] = { [1] = "Existing only for chaos, its slightest whisper meant the destruction of whole worlds!$B$BYet still, there were those that would try to worship this mindless being.  There were even those more insane who dared to think to control it!" },
        ["text"] = "Воно існувало лише заради хаосу, і навіть найменший його шепіт означав загибель цілих світів!$B$BТа все одно знаходилися ті, хто намагався поклонятися цій бездумній істоті. А ще божевільніші навіть гадали, що зможуть нею керувати!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2990266852] = {
        ["english"] = { [1] = "Hey, $c, did you see that? Out there, lingering near the water's surface....$b$bYou saw it too didn't ya?" },
        ["text"] = "Гей, $c, ти це бачив? Там, біля поверхні води....$b$bТеж бачив, еге ж?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3404309205] = {
        ["english"] = { [1] = "Elder Dreamseer resides in Gadgetzan in Tanaris Desert." },
        ["text"] = "Старійшина Сновидець мешкає в Пристробляху, в пустелі Танаріс.",
        ["npcs"] = { [1] = 15573, [2] = 15578, [3] = 15583, [4] = 15584 },
        ["roles"] = { ["greeting"] = true },
    },
    [2354891285] = {
        ["english"] = { [1] = "Frogs and leather balls for sale!" },
        ["text"] = "Жаби й шкіряні м'ячі на продаж!",
        ["npcs"] = { [1] = 14860 },
        ["roles"] = { ["greeting"] = true },
    },
    [1257183642] = {
        ["english"] = { [1] = "Fascinating. Continue, please." },
        ["text"] = "Захопливо. Продовжуйте, будь ласка.",
        ["npcs"] = { [1] = 14358 },
        ["roles"] = { ["reply"] = true },
    },
    [410786179] = {
        ["english"] = { [1] = "Gorzeeki, I wish to make a purchase." },
        ["text"] = "Ґорзікі, я хочу дещо придбати.",
        ["npcs"] = { [1] = 14437 },
        ["roles"] = { ["reply"] = true },
    },
    [2387625242] = {
        ["english"] = { [1] = "Elder Darkhorn can be found among the red rocks of Orgrimmar." },
        ["text"] = "Старійшину Темний Ріг можна знайти серед червоних скель Орґріммара.",
        ["npcs"] = { [1] = 15564, [2] = 15572, [3] = 15580, [4] = 15582 },
        ["roles"] = { ["greeting"] = true },
    },
    [1941569803] = {
        ["english"] = { [1] = "Hey wait, Gadgetzan has a disco?" },
        ["text"] = "Стривай, у Пристробляху є дискотека?",
        ["npcs"] = { [1] = 16131 },
        ["roles"] = { ["reply"] = true },
    },
    [2459683318] = {
        ["english"] = { [1] = "Hi there. No, Marvon sure isn't here, and he won't be back for quite some time. Actually, I am getting a little worried about him...$B$BI hope he gets back soon. A large chest arrived for him and it's too heavy for me to lug it inside here! I had to leave it out by the door..." },
        ["text"] = "Привіт. Ні, Марвона тут точно немає, і ще довго не буде. Насправді я вже трохи за нього хвилююся...$B$BСподіваюся, він скоро повернеться. Для нього привезли велику скриню, а вона надто важка, щоб я затягнув її всередину! Довелося лишити біля дверей...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [28062446] = {
        ["english"] = { [1] = "Gri'lek, of the Iron Blood$B$BThe wanderer.  May his strength and lust for battle pierce the ages.  $B$BGri'lek now dwells far from here.  One day, he may return..." },
        ["text"] = "Ґрі'лек, із Залізної Крові$B$BМандрівник. Нехай його сила й жага битви пройдуть крізь віки.  $B$BНині Ґрі'лек мешкає далеко звідси. Одного дня він може повернутися...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [751135215] = {
        ["english"] = { [1] = "Greetings young one, and welcome to Thunder Bluff.  You'll find safe refuge from the burdens of the world here.  All denizens of the Horde are welcome here.$B$BThe spirits of the present and past come alive here in this sacred place, my friend.  Honor them, and in doing so honor yourself." },
        ["text"] = "Вітаю, юначе, і ласкаво просимо до Громового Бескиду. Тут ти знайдеш безпечний прихисток від тягарів світу. Тут раді всім мешканцям Орди.$B$BУ цьому священному місці оживають духи минулого й сучасного, друже. Шануй їх — і тим самим шануй себе.",
        ["npcs"] = { [1] = 3057 },
        ["roles"] = { ["greeting"] = true },
    },
    [2562679984] = {
        ["english"] = { [1] = "Fast forward to the present: The resultant formula works, allowing for the creation of a more controlled drone, however, the drawback is that the inactive compound is extremely volatile.$B$BGallywix, everyone in this tower and everyone outside are infected with the poison. It's affecting our minds and our bodies. Our internal organs have become soft and extremely fragile. This is your chance, $N. I don't have the strength to carry on and I sense that soon I will become one of 'them.'" },
        ["text"] = "Перенесімося до сьогодення: отримана формула працює й дозволяє створити більш керованого трутня, але є недолік — неактивна сполука надзвичайно нестабільна.$B$BҐаллівіксе, усі в цій вежі й навколо неї заражені отрутою. Вона вражає наші тіла й розум. Наші внутрішні органи стали м'якими й надзвичайно крихкими. Це твій шанс, $N. У мене вже немає сил продовжувати, і я відчуваю, що скоро стану одним із «них».",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4034940665] = {
        ["english"] = { [1] = "Get out of my way, $r. Can't you see that we're in the middle of a battle!" },
        ["text"] = "Геть з дороги, $r. Не бачиш, ми посеред битви!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4203512652] = {
        ["english"] = { [1] = "Get back here!" },
        ["text"] = "Повернися сюди!",
        ["npcs"] = { [1] = 14860 },
        ["roles"] = { ["greeting"] = true },
    },
    [2375434190] = {
        ["english"] = { [1] = "Hey there.  Taking a break, overseer?  We don't get to see you around here much anymore since you were reassigned to Ruuan Weald.$B$BTake a look at what I have to offer.  It may not have changed much since last we spoke, but I've got plenty.$B$BAnd don't be such a stranger!" },
        ["text"] = "Привіт. Перерва, наглядачу? Відколи тебе перевели до Рууанського лісу, ми майже тебе не бачимо.$B$BПоглянь, що в мене є. Може, від нашої останньої зустрічі асортимент і не дуже змінився, але товару вистачає.$B$BІ не зникай надовго!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [682270638] = {
        ["english"] = { [1] = "Hey there, friend. My name's Remy. I'm from Redridge to the east, and came here looking for business, looking for business. You got any...got any??" },
        ["text"] = "Привіт, друже. Мене звати Ремі. Я зі Східногір'я на сході, прийшов сюди шукати справу, шукати справу. Маєш щось... маєш??",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3115951125] = {
        ["english"] = { [1] = "During Hallow's End we celebrate the day that the Banshee Queen herself delivered us from the clutches of the Lich King and the Scourge. Be sure to attend the Wickerman Festival that is held each evening outside Undercity." },
        ["text"] = "Під час Тиквовину ми святкуємо день, коли сама Королева банші визволила нас із пазурів Короля-ліча та Скверни. Обов'язково завітай на Свято Плетеного чоловічка, яке щовечора відбувається за межами Підміста.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2967274444] = {
        ["english"] = { [1] = "Hello, $c. From what I've been told, everything's been collected, and all of the materiel for the war is being shipped over to Silithus as we speak. It should all be there in less than a day. Once that's done, and the gong has been rung with the Scepter of the Shifting Sands, the war will really begin." },
        ["text"] = "Привіт, $c. Наскільки я знаю, все вже зібрано, а військові припаси зараз перевозять до Силітусу. Усе має прибути менш ніж за день. Після цього, коли в гонг ударять Скіпетром Мінливих Пісків, війна почнеться по-справжньому.",
        ["npcs"] = { [1] = 15432 },
        ["roles"] = { ["greeting"] = true },
    },
    [1924050726] = {
        ["english"] = { [1] = "Hello, $N. What can I do for you?" },
        ["text"] = "Привіт, $N. Чим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2201477437] = {
        ["english"] = { [1] = "Hey there, $N. How can I help you?" },
        ["text"] = "Привіт, $N. Чим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4222813600] = {
        ["english"] = { [1] = "Hail to you, $r. What I am doing here is a story for another time. Oof, that was a bad one.$B$BMy brother and I are stuck here, between our time and the present. We dare not leave for fear of causing a temporal paradox. Patiently we wait until the dragons restore us to our proper timeline.$B$BHow long has it been you ask? I'm not sure really. Ask my brother.$B$BCare for some cheese?" },
        ["text"] = "Вітаю, $r. Що я тут роблю — історія на інший раз. Ох, це було боляче.$B$BМи з братом застрягли між нашим часом і сьогоденням. Не можемо піти, бо боїмося створити часовий парадокс. Терпляче чекаємо, поки дракони повернуть нас до належної часової лінії.$B$BСкільки часу минуло? Не знаю. Спитай мого брата.$B$BСиру хочеш?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [169101422] = {
        ["english"] = { [1] = "How dare you commune with a Duke of the Council, worm!" },
        ["text"] = "Як ти смієш звертатися до герцога Ради, хробаче!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [637407294] = {
        ["english"] = { [1] = "Here are more of the incendiary devices, $N. Be careful with these, they can cause a great deal of disruption to time if used improperly." },
        ["text"] = "Ось іще запальні пристрої, $N. Обережно з ними: неправильне використання може спричинити серйозні порушення плину часу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1799450386] = {
        ["english"] = { [1] = "Fastest gryphons this side of Aerie Peak. Want to take a ride?" },
        ["text"] = "Найшвидші грифони по цей бік Орлиного піку. Хочете прокататися?",
        ["npcs"] = { [1] = 2859 },
        ["roles"] = { ["greeting"] = true },
    },
    [2684848703] = {
        ["english"] = { [1] = "Hee hee hee! Dis gunna be some fun, mon!" },
        ["text"] = "Хі-хі-хі! Оце буде веселуха, мон!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [648051612] = {
        ["english"] = { [1] = "I am Ulysses Rackmore, captain of the Gallant.  And this is the log of the last few days of my doomed ship.$B$BWe were sailing to Feathermoon Stronghold with a shipment of supplies when naga stormed the sides of the Gallant.  We drove them back but we knew they'd return.  Fearing the loss of my most precious belongings, I steered the Gallant to an island off the coast of Desolace, one with old, night elf ruins.  And there I left my treasure chest." },
        ["text"] = "Я Улісс Рекмор, капітан «Ґалланта». А це журнал останніх днів мого приреченого корабля.$B$BМи пливли до твердині Перомісяця з вантажем припасів, коли наґи полізли на борти «Ґалланта». Ми відбили їх, але знали, що вони повернуться. Боячись утратити найдорожчі речі, я повів «Ґаллант» до острова біля узбережжя Спустошища, де є старі руїни нічних ельфів. Там я й залишив скриню зі скарбами.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1550512546] = {
        ["english"] = { [1] = "Grok hear dat yous da new $g king : queen; of all da ogres.  Congrat... congratu... gratz, little $r." },
        ["text"] = "Ґрок чути, що ти новий $g король : королева; усіх огрів. Віт... віта... вітаю, маленький $r.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1427928503] = {
        ["english"] = { [1] = "Go, $N, into Arathi Basin! Slay, SLAY, as you've never slain before!" },
        ["text"] = "Рушай, $N, до Низини Араті! ВБИВАЙ, ВБИВАЙ, як ніколи раніше!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1229217915] = {
        ["english"] = { [1] = "Great job! Arthas is safely on his way to Northrend!" },
        ["text"] = "Чудова робота! Артас безпечно прямує до Нортренду!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2265073340] = {
        ["english"] = { [1] = "Hey there, $c!$B$B<Khatie looks at you slyly.>$B$BAnytime you want to wrangle us up some more aether rays, you make sure to come and see me!" },
        ["text"] = "Привіт, $c!$B$B<Каті хитро дивиться на тебе.>$B$BЯкщо захочеш пригнати нам ще ефірних скатів, обов'язково приходь до мене!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1440453886] = {
        ["english"] = { [1] = "Has the Prince recanted the tale of the Ashbringer? It is our most favorite of his stories. His favorite is the followup to the Ashbringer. Of course, nobody has ever been able to get that story out of him." },
        ["text"] = "Принц уже переповідав історію Попелителя? Це наша найулюбленіша його історія. А його улюблена — продовження історії Попелителя. Щоправда, ніхто так і не зміг витягти з нього ту розповідь.",
        ["npcs"] = { [1] = 14369 },
        ["roles"] = { ["greeting"] = true },
    },
    [969421747] = {
        ["english"] = { [1] = "Expedition Point is a tough place to be stationed, but it's critical to the defense of Honor Hold.  The information gathered here, and the engagements our soldiers make against the Legion and the orcs of Zeth'Gor, are invaluable to the Alliance's Hellfire campaign." },
        ["text"] = "Експедиційна застава — важке місце для служби, але вона життєво важлива для оборони Оплоту Честі. Відомості, які тут збирають, і сутички наших солдатів із Легіоном та орками Зет'Ґора безцінні для кампанії Альянсу на Півострові Пекельного Вогню.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2344308379] = {
        ["english"] = { [1] = "Every item that I have for sale I acquired myself.  You have my personal guarantee of authenticity." },
        ["text"] = "Кожен предмет, який я продаю, я здобув особисто. Даю власну гарантію справжності.",
        ["npcs"] = { [1] = 14846 },
        ["roles"] = { ["greeting"] = true },
    },
    [3768554555] = {
        ["english"] = { [1] = "Elune has blessed us many times over with all the discoveries we have made.  But we must remain vigilant, $c." },
        ["text"] = "Елуна не раз благословляла нас усіма відкриттями, які ми зробили. Та ми мусимо залишатися пильними, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2387529108] = {
        ["english"] = { [1] = "Gangway, ye scurvy dog!  Revilgaz has spared me from the gallows but my punishment might be nearly as bad." },
        ["text"] = "З дороги, цинґавий псе! Ревілґаз урятував мене від шибениці, та покарання може бути майже гіршим.",
        ["npcs"] = { [1] = 16399 },
        ["roles"] = { ["greeting"] = true },
    },
    [2907427027] = {
        ["english"] = { [1] = "Hey there!  Good to see a new face - I don't get many visitors and the technicians aren't very good conversationalists.$B$BI bet you're on your way to Area 52.  Am I right?" },
        ["text"] = "Привіт! Радий бачити нове обличчя — відвідувачів тут небагато, а техніки не найкращі співрозмовники.$B$BБ'юсь об заклад, ти прямуєш до Зони 52. Вгадав?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1069846799] = {
        ["english"] = { [1] = "Good Morning!" },
        ["text"] = "Доброго ранку!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [66948859] = {
        ["english"] = { [1] = "Hey there!  Are you interested in learning some more about racing rams and ram racing?" },
        ["text"] = "Привіт! Хочеш дізнатися більше про перегони на баранах і керування ними?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3615421690] = {
        ["english"] = { [1] = "Game? Are you crazy?" },
        ["text"] = "Гра? Ти здурів?",
        ["npcs"] = { [1] = 14354 },
        ["roles"] = { ["reply"] = true },
    },
    [3218317643] = {
        ["english"] = { [1] = "Haha! Save for their leaders--the satyr, Bazzalan, and the warlock Jergosh--yes, all of them. That is why I constantly send Thrall's worshippers at them. It gives Thrall the impression that I am weeding out the evil in the bowels of his great city. The victory is in reality two-fold: kill Thrall's faithful and test the strength of those in the Searing Blade to see if they are truly worthy of joining me." },
        ["text"] = "Ха-ха! Крім їхніх ватажків — сатира Баззалана й чорнокнижника Джерґоша — так, усіх. Саме тому я постійно посилаю на них шанувальників Тралла. Тралл думає, ніби я викорінюю зло в надрах його великого міста. Насправді ж перемога подвійна: гинуть вірні Тралла, а члени Палаючого Клинка доводять свою силу й гідність приєднатися до мене.",
        ["npcs"] = { [1] = 3216 },
        ["roles"] = { ["greeting"] = true },
    },
    [135273900] = {
        ["english"] = { [1] = "Good ol' Erma, she's been taking care of the local animals for years now.  I'm sure she'd be happy to take care of any you'd like to put up.  She can be found right outside of the Lion's Pride Inn." },
        ["text"] = "Стара добра Ерма вже багато років доглядає місцевих тварин. Упевнений, вона залюбки пригляне за будь-якою твариною, яку захочеш залишити. Її знайдеш просто біля таверни «Гордість Лева».",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [1273794992] = {
        ["english"] = { [1] = "Hey there friend!  I see you've got some Brewfest tokens.  As it happens, I still have some Brewfest items for sale." },
        ["text"] = "Привіт, друже! Бачу, маєш жетони Хмільного фестивалю. Якраз у мене ще лишилися святкові товари на продаж.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [403099394] = {
        ["english"] = { [1] = "Get out of here, before the slavers see you!" },
        ["text"] = "Забирайся звідси, поки работорговці тебе не побачили!",
        ["npcs"] = { [1] = 5843 },
        ["roles"] = { ["greeting"] = true },
    },
    [2878069893] = {
        ["english"] = { [1] = "Hey friend, what I've got here is a breakthrough, the likes of which have never been seen!  And it's for sale, for cheap!$b$bYou see, I got tired of spending money in taverns looking for the perfect person.  So I made these goggles and now EVERYONE looks like pure perfection.  I mean you CAN'T go wrong with these puppies!$b$bSo, you wanna try these out, help pad my pockets a bit?  Since you look soo good, I'll even give you a discount!" },
        ["text"] = "Гей, друже, те, що в мене тут, — прорив, якого світ ще не бачив! І воно продається, недорого!$b$bРозумієш, мені набридло витрачати гроші в тавернах у пошуках ідеальної людини. Тож я зробив ці окуляри — і тепер УСІ виглядають досконало. З цими малюками просто НЕ МОЖНА помилитися!$b$bТо що, хочеш випробувати й трохи набити мої кишені? А оскільки ти й так чудово виглядаєш, ще й знижку дам!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [794959304] = {
        ["english"] = { [1] = "Hey there cutie, you looking for a ride to Grom'gol? I hear it gets mighty steamy down in those jungles, maybe I could join you for a short vacation, show you a real jungle cat." },
        ["text"] = "Гей, красунчику, шукаєш рейс до Ґром'ґола? Кажуть, у тих джунглях дуже спекотно — може, я приєднаюся до тебе на коротку відпустку й покажу справжню дику кішку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4095967763] = {
        ["english"] = { [1] = "Do you want to play a game, stinky?" },
        ["text"] = "Хочеш пограти, смердючко?",
        ["npcs"] = { [1] = 14354 },
        ["roles"] = { ["greeting"] = true },
    },
    [2577376444] = {
        ["english"] = { [1] = "Haha, $g boyo : girlie;! The Alliance has gathered everything that we're needin' to get this here war started! Maybe the Horde will catch up soon?" },
        ["text"] = "Ха-ха, $g хлопче : дівчино;! Альянс зібрав усе, що нам треба, щоб розпочати цю війну! Може, Орда скоро наздожене?",
        ["npcs"] = { [1] = 15383 },
        ["roles"] = { ["greeting"] = true },
    },
    [1905771823] = {
        ["english"] = { [1] = "He is the greatest hero the arakkoa have ever known.$B$BIt is said that in ancient times, he built the city of Skettis with his own claws. He was our greatest champion and defender, but he left us when we turned away from the veneration of Rukhmar.$B$BWe came to worship a new master, one who promised us untold power and status in the cosmos.$B$BThere are some who say that Terokk and Rukhmar are one, and he withdrew his presence from us when we turned away from him." },
        ["text"] = "Він найбільший герой, якого коли-небудь знали араккоа.$B$BКажуть, у давнину він власними кігтями збудував місто Скеттіс. Він був нашим найвеличнішим захисником і чемпіоном, але покинув нас, коли ми відвернулися від поклоніння Рухмар.$B$BМи почали служити новому володарю, який обіцяв незліченну силу й високе становище в космосі.$B$BДехто каже, що Терокк і Рухмар — одне й те саме, і що він відвернувся від нас, коли ми відвернулися від нього.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2972579201] = {
        ["english"] = { [1] = "Hey mon, you be needin' to head on over to da $c trainer." },
        ["text"] = "Гей, мон, тобі треба до наставника $c.",
        ["npcs"] = { [1] = 3154, [2] = 3406, [3] = 3407 },
        ["roles"] = { ["greeting"] = true },
    },
    [3269364330] = {
        ["english"] = { [1] = "Greetings.  You seek instruction in the art of war?" },
        ["text"] = "Вітаю. Шукаєте навчання мистецтва війни?",
        ["npcs"] = { [1] = 3593, [2] = 3598, [3] = 4087, [4] = 5113, [5] = 7315 },
        ["roles"] = { ["greeting"] = true },
    },
    [2775160192] = {
        ["english"] = { [1] = "Hold on there, I'm just an assistant. If ye want to start learnin' the fancy stuff, talk to old Stonebrew over there." },
        ["text"] = "Стривай, я лише помічник. Якщо хочеш перейти до складніших речей, поговори зі старим Стоунбрю он там.",
        ["npcs"] = { [1] = 1703 },
        ["roles"] = { ["greeting"] = true },
    },
    [2914612484] = {
        ["english"] = { [1] = "Great, let's get started... ha! Fooled you! Surely you didn't think it would be that simple. You'll need to prove your mettle just like everyone else!" },
        ["text"] = "Чудово, почнімо... ха! Повівся! Невже думав, що все буде так просто? Доведеться довести свою силу, як і всім іншим!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3958948173] = {
        ["english"] = { [1] = "Frustrated by the Dalaran wizards' lack of progress against the undead during the Third War, the Archmage Arugal elected to summon the extra-dimensional worgen to bolster his side's diminishing ranks. The wolf-men slaughtered the Scourge, then quickly turned on the wizards themselves and laid siege to the keep of the noble, Baron Silverlaine. The fort quickly fell into shadow and ruin. Driven mad with guilt, Arugal adopted the worgen as his children and retreated to the newly dubbed 'Shadowfang Keep'. \010" },
        ["text"] = "Розчарований відсутністю поступу даларанських чарівників у боротьбі з невмерлими під час Третьої війни, архімаг Аруґал вирішив викликати ворґенів з іншого виміру, щоб поповнити свої ряди. Вовколюди винищили Скверну, а потім швидко обернулися проти самих чарівників і взяли в облогу фортецю шляхетного барона Сільверлейна. Твердиня швидко поринула в тінь і занепад. Збожеволівши від провини, Аруґал прийняв ворґенів за своїх дітей і відступив у фортецю, яку відтоді назвали «Твердинею Тіньового Ікла».\010",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [296856763] = {
        ["english"] = { [1] = "Fist weapons are taught by Sayoc, the orc weapon master in Orgrimmar. He spends his days in the Valley of Honor." },
        ["text"] = "Користуватися кистьовою зброєю навчає Сайок, орчий майстер зброї в Орґріммарі. Він проводить дні в Долині Честі.",
        ["npcs"] = { [1] = 11869, [2] = 11870 },
        ["roles"] = { ["greeting"] = true },
    },
    [315338282] = {
        ["english"] = { [1] = "Hello, $N! I am master engineer, Scooty." },
        ["text"] = "Привіт, $N! Я майстер-інженер Скуті.",
        ["npcs"] = { [1] = 7853 },
        ["roles"] = { ["greeting"] = true },
    },
    [687177300] = {
        ["english"] = { [1] = "Heigan is probably performing maintenance on his slime and crap filled dance studio." },
        ["text"] = "Гейґан, мабуть, знову прибирає у своїй танцювальній студії, повній слизу й лайна.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2102787310] = {
        ["english"] = { [1] = "I am knowledgable, but I am not an expert. You know who you should talk to? Rhiannon! She's not far. Ask around for her in Undercity" },
        ["text"] = "Я знаю чимало, але не експерт. Знаєш, із ким треба поговорити? З Ріаннон! Вона недалеко. Розпитай про неї в Підмісті.",
        ["npcs"] = { [1] = 3523 },
        ["roles"] = { ["greeting"] = true },
    },
    [2826087672] = {
        ["english"] = { [1] = "Healing is for those who cannot endure pain.  However if you must, seek out the Spirit Lodge on the lake in the Valley of Spirits, up and above the Valley of Strength to the west." },
        ["text"] = "Зцілення — для тих, хто не здатен терпіти біль. Та якщо вже мусиш, шукай Оселю Духів біля озера в Долині Духів, західніше й вище від Долини Сили.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1528451036] = {
        ["english"] = { [1] = "Hey everyone, it's $N!" },
        ["text"] = "Гей, усі, це $N!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1918898971] = {
        ["english"] = { [1] = "Even within cold, stone walls such as the ones that shelter this town, one may find tranquility and peace.  In fact, you may find them everywhere you are... simply look inside yourself for such balance." },
        ["text"] = "Навіть серед холодних кам'яних мурів цього міста можна знайти спокій і гармонію. Насправді їх можна знайти будь-де... просто зазирни всередину себе й відшукай рівновагу.",
        ["npcs"] = { [1] = 3597, [2] = 5504, [3] = 5505, [4] = 5506, [5] = 12042 },
        ["roles"] = { ["greeting"] = true },
    },
    [2784141396] = {
        ["english"] = { [1] = "Greetings, fleshling. I am Navuud, chief researcher here at the Protectorate Watch Post." },
        ["text"] = "Вітаю, плотянику. Я Навууд, головний дослідник цієї застави Протекторату.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2880250130] = {
        ["english"] = { [1] = "Hey citizen ! I need your help.. ." },
        ["text"] = "Гей, громадянине! Мені потрібна твоя допомога.. .",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2079704741] = {
        ["english"] = { [1] = "Heroes of the Brood? C'Thun must be banished! We can assist you, mortal!" },
        ["text"] = "Герої Виводка? К'Туна треба вигнати! Ми можемо допомогти тобі, смертний!",
        ["npcs"] = { [1] = 15378 },
        ["roles"] = { ["greeting"] = true },
    },
    [465626580] = {
        ["english"] = { [1] = "Henchmen?  Tribute?" },
        ["text"] = "Поплічники? Данина?",
        ["npcs"] = { [1] = 14353 },
        ["roles"] = { ["reply"] = true },
    },
    [3470595367] = {
        ["english"] = { [1] = "Hello, $n!  How goes your adventures? My experiments are progressing nicely...$B$BBe sure to check back with me later!   I might have more test flight opportunities for you!" },
        ["text"] = "Привіт, $n! Як пригоди? Мої експерименти чудово просуваються...$B$BЗаходь пізніше! Можливо, для тебе з'являться нові випробувальні польоти!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3138555002] = {
        ["english"] = { [1] = "Here's to hoping not all of Outland is as barren as this region.  This is quite a change from the green grasslands and forests of Eversong." },
        ["text"] = "Сподіваюся, не все Позамежжя таке ж безплідне, як цей край. Після зелених лук і лісів Вічноспіву різниця разюча.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2581893031] = {
        ["english"] = { [1] = "Here's a gold, buy yourself something nice." },
        ["text"] = "Ось золота монета, купи собі щось гарне.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3586197124] = {
        ["english"] = { [1] = "Here we practice fire fighting techniques.  Power to the Forsaken!" },
        ["text"] = "Тут ми відпрацьовуємо техніки гасіння пожеж. Слава Відреченим!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2683207855] = {
        ["english"] = { [1] = "Hi! I just got back from exploring the Ruins of Kel'Theril, to the southwest. Now I'm intent on investigating the Wildkin that lie just up the ridge here, in Owl Wing Thicket.$B$BHave you spoken to Erelas Ambersky in Rut'theran Village? He requested that I come here, and perhaps he has a task for you as well." },
        ["text"] = "Привіт! Я щойно повернувся з дослідження руїн Кел'Теріла на південному заході. Тепер хочу дослідити диких совозвірів трохи вище по схилу, в гущавині Совиного Крила.$B$BТи говорив з Ереласом Бурштинове Небо в селищі Рут'теран? Він попросив мене прийти сюди, можливо, і для тебе має завдання.",
        ["npcs"] = { [1] = 10300 },
        ["roles"] = { ["greeting"] = true },
    },
    [1606949453] = {
        ["english"] = { [1] = "Engineering will provide you with the skills and knowledge to dismantle your opponents! Let me show you how..." },
        ["text"] = "Інженерія дасть тобі навички та знання, щоб розбирати супротивників на частини! Дозволь показати...",
        ["npcs"] = { [1] = 4586 },
        ["roles"] = { ["greeting"] = true },
    },
    [1739376804] = {
        ["english"] = { [1] = "Done, done, and done." },
        ["text"] = "Готово, готово й готово.",
        ["npcs"] = { [1] = 3836 },
        ["roles"] = { ["reply"] = true },
    },
    [4179556096] = {
        ["english"] = { [1] = "Good, you've got some grit! I like that. Well then, let's get going!" },
        ["text"] = "Добре, у тебе є характер! Мені подобається. Ну що ж, рушаймо!",
        ["npcs"] = { [1] = 11049 },
        ["roles"] = { ["greeting"] = true },
    },
    [2335732006] = {
        ["english"] = { [1] = "Here to learn how to wield a new weapon, or just to waste my time?" },
        ["text"] = "Прийшов навчитися володіти новою зброєю чи просто марнувати мій час?",
        ["npcs"] = { [1] = 11868 },
        ["roles"] = { ["greeting"] = true },
    },
    [974488914] = {
        ["english"] = { [1] = "How may I help you, $c?" },
        ["text"] = "Чим можу допомогти, $c?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2681483083] = {
        ["english"] = { [1] = "Greetings.  I'm a mage trainer, and you're a mage." },
        ["text"] = "Вітаю. Я наставник магів, а ти маг.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2026610657] = {
        ["english"] = { [1] = "Hello.  I trust that this day finds you well?" },
        ["text"] = "Привіт. Сподіваюся, цей день добре до тебе ставиться?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1796712235] = {
        ["english"] = { [1] = "Here to help with the disturbances?" },
        ["text"] = "Прийшов допомогти з цими збуреннями?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3595672714] = {
        ["english"] = { [1] = "Greetings, $N. I am Doctor Gustaf VanHowzen, head trauma surgeon of Alliance Trauma." },
        ["text"] = "Вітаю, $N. Я доктор Ґустаф Ван-Говзен, головний хірург травматології Альянсу.",
        ["npcs"] = { [1] = 12939 },
        ["roles"] = { ["greeting"] = true },
    },
    [2988504336] = {
        ["english"] = { [1] = "Here lie the remains of Weeder Greenthumb, one of Watcher Jhang's druid companions.  By all appearances he was killed quick and clean while trying to make his escape from the Slave Pens." },
        ["text"] = "Тут лежать останки Прополювача Зеленопальця, одного з друїдів-супутників вартової Джанґ. Судячи з усього, його швидко й чисто вбили, коли він намагався втекти із Загонів рабів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3431814435] = {
        ["english"] = { [1] = "Here is where I sacrificied everything to free my father. Now I come to destroy it..." },
        ["text"] = "Саме тут я пожертвував усім, щоб визволити батька. А тепер прийшов це знищити...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1307527594] = {
        ["english"] = { [1] = "I am here at the behest of my master, Baron Sablemane, to help the Cenarion Expedition with its wyrmcult problems.$B$BI'm something of an expert on these things." },
        ["text"] = "Я тут за наказом мого володаря, барона Соболиної Гриви, щоб допомогти Кенарійській експедиції з проблемами культу зміїв.$B$BЯ дещо знаю про такі справи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2269770667] = {
        ["english"] = { [1] = "Feel like helping me to take down the warp-gate in that Burning Legion camp to the south?" },
        ["text"] = "Хочеш допомогти мені знищити браму викривлення в тому таборі Палаючого Легіону на півдні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3675701430] = {
        ["english"] = { [1] = "Here at the Farstrider lodge, we prize hunting skills above all else. Wish to gain my approval? You'll have to earn it.$B$BYou look up to the challenge, $Glad:lass;!" },
        ["text"] = "Тут, у пристанищі Далекоходців, ми понад усе цінуємо мисливські навички. Хочеш заслужити моє схвалення? Доведеться його заслужити.$B$BСхоже, ти готовий до випробування, $Gхлопче:дівчино;!",
        ["npcs"] = { [1] = 1154 },
        ["roles"] = { ["greeting"] = true },
    },
    [2478886126] = {
        ["english"] = { [1] = "Graham Van Talen in Rogues' Quarter on outer ring of Undercity." },
        ["text"] = "Ґрем Ван Тален у Кварталі розбійників, на зовнішньому кільці Підміста.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [2249988854] = {
        ["english"] = { [1] = "Enjoying the festival, $c?$b$bWhile the Flamekeeper tends to the fires of the present, I am more of a historian, keeping close the festivals past. I'm also, of course, documenting this year's festivities. Things are going well thus far, don't you think?$b$bYou know, $n, there is power inherent in all festival fires burning throughout the holiday. We're taking care of ours, but I'm certain there are sacred flames burning deep within our enemy's cities..." },
        ["text"] = "Подобається свято, $c?$b$bПоки Вартовий Полум'я дбає про вогні сьогодення, я більше історик і бережу пам'ять про минулі свята. І, звісно, записую події цього року. Поки що все йде добре, хіба ні?$b$bЗнаєш, $n, у всіх святкових вогнях, що палають упродовж свята, є своя сила. Ми бережемо наші, але я певен, що священні вогні палають і в самому серці ворожих міст...",
        ["npcs"] = { [1] = 16817 },
        ["roles"] = { ["greeting"] = true },
    },
    [2855451405] = {
        ["english"] = { [1] = "Elves in Warsong Gulch make crunchy sound.  You crunch them good.  Talk to Kurden Bloodclaw in Royal Quarter.", [2] = "Elves in Warsong Gulch make crunchy sound. You crunch them good. Talk to Kurden Bloodclaw in Royal Quarter." },
        ["text"] = "Ельфи в Ущелині Пісні Війни хрустять. Ти їх добре хрусти. Поговори з Курденом Кривавим Кігтем у Королівському кварталі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1202866516] = {
        ["english"] = { [1] = "Greetings $c -- if you're looking for leather goods and leatherworking supplies, you've come to the right semi-retired Paladin." },
        ["text"] = "Вітаю, $c — якщо шукаєш шкіряні вироби та припаси для шкірництва, ти прийшов до правильного напіввідставного паладина.",
        ["npcs"] = { [1] = 7852 },
        ["roles"] = { ["greeting"] = true },
    },
    [3265668836] = {
        ["english"] = { [1] = "Here are the final standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BThe Horde has the most popular hero!" },
        ["text"] = "Ось остаточні результати!$B$BТралл: $2200w$BКерн: $2201w$BСільвана: $2202w$BУсього Орда: $2207w$B$BБолвар: $2203w$BМаґні: $2204w$BТиранда: $2205w$BУсього Альянс: $2206w$B$BНайпопулярніший герой — в Орди!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [936001623] = {
        ["english"] = { [1] = "Elder Windrun resides in the Crown Guard Tower in the Eastern Plaguelands." },
        ["text"] = "Старійшина Вітробіг мешкає у вежі Королівської Варти в Східному Чумнозем'ї.",
        ["npcs"] = { [1] = 15566, [2] = 15594, [3] = 15602, [4] = 15607 },
        ["roles"] = { ["greeting"] = true },
    },
    [3271681465] = {
        ["english"] = { [1] = "Elder Morndeep spends time at the Ring of Law in Blackrock Depths." },
        ["text"] = "Старійшина Морндіп проводить час на Колі Закону в Глибинах Чорнокамінної гори.",
        ["npcs"] = { [1] = 15567 },
        ["roles"] = { ["greeting"] = true },
    },
    [2705099054] = {
        ["english"] = { [1] = "Gelman Stonehand would be the one to talk to. I think he has a house over in the Dwarven District but I can't remember exactly. I would check over there." },
        ["text"] = "Тобі треба поговорити з Ґелманом Кам'яноруким. Здається, він має будинок у Дворфівському районі, але точно не пам'ятаю. Я б пошукав там.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [33470106] = {
        ["english"] = { [1] = "Fishmaster Bassbait has had the waters here seeded with high quality Tastyfish so he can have his tournament.\010\010Once he gets his winner, I will give you silver for each five Tastyfish you bring me!\010" },
        ["text"] = "Рибний майстер Бассбейт зарибив тутешні води високоякісною смачнорибкою для свого турніру.\010\010Коли визначиться переможець, я даватиму тобі срібло за кожні п'ять смачнорибок, які принесеш!\010",
        ["npcs"] = { [1] = 15078 },
        ["roles"] = { ["greeting"] = true },
    },
    [289169980] = {
        ["english"] = { [1] = "Hello, what business brings you here?$B$BThis is an orphanage for the children of Outland who have lost their parents and have no one else to look after them.$B$BPerhaps you are here because you are considering adoption?" },
        ["text"] = "Привіт, що привело тебе сюди?$B$BЦе сиротинець для дітей Позамежжя, які втратили батьків і не мають більше нікого, хто міг би про них подбати.$B$BМожливо, ти прийшов, бо думаєш про усиновлення?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [977688906] = {
        ["english"] = { [1] = "Here are the final standings!$B$BThrall: $2200w$BCairne: $2201w$BSylvanas: $2202w$BTotal Horde: $2207w$B$BBolvar: $2203w$BMagni: $2204w$BTyrande: $2205w$BTotal Alliance: $2206w$B$BThe Alliance has the most popular hero!" },
        ["text"] = "Ось остаточні результати!$B$BТралл: $2200w$BКерн: $2201w$BСільвана: $2202w$BУсього Орда: $2207w$B$BБолвар: $2203w$BМаґні: $2204w$BТиранда: $2205w$BУсього Альянс: $2206w$B$BНайпопулярніший герой — в Альянсу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [946948681] = {
        ["english"] = { [1] = "Here among the craftsmen of Darnassus, there is a millenium of knowledge for the benefit of your chosen craft.  Now tell me, which craft do you find the most intriguing?" },
        ["text"] = "Тут, серед ремісників Дарнаса, зібрано тисячу років знань на користь обраного тобою ремесла. А тепер скажи, яке ремесло тебе найбільше цікавить?",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [2569242613] = {
        ["english"] = { [1] = "Druids?  I haven't seen any druids around here.  Although there is a district in Stormwind that the night elves have made their own." },
        ["text"] = "Друїди? Не бачив тут жодного. Хоча в Штормовії є район, який нічні ельфи облаштували під себе.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [4223104208] = {
        ["english"] = { [1] = "Don't... worry... about me..." },
        ["text"] = "Не... турбуйся... про мене...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2964252582] = {
        ["english"] = { [1] = "Due to incompatibility on your class specification, I am unable to help you rectify any situation you have with lack of ability." },
        ["text"] = "Через несумісність із вашою класовою спеціалізацією я не можу допомогти вам виправити проблему з відсутністю здібності.",
        ["npcs"] = { [1] = 5114 },
        ["roles"] = { ["greeting"] = true },
    },
    [727289528] = {
        ["english"] = { [1] = "Herbs, herbs, hmmm, let me see here. Ah yes, here it is. To date we have accumulated $2047w out of $2048w stranglekelp, $2053w out of $2055w purple lotuses, and $2057w out of $2058w arthas' tears needed." },
        ["text"] = "Трави, трави, гм-м, погляньмо. Ага, ось. Наразі ми зібрали $2047w із $2048w душителя, $2053w із $2055w пурпурового лотоса та $2057w із $2058w сліз Артаса.",
        ["npcs"] = { [1] = 15701 },
        ["roles"] = { ["greeting"] = true },
    },
    [3616973642] = {
        ["english"] = { [1] = "Fishing" },
        ["text"] = "Рибальство",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [40] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [523429827] = {
        ["english"] = { [1] = "Grand Foreman Puzik Gallywix finally intervened, taking the surplus of poisons to his tower, here at the Sludge Fen, in order to study and research the unstable nature of the toxins. A decision was finally reached to share the secret of the poison with the Defias Brotherhood in exchange for a very large supply of a stable, usable poison.$B$BKlaven Mortwake of the Defias Brotherhood was tasked with the job of altering the chemical properties of Zanzil's mixture." },
        ["text"] = "Головний бригадир Пузік Ґаллівікс нарешті втрутився й забрав надлишки отрут до своєї вежі тут, у Шламовій драговині, щоб дослідити нестабільну природу токсинів. Зрештою вирішили поділитися таємницею отрути з Братством Непокірних в обмін на великий запас стабільної придатної отрути.$B$BКлавен Мортвейк із Братства Непокірних отримав завдання змінити хімічні властивості суміші Занзіла.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3084954310] = {
        ["english"] = { [1] = "Drek'Thar is the military and spiritual leader of the Frostwolf Clan in Alterac, leading his brethren from Frostwolf Keep.$B$BIf he is defeated then the Horde forces in Alterac will crumble." },
        ["text"] = "Дрек'Тар — військовий і духовний провідник клану Морозних Вовків в Альтераку. Він керує своїми побратимами з форту Морозних Вовків.$B$BЯкщо його здолати, сили Орди в Альтераку розсиплються.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [633971117] = {
        ["english"] = { [1] = "Don't let the jingle of the bells take away from the jingle in your pocket!  Buy Smokywood Pastures treats for your Winter Veil festivities!" },
        ["text"] = "Нехай дзеленчання дзвіночків не заглушить дзвін монет у кишені! Купуйте ласощі «Пасовищ Димного Лісу» до святкування Зимового Покрову!",
        ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 },
        ["roles"] = { ["greeting"] = true },
    },
    [2340480512] = {
        ["english"] = { [1] = "Hello, how are you feeling today, $c? Well, I hope. You may be wondering what is going on here. There's a war at Ahn'Qiraj that is being planned and prepared for. We and the Horde are preparing as best we can for it.$B$BTo that end, the Alliance has asked me to supervise the collection of silk bandages here. To date we've managed to put together $2082w out of $2083w needed. Are you thinking about helping out?" },
        ["text"] = "Привіт, як почуваєшся сьогодні, $c? Сподіваюся, добре. Можливо, тобі цікаво, що тут відбувається. Ми готуємося до війни в Ан'Кіражі. І ми, і Орда робимо все, що можемо.$B$BДля цього Альянс доручив мені наглядати за збором шовкових бинтів. Наразі вдалося зібрати $2082w із потрібних $2083w. Допоможеш?",
        ["npcs"] = { [1] = 15452 },
        ["roles"] = { ["greeting"] = true },
    },
    [1283298886] = {
        ["english"] = { [1] = "Greetings, $c.  What may this humble servant of the Feathermoon Stronghold do for you today?" },
        ["text"] = "Вітаю, $c. Чим цей покірний слуга твердині Перомісяця може прислужитися вам сьогодні?",
        ["npcs"] = { [1] = 7879 },
        ["roles"] = { ["greeting"] = true },
    },
    [3806984645] = {
        ["english"] = { [1] = "Hero, I have urgent business with Corporal Splithoof." },
        ["text"] = "Герою, маю термінову справу до капрала Розщепленого Копита.",
        ["npcs"] = { [1] = 7572 },
        ["roles"] = { ["reply"] = true },
    },
    [3411977630] = {
        ["english"] = { [1] = "Hemet is the greatest hunter that I know.  We chanced upon each other in the hills of Winterspring back on Azeroth many moons ago.  He and I were stalking the same quarry: the great cat known as Rak'shiri.$B$BRather than fight each other over our prey, we made a wager out of it; whoever collected the frostsaber's skin would get to demand something of the other.  To my eternal shame, this is how I earned the nickname, Fitz.$B$BDo I look like a Fitz?" },
        ["text"] = "Гемет — найвеличніший мисливець, якого я знаю. Багато місяців тому ми випадково зустрілися в пагорбах Зимоключа на Азероті. Ми обидва вистежували одну здобич: великого кота Рак'шірі.$B$BЗамість того щоб битися за здобич, ми уклали парі: хто здобуде шкуру кригозуба, той може вимагати від іншого будь-чого. На мій вічний сором, саме так я отримав прізвисько Фітц.$B$BЯ схожий на Фітца?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3185299363] = {
        ["english"] = { [1] = "How dare you ask me for training, maggot? What were you hoping for, you slack-jawed yokel, a lecture on the proper uses of silverleaf? Out! You're lucky I don't thrash you senseless for wasting my time." },
        ["text"] = "Як ти смієш просити мене про навчання, хробаче? На що сподівався, тупорилий селюче — на лекцію про правильне використання срібнолисту? Геть! Тобі пощастило, що я не відлупцюю тебе до безтями за марнування мого часу.",
        ["npcs"] = { [1] = 1386 },
        ["roles"] = { ["greeting"] = true },
    },
    [1094004523] = {
        ["english"] = { [1] = "HELP!!!!" },
        ["text"] = "ДОПОМОЖІТЬ!!!!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3280247064] = {
        ["english"] = { [1] = "Gordo like picking flowers. Pick flowers kind of like killing." },
        ["text"] = "Ґордо любити збирати квіти. Збирати квіти — трохи як убивати.",
        ["npcs"] = { [1] = 10666 },
        ["roles"] = { ["greeting"] = true },
    },
    [3322769083] = {
        ["english"] = { [1] = "Gathering... information... on the Scourge.$b$bAlliance forces appeared...$b$bWe took cover - waited until they attacked the gate... then, we hit them from the rear.$b$bPinched between us... and the Scourge... it was too much for them....$b$b$g Brother:Sister;... it was... glorious." },
        ["text"] = "Збирали... відомості... про Скверну.$b$bЗ'явилися сили Альянсу...$b$bМи сховалися — чекали, поки вони атакують браму... а тоді вдарили з тилу.$b$bЗатиснуті між нами... і Скверною... вони не витримали....$b$b$g Брате:Сестро;... це було... славетно.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [983848379] = {
        ["english"] = { [1] = "Hail, champion! Have you ever thought about going into the gladiator business full time? You and I could make a mountain of gold." },
        ["text"] = "Вітаю, чемпіоне! Не думав зайнятися гладіаторською справою на повний час? Ми з тобою могли б заробити гору золота.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2542622990] = {
        ["english"] = { [1] = "Hello? " },
        ["text"] = "Привіт? ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [400573678] = {
        ["english"] = { [1] = "Greetings.  I am Chronos - He Who Never Forgets.  My memory is without flaw, and exact to the most minor detail.$B$BTrust me." },
        ["text"] = "Вітаю. Я Хронос — Той, Хто Ніколи Не Забуває. Моя пам'ять бездоганна й точна до найменшої дрібниці.$B$BПовірте мені.",
        ["npcs"] = { [1] = 14833 },
        ["roles"] = { ["greeting"] = true },
    },
    [3542854238] = {
        ["english"] = { [1] = "Go to the Freewind Post in Thousand Needles and you will find Elder Skyseer." },
        ["text"] = "Іди до застави Вільного Вітру в Тисячі Шипів — там знайдеш старійшину Небопровидця.",
        ["npcs"] = { [1] = 15573, [2] = 15578, [3] = 15586, [4] = 15604 },
        ["roles"] = { ["greeting"] = true },
    },
    [3165982058] = {
        ["english"] = { [1] = "Hello.  What brings you to Chillwind Camp today?" },
        ["text"] = "Привіт. Що привело тебе сьогодні до табору Студовію?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2711161703] = {
        ["english"] = { [1] = "Guns are a specialty of Buliwyf's! He's around this shop somewhere." },
        ["text"] = "Рушниці — спеціалізація Булівіфа! Він десь тут, у цій крамниці.",
        ["npcs"] = { [1] = 13084 },
        ["roles"] = { ["greeting"] = true },
    },
    [815639966] = {
        ["english"] = { [1] = "Hello, Rutgar. The Commander has sent me here to gather some information about his missing wife." },
        ["text"] = "Привіт, Рутґаре. Командир послав мене сюди зібрати відомості про його зниклу дружину.",
        ["npcs"] = { [1] = 15170 },
        ["roles"] = { ["reply"] = true },
    },
    [3154127832] = {
        ["english"] = { [1] = "Hello, Rayne. What brings the Cenarion Circle to the Plaguelands?" },
        ["text"] = "Привіт, Рейн. Що привело Кенарієве Коло до Чумнозем'я?",
        ["npcs"] = { [1] = 16135 },
        ["roles"] = { ["reply"] = true },
    },
    [618068289] = {
        ["english"] = { [1] = "Grrr..." },
        ["text"] = "Гррр...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [162237191] = {
        ["english"] = { [1] = "Dreadlords?  Perhaps you mean Lord Banehollow.  He sends his regards, and has a message for you..." },
        ["text"] = "Володарі жаху? Можливо, ви маєте на увазі лорда Бейнхоллоу. Він передає вітання і має для вас послання...",
        ["npcs"] = { [1] = 14523 },
        ["roles"] = { ["reply"] = true },
    },
    [837033567] = {
        ["english"] = { [1] = "Even my talents have a limit, and you have reached it. Congratulations, $N. Your next stop should be Camp Mojache in Feralas. The tauren Hahrana Ironhide lives there; she is renowned for her skill." },
        ["text"] = "Навіть мій талант має межу, і ти її досягнув. Вітаю, $N. Твоя наступна зупинка — табір Мохаче у Фераласі. Там живе тауренка Гаграна Залізна Шкура, відома своєю майстерністю.",
        ["npcs"] = { [1] = 3007 },
        ["roles"] = { ["greeting"] = true },
    },
    [1290590848] = {
        ["english"] = { [1] = "Fairweather and I are up here representing Sylvanaar's interests.$B$BThe druids have been more than accomodating, but allowing the Horde to travel through here gives me the willies." },
        ["text"] = "Ми з Фейрветером тут представляємо інтереси Сільванаара.$B$BДруїди були більш ніж гостинними, але від самої думки, що Орда проходить тут, мене морозить.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [813594593] = {
        ["english"] = { [1] = "Have a drink, $c.  It might be your last!" },
        ["text"] = "Випий, $c. Може, це твій останній кухоль!",
        ["npcs"] = { [1] = 9545 },
        ["roles"] = { ["greeting"] = true },
    },
    [1589158515] = {
        ["english"] = { [1] = "Greetings, $r.$B$BI have been expecting you." },
        ["text"] = "Вітаю, $r.$B$BЯ чекав на тебе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2141102821] = {
        ["english"] = { [1] = "Hurry! You should talk to Mekkatorque! If we don't start the assault soon, we're going to be late.$B$BAnd my boss HATES it when we're late!" },
        ["text"] = "Поквапся! Тобі треба поговорити з Меккаторком! Якщо скоро не почнемо наступ, запізнимося.$B$BА мій начальник НЕНАВИДИТЬ, коли ми запізнюємося!",
        ["npcs"] = { [1] = 11390 },
        ["roles"] = { ["greeting"] = true },
    },
    [2201621567] = {
        ["english"] = { [1] = "Gelkak's key slides into the vacant slot." },
        ["text"] = "Ключ Ґелкака входить у порожній паз.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3311045520] = {
        ["english"] = { [1] = "Excuse me?  We've been \"rescheduled for visitation\"?  What does that mean?!", [2] = "Excuse me? We've been \"rescheduled for visitation\"? What does that mean?!" },
        ["text"] = "Перепрошую? Нас «перепланували для відвідин»? Що це взагалі означає?!",
        ["npcs"] = { [1] = 7918 },
        ["roles"] = { ["reply"] = true },
    },
    [2989951396] = {
        ["english"] = { [1] = "Hello, traveler. Not many find me out this way.$B$BMy name is Rivern, and I train the Winterspring Frostsabers to become mounts.$B$BThese cats are the most feral and difficult to subdue of all the sabers. Only the most trusted and exalted may attempt to ride one.$B$BI will not sell such a mount to just anyone; no, you must work for it and earn your acceptance not only with me, but with the sabers themselves." },
        ["text"] = "Привіт, мандрівнику. Мало хто знаходить мене в цій глушині.$B$BМене звати Ріверн, і я навчаю зимоключних кригозубів бути верховими тваринами.$B$BЦі коти — найдикіші й найважчі для приручення серед усіх шаблезубів. Лише найбільш довірені й піднесені можуть спробувати осідлати одного.$B$BЯ не продам такого скакуна будь-кому; ти мусиш заслужити визнання і в мене, і в самих шаблезубів.",
        ["npcs"] = { [1] = 10618 },
        ["roles"] = { ["greeting"] = true },
    },
    [1890443273] = {
        ["english"] = { [1] = "Herbalism" },
        ["text"] = "Травництво",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [40] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [3849130224] = {
        ["english"] = { [1] = "Gladiators earn the right to wear equipment like mine by winning ranked arena matches." },
        ["text"] = "Гладіатори здобувають право носити спорядження на кшталт мого, перемагаючи в рейтингових боях на арені.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2365977664] = {
        ["english"] = { [1] = "Greetings, $N. I am Myolor Sunderfury, keeper of the Great Forge." },
        ["text"] = "Вітаю, $N. Я Міолор Лютолом, хранитель Великої Кузні.",
        ["npcs"] = { [1] = 11145 },
        ["roles"] = { ["greeting"] = true },
    },
    [799785125] = {
        ["english"] = { [1] = "Greetings!  If you are here to access gnome engineering schemata, please have your gnome engineer membership card ready for verification." },
        ["text"] = "Вітаю! Якщо ви прийшли по схеми гномської інженерії, приготуйте членську картку гномського інженера для перевірки.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3014187294] = {
        ["english"] = { [1] = "Greetings, $c.  Though time and drink have dulled my outer senses, my inner eyes remain strong." },
        ["text"] = "Вітаю, $c. Хоч час і випивка притупили мої зовнішні чуття, внутрішній зір лишається гострим.",
        ["npcs"] = { [1] = 8579 },
        ["roles"] = { ["greeting"] = true },
    },
    [654853478] = {
        ["english"] = { [1] = "Hello, $N! If you don't see it in my shop, chances are good I can get it!" },
        ["text"] = "Привіт, $N! Якщо чогось немає в моїй крамниці, майже напевно я зможу це дістати!",
        ["npcs"] = { [1] = 3413 },
        ["roles"] = { ["greeting"] = true },
    },
    [384538175] = {
        ["english"] = { [1] = "Elder Starweave can be found at the coastal village of Auberdine in Darkshore." },
        ["text"] = "Старійшину Зореплет можна знайти в прибережному селищі Аубердін на Темнобережжі.",
        ["npcs"] = { [1] = 15598, [2] = 15603, [3] = 15605 },
        ["roles"] = { ["greeting"] = true },
    },
    [2332584461] = {
        ["english"] = { [1] = "Hello, Frankal. I've heard that you might have some information as to the whereabouts of Mistress Natalia Mar'alith." },
        ["text"] = "Привіт, Франкале. Я чув, що ти можеш дещо знати про місцеперебування господині Наталії Мар'аліт.",
        ["npcs"] = { [1] = 15171 },
        ["roles"] = { ["reply"] = true },
    },
    [1594440277] = {
        ["english"] = { [1] = "Hurry, $r.$b$bTime is running out for me." },
        ["text"] = "Швидше, $r.$b$bУ мене майже не лишилося часу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2460758621] = {
        ["english"] = { [1] = "Elementium? I have not heard that word uttered from the mouth of a mortal in decades." },
        ["text"] = "Елементій? Я десятиліттями не чув цього слова з уст смертного.",
        ["npcs"] = { [1] = 14348 },
        ["roles"] = { ["greeting"] = true },
    },
    [2179121207] = {
        ["english"] = { [1] = "Hello, are you here to learn about the conflict in Bloodmyst?" },
        ["text"] = "Привіт, ти прийшов дізнатися про конфлікт на Кривавій Млі?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [397631908] = {
        ["english"] = { [1] = "Hello, $r.$b$bLet's get busy! No sense waiting around for supplies that may never arrive.$b$bI need my anvil in order to outfit our troops properly. Right now It's $3228w percent complete.$b$bAnd when the anvil is completed, there will be many more powerful items that I will be able to smith for you." },
        ["text"] = "Привіт, $r.$b$bДо роботи! Нема сенсу сидіти й чекати припасів, які можуть ніколи не прибути.$b$bМені потрібне ковадло, щоб як слід споряджати наших бійців. Зараз воно готове на $3228w відсотків.$b$bКоли ковадло буде завершено, я зможу кувати для тебе значно могутніші предмети.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1033551887] = {
        ["english"] = { [1] = "Greetings $c!  Welcome aboard the Cloudkisser.  Northrend can be a very harsh place.  I hope you have prepared yourself." },
        ["text"] = "Вітаю, $c! Ласкаво просимо на борт «Хмароцілуна». Нортренд може бути дуже суворим краєм. Сподіваюся, ви добре підготувалися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1711846732] = {
        ["english"] = { [1] = "Good work! Arthas now knows about the plagued grain in Stratholme, and is about to begin the culling. Something is still not quite right, though. I sense a foreign presence in this timeline besides us, and that must mean the Infinite Dragonflight are here somewhere." },
        ["text"] = "Гарна робота! Тепер Артас знає про заражене зерно в Стратгольмі й ось-ось почне очищення. Та щось усе ще негаразд. Я відчуваю в цій часовій лінії сторонню присутність, окрім нас, а це означає, що десь тут Нескінченна драконяча зграя.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1224600208] = {
        ["english"] = { [1] = "Hello young $g Master:Mistress;. I am Eva Sarkhoff and this is my husband, Lucien. It is a pleasure to make your acquaintance." },
        ["text"] = "Вітаю, юний $g пане:пані;. Я Єва Саркофф, а це мій чоловік Люсьєн. Приємно познайомитися.",
        ["npcs"] = { [1] = 11216 },
        ["roles"] = { ["greeting"] = true },
    },
    [1948872956] = {
        ["english"] = { [1] = "I am 100% confident that I wish to learn in the ways of goblin engineering." },
        ["text"] = "Я на 100% упевнений, що хочу вивчати гоблінську інженерію.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [1707167211] = {
        ["english"] = { [1] = "Hello, $n.$b$bNow that I've finished creating my anvil I can begin outfitting our troops. It's an important step, but there's still much to be done.$b$bMore importantly for you, there are new things that I can create, which you may be interested in." },
        ["text"] = "Привіт, $n.$b$bТепер, коли моє ковадло готове, я можу почати споряджати наші війська. Це важливий крок, але роботи ще багато.$b$bА для тебе важливіше те, що тепер я можу створювати нові речі, які тебе зацікавлять.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3661846561] = {
        ["english"] = { [1] = "Elder Bloodhoof can be found at Bloodhoof Village in Mulgore." },
        ["text"] = "Старійшину Криваве Копито можна знайти в селищі Криваве Копито в Мулґорі.",
        ["npcs"] = { [1] = 15580, [2] = 15582, [3] = 15588, [4] = 15597 },
        ["roles"] = { ["greeting"] = true },
    },
    [4014732458] = {
        ["english"] = { [1] = "Hey there, cutie!  Mind rubbing some lotion on my exposed areas?" },
        ["text"] = "Гей, красунчику! Не намастиш лосьйоном мої відкриті місця?",
        ["npcs"] = { [1] = 7770 },
        ["roles"] = { ["greeting"] = true },
    },
    [2914310796] = {
        ["english"] = { [1] = "Don't waste my time. I have research projects older than you. Go talk to Doctor Martin Felben in the Apothecarium of the Undercity. He's a Forsaken who can probably manage to teach you the basics." },
        ["text"] = "Не марнуй мого часу. У мене є дослідницькі проєкти старші за тебе. Іди до доктора Мартіна Фелбена в Аптекаріумі Підміста. Він Відречений і, мабуть, зможе навчити тебе основ.",
        ["npcs"] = { [1] = 2391 },
        ["roles"] = { ["greeting"] = true },
    },
    [2715942302] = {
        ["english"] = { [1] = "Greetings, friend!  Can I interest you in some ectoplasmic capacitors?  Or perhaps a nice omni-directional spectral assimilator? " },
        ["text"] = "Вітаю, друже! Може, зацікавишся ектоплазмовими конденсаторами? Або, можливо, гарним всеспрямованим спектральним асимілятором? ",
        ["npcs"] = { [1] = 16014 },
        ["roles"] = { ["greeting"] = true },
    },
    [2041395128] = {
        ["english"] = { [1] = "Hey there, $c! Looks like the Horde collected the last of their stuff, and now theirs and ours is being shipped over to Silithus as we speak. I'm told it'll be there in less than $2113w days, and then someone can ring that big gong near the Ahn'Qiraj gates to start the war." },
        ["text"] = "Привіт, $c! Схоже, Орда зібрала останні припаси, і тепер їхнє й наше вже перевозять до Силітусу. Кажуть, усе прибуде менш ніж за $2113w днів, а тоді хтось зможе вдарити у великий гонг біля брам Ан'Кіражу й почати війну.",
        ["npcs"] = { [1] = 15450 },
        ["roles"] = { ["greeting"] = true },
    },
    [3076224078] = {
        ["english"] = { [1] = "Him's at inner ring of Rogues' Quarter." },
        ["text"] = "Він на внутрішньому кільці Кварталу розбійників.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3157189138] = {
        ["english"] = { [1] = "Hello, $N. I train and care for young hippogryphs here; feel free to have a look around." },
        ["text"] = "Привіт, $N. Я навчаю й доглядаю тут молодих гіпогрифів; можеш оглянутися.",
        ["npcs"] = { [1] = 7916 },
        ["roles"] = { ["greeting"] = true },
    },
    [2012094365] = {
        ["english"] = { [1] = "Hello, hello!" },
        ["text"] = "Привіт-привіт!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [117373560] = {
        ["english"] = { [1] = "Here's to you!  Here's to me!  May we never disagree.$b$bBut if we do... BLAST YOU!  Here's to me." },
        ["text"] = "За тебе! За мене! Нехай ми ніколи не сваримося.$b$bА як посваримось... ТА ЩОБ ТЕБЕ! За мене.",
        ["npcs"] = { [1] = 2491 },
        ["roles"] = { ["greeting"] = true },
    },
    [3162476281] = {
        ["english"] = { [1] = "Greetings,  I am Vindicator Palanaar, a traveling paladin of the Light.  I am here to be of assistance to the night elves." },
        ["text"] = "Вітаю, я поборник Паланаар, мандрівний паладин Світла. Я тут, щоб допомагати нічним ельфам.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1337489638] = {
        ["english"] = { [1] = "Hello, $n! How can I help you today?" },
        ["text"] = "Привіт, $n! Чим можу допомогти сьогодні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2806911343] = {
        ["english"] = { [1] = "Hello, $c. Please excuse me as I am having a conversation with Rimblat. He believes that even this land is not beyond saving." },
        ["text"] = "Привіт, $c. Перепрошую, я зараз розмовляю з Рімблатом. Він вірить, що навіть цю землю ще можна врятувати.",
        ["npcs"] = { [1] = 16135 },
        ["roles"] = { ["greeting"] = true },
    },
    [2902496179] = {
        ["english"] = { [1] = "Having a good time?" },
        ["text"] = "Добре проводиш час?",
        ["npcs"] = { [1] = 14849 },
        ["roles"] = { ["greeting"] = true },
    },
    [3218253314] = {
        ["english"] = { [1] = "Happy Hallow's End!  Do you like my mask?  Very scary!" },
        ["text"] = "Щасливого Тиквовину! Подобається моя маска? Дуже страшна!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2363205363] = {
        ["english"] = { [1] = "Good idea!" },
        ["text"] = "Гарна думка!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2551250389] = {
        ["english"] = { [1] = "Hello, $c. If you haven't already, you really should speak with Farstrider Solanna." },
        ["text"] = "Привіт, $c. Якщо ще не говорив із далекоходицею Соланною, тобі справді варто це зробити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1635760519] = {
        ["english"] = { [1] = "Hello, $c. I've set up camp here at the Bulwark to make my preparations for my journey into the Plaguelands. I've heard rumor that a great human wizard took up residency in Hearthglen not terribly long ago. He was commissioned by the Scarlet Crusade to fashion their warriors and hunters new bows and guns. It's said that he completed a remarkable weapon before the Crusade killed him.$B$BI guess their mistrust of the arcane has grown." },
        ["text"] = "Привіт, $c. Я розбив табір тут, біля Бастіону, готуючись до подорожі в Чумнозем'я. Чув чутки, що не так давно в Гартґлені оселився могутній людський чарівник. Багряний Похід доручив йому створювати нові луки й рушниці для своїх воїнів та мисливців. Кажуть, він завершив одну видатну зброю, перш ніж Похід його вбив.$B$BСхоже, їхня недовіра до аркани лише зростає.",
        ["npcs"] = { [1] = 11608 },
        ["roles"] = { ["greeting"] = true },
    },
    [3100592855] = {
        ["english"] = { [1] = "Hello, $c. I trust that you bring good tidings concerning the Ahn'Qiraj War preparations. I myself have been placed in charge of all accumulation of rugged leather for the Horde; a task to which I feel uniquely qualified. Never underestimate the utility of a sharpened knife.$B$BAs to the rugged leather, we currently have $2073w out of $2074w needed." },
        ["text"] = "Привіт, $c. Сподіваюся, ти приніс добрі новини про підготовку до війни в Ан'Кіражі. Мені доручили весь збір грубої шкіри для Орди — завдання, для якого я, без сумніву, чудово підходжу. Ніколи не недооцінюй користі гострого ножа.$B$BЩодо грубої шкіри: зараз маємо $2073w із потрібних $2074w.",
        ["npcs"] = { [1] = 15525 },
        ["roles"] = { ["greeting"] = true },
    },
    [916384651] = {
        ["english"] = { [1] = "Elder Lunaro is at the Ruins of Tethys in Grizzly Hills." },
        ["text"] = "Старійшина Лунаро перебуває в руїнах Тетісу в Сивих пагорбах.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1566802937] = {
        ["english"] = { [1] = "For many hundreds of years Alassin has cared for the animals that our hunters befriend.  His care of animals is highly sought for by the hunters around here.  If you seek him as well, then look for him in the Cenarion Enclave." },
        ["text"] = "Сотні років Алассін доглядає за тваринами, яких приручають наші мисливці. Його вміння дуже цінують тутешні мисливці. Якщо шукаєш його — заглянь до Кенарієвого анклаву.",
        ["npcs"] = { [1] = 4262 },
        ["roles"] = { ["greeting"] = true },
    },
    [2812841490] = {
        ["english"] = { [1] = "Eh?" },
        ["text"] = "Га?",
        ["npcs"] = { [1] = 14368 },
        ["roles"] = { ["reply"] = true },
    },
    [2134696599] = {
        ["english"] = { [1] = "Hello, $c. I trust that you are enjoying youself? What do you think of the party? I do so hope that we aren't running out of anything. Nothing kills a fete faster than running out of drinks and hors d'oeuvres, wouldn't you say?$B$BYes, well, I must be about attending to my other guests. Do enjoy your stay." },
        ["text"] = "Привіт, $c. Сподіваюся, тобі весело? Ну як тобі свято? Дуже сподіваюся, що в нас нічого не закінчується. Ніщо так не вбиває вечірку, як брак напоїв і закусок, еге ж?$B$BЩо ж, мені треба приділити увагу іншим гостям. Приємного відпочинку.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2388269577] = {
        ["english"] = { [1] = "Hello, $C.  I hope you've come to bolster our ranks.  Beasts and thieves are spilling into our beloved Elwynn, and we barely have enough men to keep the roads safe!$B$BAnd if you haven't done so, read that notice about Hogger.  He's a beast in yonder woods that must be dealt with." },
        ["text"] = "Привіт, $C. Сподіваюся, ти прийшов підсилити наші лави. Звірі й злодії заполонили наш улюблений Ельвинн, а людей ледве вистачає, щоб дороги лишалися безпечними!$B$BІ якщо ще не читав, поглянь на оголошення про Гоґґера. Цю потвору в лісах неподалік треба знищити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2325001437] = {
        ["english"] = { [1] = "Farewell.", [2] = "Farewell.\010" },
        ["text"] = "Прощавайте.",
        ["npcs"] = { [1] = 15864 },
        ["roles"] = { ["reply"] = true },
    },
    [2743842285] = {
        ["english"] = { [1] = "Hands off the cloak! Yes, yes, I know that you want one too. Everybody wants one of my cloaks. Believe me, person of low moral and social standing, one day I will make my fortune from the sale of my cloaks. Everyone from here to Ironforge will know the name of Bartolo Ginsetti. The Ginsetti label will be coveted by all!" },
        ["text"] = "Руки геть від плаща! Так-так, знаю, ти теж такий хочеш. Усі хочуть мої плащі. Повір, людино низьких моральних і суспільних якостей, одного дня я розбагатію на продажу плащів. Відсюди до Залізогарта всі знатимуть ім'я Бартоло Джінсетті. Усі жадатимуть речей із маркою Джінсетті!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2867131082] = {
        ["english"] = { [1] = "Find Red Canyon Mining northeast of the lake in the Valley of Honor.  Speak to Makaru there." },
        ["text"] = "Знайди копальню Червоного Каньйону на північний схід від озера в Долині Честі. Там поговори з Макару.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1933949460] = {
        ["english"] = { [1] = "Hi there! I'm glad you came back, $n. Tell me, have you completed the first quest I gave you? If you have, I might have a second quest for you..." },
        ["text"] = "Привіт! Радий, що ти повернувся, $n. Скажи, ти виконав перше завдання, яке я дав? Якщо так, можливо, для тебе знайдеться друге...",
        ["npcs"] = { [1] = 8737 },
        ["roles"] = { ["greeting"] = true },
    },
    [598856713] = {
        ["english"] = { [1] = "Hmmm, I think you will need to go up to Thunder Bluff to learn that.  Head north on the road out of Bloodhoof Village.  It will take you to the base of Thunder Bluff.  Ride the elevator to the top and you should be able to ask any of the Bluffwatchers there for further assistance." },
        ["text"] = "Гм-м, думаю, для цього треба піднятися до Громового Бескиду. Вийди дорогою на північ із селища Криваве Копито. Вона приведе до підніжжя Громового Бескиду. Підіймися ліфтом нагору й запитай когось із вартових Бескиду.",
        ["npcs"] = { [1] = 3212, [2] = 3215, [3] = 3217, [4] = 3218, [5] = 3219, [6] = 3220, [7] = 3221, [8] = 3222, [9] = 3223, [10] = 3224 },
        ["roles"] = { ["greeting"] = true },
    },
    [2812928453] = {
        ["english"] = { [1] = "Greetings, $c. Have you spoken with Fahrad yet?" },
        ["text"] = "Вітаю, $c. Ти вже говорив із Фаградом?",
        ["npcs"] = { [1] = 6766 },
        ["roles"] = { ["greeting"] = true },
    },
    [967410879] = {
        ["english"] = { [1] = "Have you spoken to either of my acolytes inside the tower yet, $N? We cannot complete your orb until you've done one of their tasks. Speak to them now, if you're ready." },
        ["text"] = "Ти вже говорив із кимось із моїх служителів у вежі, $N? Ми не зможемо завершити твою сферу, доки ти не виконаєш одне з їхніх завдань. Поговори з ними, якщо готовий.",
        ["npcs"] = { [1] = 6266 },
        ["roles"] = { ["greeting"] = true },
    },
    [1789457104] = {
        ["english"] = { [1] = "Hello, $c, good of you to show up. Allow me to be succinct; we are gathering supplies for the Ahn'Qiraj war effort. We wouldn't want to have more casualties than necessary, now would we? I have the responsibility of coordinating the collection of $2086w mageweave bandages. To date we have garnered $2085w. Care to assist?" },
        ["text"] = "Привіт, $c, добре, що прийшов. Буду коротким: ми збираємо припаси для війни в Ан'Кіражі. Не хочемо зайвих жертв, правда? Я відповідаю за збір $2086w бинтів із маготканини. Наразі маємо $2085w. Допоможеш?",
        ["npcs"] = { [1] = 15529 },
        ["roles"] = { ["greeting"] = true },
    },
    [3966803772] = {
        ["english"] = { [1] = "Hello, $c!  Welcome to the races at the Shimmering Flats!" },
        ["text"] = "Привіт, $c! Ласкаво просимо на перегони в Мерехтливих рівнинах!",
        ["npcs"] = { [1] = 4419 },
        ["roles"] = { ["greeting"] = true },
    },
    [4117830429] = {
        ["english"] = { [1] = "Evenin', Gov'na." },
        ["text"] = "Добривечір, пане.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [896841511] = {
        ["english"] = { [1] = "Hello, $c! I've went around and asked, and it looks like all of us here have collected everything that the Alliance needs to prepare for the Ahn'Qiraj War. Now we just need to encourage the Horde to do the same and then we'll be able to ship it all over to Cenarion Hold in Silithus." },
        ["text"] = "Привіт, $c! Я всіх тут розпитав, і схоже, ми зібрали все, що Альянсу потрібно для підготовки до війни в Ан'Кіражі. Тепер треба тільки підштовхнути Орду зробити те саме, а потім ми зможемо відправити все до Кенарійської цитаделі в Силітусі.",
        ["npcs"] = { [1] = 15450 },
        ["roles"] = { ["greeting"] = true },
    },
    [4168554863] = {
        ["english"] = { [1] = "Greetings, noble $c.  This humble servant of the Cenarion Circle wishes blessings and bounties be given unto you and yours." },
        ["text"] = "Вітаю, шляхетний $c. Цей покірний слуга Кенарієвого Кола бажає благословення й достатку тобі та твоїм близьким.",
        ["npcs"] = { [1] = 9087 },
        ["roles"] = { ["greeting"] = true },
    },
    [3609317592] = {
        ["english"] = { [1] = "Elder Primestone has spent many years in the Crystal Vale in Silithus." },
        ["text"] = "Старійшина Прадавній Камінь провів багато років у Кришталевій долині в Силітусі.",
        ["npcs"] = { [1] = 15583, [2] = 15599 },
        ["roles"] = { ["greeting"] = true },
    },
    [137938957] = {
        ["english"] = { [1] = "Gnomeregan" },
        ["text"] = "Ґномреґан",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["reply"] = true },
    },
    [1899750100] = {
        ["english"] = { [1] = "Hello! You're pretty strong and nice and stuff. I like you. Lets stay friends, okay?" },
        ["text"] = "Привіт! Ти доволі сильний і добрий, ну й таке. Ти мені подобаєшся. Давай залишимося друзями, гаразд?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2965769778] = {
        ["english"] = { [1] = "Elder Stonefort has taken to the dungeons of Blackrock Spire." },
        ["text"] = "Старійшина Кам'яна Твердиня оселився в підземеллях Чорнокамінного Шпиля.",
        ["npcs"] = { [1] = 15567 },
        ["roles"] = { ["greeting"] = true },
    },
    [347887204] = {
        ["english"] = { [1] = "Greetings $G brother:sister;. How can we be of service?" },
        ["text"] = "Вітаю, $G брате:сестро;. Чим можемо прислужитися?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [391075196] = {
        ["english"] = { [1] = "Etched into a tablet of pure gold was the embodiment of my remorse, shame, regret, and sorrow. Unfortunately, the Twilight's Hammer found the tablet and branded me a blasphemer. I was summarily executed, my prayer to Elune incomplete. I am now bound to this world as a spirit, unable to transcend to the Nether; held in this cage as a warning to all that would betray the faith of the Twilight's Hammer.\010" },
        ["text"] = "На табличці з чистого золота було викарбувано втілення мого каяття, сорому, жалю й скорботи. На жаль, Сутінковий Молот знайшов табличку й оголосив мене богохульником. Мене негайно стратили, і моя молитва до Елуни лишилася незавершеною. Тепер я прив'язаний до цього світу як дух і не можу перейти в Крутоверть; мене тримають у цій клітці як пересторогу всім, хто зрадить віру Сутінкового Молота.\010",
        ["npcs"] = { [1] = 8436 },
        ["roles"] = { ["greeting"] = true },
    },
    [2525619529] = {
        ["english"] = { [1] = "Hello!  So good to meet you!" },
        ["text"] = "Привіт! Дуже радий знайомству!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2816768809] = {
        ["english"] = { [1] = "Greetings honored one.  Turak Runetotem and the other druids have been expecting you at the Hall of Elders on Elder Rise." },
        ["text"] = "Вітаю, шановний. Турак Рунічний Тотем та інші друїди чекають на вас у Залі старійшин на Верхів'ї старійшин.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [783606437] = {
        ["english"] = { [1] = "Greetings, my friend.  May the Dawn keep you well in these troubled times." },
        ["text"] = "Вітаю, друже. Нехай Світанок береже тебе в ці тривожні часи.",
        ["npcs"] = { [1] = 10431 },
        ["roles"] = { ["greeting"] = true },
    },
    [1208892090] = {
        ["english"] = { [1] = "Druid" },
        ["text"] = "Друїд",
        ["npcs"] = { [1] = 68, [2] = 1423, [3] = 1976, [4] = 2808, [5] = 3084, [6] = 3212, [7] = 3215, [8] = 3217, [9] = 3218, [10] = 3219, [11] = 3220, [12] = 3221, [13] = 3222, [14] = 3223, [15] = 3224, [16] = 3571, [17] = 4262, [18] = 6272, [19] = 6740, [20] = 8931 },
        ["roles"] = { ["reply"] = true },
    },
    [2774571079] = {
        ["english"] = { [1] = "Hello!  And welcome!  I'm afraid my booth is not open... many repairs are needed...$B$BBut I am still bound by blood oath to put a smile on your face.  So please, smile, or I must cut off my hand and consume no living flesh until it regenerates..." },
        ["text"] = "Привіт і ласкаво просимо! Боюся, мій прилавок зачинений... треба багато чого полагодити...$B$BАле кровна клятва все одно зобов'язує мене викликати усмішку на твоєму обличчі. Тож, будь ласка, усміхнися, інакше я мушу відрубати собі руку й не їсти живої плоті, доки вона не відросте...",
        ["npcs"] = { [1] = 14841 },
        ["roles"] = { ["greeting"] = true },
    },
    [244968296] = {
        ["english"] = { [1] = "Greetings $N" },
        ["text"] = "Вітаю, $N",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2937636264] = {
        ["english"] = { [1] = "Faire's a coming!" },
        ["text"] = "Ярмарок наближається!",
        ["npcs"] = { [1] = 14843, [2] = 14849 },
        ["roles"] = { ["greeting"] = true },
    },
    [3017486530] = {
        ["english"] = { [1] = "Even if you somehow managed to free us without defeating C'Thun, we would focus all of our powers to see the beast banished back to the hell from whence it came - AT ANY COST." },
        ["text"] = "Навіть якби вам якимось дивом вдалося звільнити нас, не перемігши К'Туна, ми зосередили б усю силу, щоб вигнати цю потвору назад у пекло, звідки вона прийшла — ЗА БУДЬ-ЯКУ ЦІНУ.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2452955234] = {
        ["english"] = { [1] = "Having a bad day? Try some cherry pie." },
        ["text"] = "День не задався? Скуштуй вишневого пирога.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [80267346] = {
        ["english"] = { [1] = "Don't look so surprised to see me here, $r. The coming of the draenei and their alliance with my people was foretold by Kurz the Revelator." },
        ["text"] = "Не дивуйся так, побачивши мене тут, $r. Прихід дренеїв і їхній союз із моїм народом провістив Курц Одкровенний.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3094620717] = {
        ["english"] = { [1] = "Hello there, my name is Petra.  To my right is my kodo, Dadanga.  We're with Marshal Expeditions - been so for a few years now, ever since Dadanga was a babe.$B$BIf you have any lit torches or any open sources of flame, I'd like to ask you to keep them stashed if you could.  Dadanga dislikes smoke." },
        ["text"] = "Привіт, мене звати Петра. Праворуч від мене мій кодо Даданґа. Ми з експедицією Маршалла вже кілька років, відтоді як Даданґа був малюком.$B$BЯкщо маєш запалені смолоскипи чи будь-яке відкрите полум'я, прошу сховати їх. Даданґа не любить диму.",
        ["npcs"] = { [1] = 9273 },
        ["roles"] = { ["greeting"] = true },
    },
    [648781184] = {
        ["english"] = { [1] = "Finally! Put some fingers in your ears, your brain mighta just grown five sizes and I'm worried it might leak out.$B$BSo, the Dark Irons spared his life and took him prisoner. Their leader, some self-important, uppity fella named Thauris-something, took Ironfoe for himself. And that was the last I saw of ol' Windsor... *hic* 'scuse me.\010" },
        ["text"] = "Нарешті! Заткни вуха пальцями — здається, твій мозок щойно виріс у п'ять разів, і я боюся, що він витече.$B$BОтже, Темне Залізо лишило його живим і взяло в полон. Їхній ватажок, якийсь пихатий задавака на ім'я Тауріс-щось-там, забрав Залізолом собі. І це востаннє, коли я бачив старого Віндзора... *гик* перепрошую.\010",
        ["npcs"] = { [1] = 9563 },
        ["roles"] = { ["greeting"] = true },
    },
    [1706458839] = {
        ["english"] = { [1] = "I am Highborne, $r. It has no meaning now. There was a time, though, when this world was ruled by Highborne. Ten thousand years past..." },
        ["text"] = "Я Високородний, $r. Тепер це нічого не означає. Але був час, коли цим світом правили Високородні. Десять тисяч років тому...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3302185948] = {
        ["english"] = { [1] = "Helene Peltskinner has had years of experience skinning animals for Adele Fielder to make leather items.  You can find Helene in her house by Crystal Lake." },
        ["text"] = "Гелен Шкуродерка роками знімала шкури з тварин для Адель Філдер, щоб та шила шкіряні речі. Гелен знайдеш у її будинку біля Кришталевого озера.",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3061967600] = {
        ["english"] = { [1] = "Every two years the Spirits of Competition grow especially fervent... and now is that time! Both Alliance and Horde wear this tabard into the Battlegrounds to honor the spirits, seeking to defeat all enemies and earn their favor." },
        ["text"] = "Раз на два роки Духи Змагання стають особливо завзятими... і цей час настав! І Альянс, і Орда вдягають цю гербову накидку на полях бою, щоб ушанувати духів, перемогти всіх ворогів і здобути їхню прихильність.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3487869099] = {
        ["english"] = { [1] = "Glug bmrgl grggl!" },
        ["text"] = "Ґлуґ бмрґл ґрґґл!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1711687396] = {
        ["english"] = { [1] = "Do you still need some help shipping kegs from Kharanos?" },
        ["text"] = "Вам іще потрібна допомога з перевезенням барилець із Хараноса?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3360191540] = {
        ["english"] = { [1] = "Dwarves!!!  Now you're telling me that dwarves originally came from the Earthen?!" },
        ["text"] = "Дворфи!!! Тепер ви кажете, що дворфи спочатку походять від земельників?!",
        ["npcs"] = { [1] = 7172 },
        ["roles"] = { ["reply"] = true },
    },
    [36665049] = {
        ["english"] = { [1] = "Greetings mage.  Shall I provide you with further insight into the world of magic?" },
        ["text"] = "Вітаю, магу. Бажаєш дізнатися більше про світ магії?",
        ["npcs"] = { [1] = 198, [2] = 328, [3] = 331, [4] = 5497, [5] = 5498 },
        ["roles"] = { ["greeting"] = true },
    },
    [2653807996] = {
        ["english"] = { [1] = "Greetings, $Gsir:miss;. I am Master Xylem's apprentice Nyrill. If you have any concerns, please feel free to bring them up with the master.$B$BI will be here to serve you when you're ready to return down to the base of the mountain." },
        ["text"] = "Вітаю, $Gпане:пані;. Я Нірілл, учень майстра Ксилема. Якщо вас щось турбує, сміливо звертайтеся до майстра.$B$BЯ буду тут, щоб служити вам, коли будете готові повернутися до підніжжя гори.",
        ["npcs"] = { [1] = 8399 },
        ["roles"] = { ["greeting"] = true },
    },
    [985632587] = {
        ["english"] = { [1] = "Hi $N!$B$BI have to work on my devices, but eventually... I'm going to need someone to get me dragon eggs!" },
        ["text"] = "Привіт, $N!$B$BМені треба попрацювати над своїми пристроями, але згодом... знадобиться хтось, хто дістане для мене драконячі яйця!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1228422324] = {
        ["english"] = { [1] = "Fineous has what you need, friend." },
        ["text"] = "У Фінеуса є те, що тобі потрібно, друже.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2407156561] = {
        ["english"] = { [1] = "Fishing is just so pleasant, mon. You know? I owe my state of bliss to my mentor, the greatest angler in the whole world - Nat Pagle. Have you heard of him, mon?$B$BIf you be looking for enlightenment, Nat Pagle be the one who gonna show you the way. " },
        ["text"] = "Рибалити так приємно, мон. Знаєш? Своїм блаженством я завдячую наставнику — найкращому рибалці у світі, Нату Пеґлу. Чув про нього, мон?$B$BЯкщо шукаєш просвітлення, Нат Пеґл покаже шлях. ",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3326416178] = {
        ["english"] = { [1] = "Hello $c, and welcome to the Darkmoon Faire. There is so much to do here at the faire that it can be a little overwhelming for our first time visitors. That's why I'm here to help. Do you have any questions?" },
        ["text"] = "Привіт, $c, і ласкаво просимо на ярмарок Темного Місяця. Тут стільки всього, що новачкам легко розгубитися. Саме тому я тут — допомогти. Маєш запитання?",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["greeting"] = true },
    },
    [1831586545] = {
        ["english"] = { [1] = "Hello there $g mister : ma'am;... do you have a little time that you could help us out?  Please?" },
        ["text"] = "Привіт, $g пане : пані;... маєте хвилинку, щоб нам допомогти? Будь ласка?",
        ["npcs"] = { [1] = 8965 },
        ["roles"] = { ["greeting"] = true },
    },
    [1399235561] = {
        ["english"] = { [1] = "Heh, bombs, us like bombs.  Graham Van Talen show you how to make.  He in outer ring of Rogues' Quarter." },
        ["text"] = "Хех, бомби, ми любити бомби. Ґрем Ван Тален покаже, як робити. Він на зовнішньому кільці Кварталу розбійників.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [1824257048] = {
        ["english"] = { [1] = "Hello Sovik, I wish to browse your goods." },
        ["text"] = "Привіт, Совіку, я хочу оглянути твої товари.",
        ["npcs"] = { [1] = 3413 },
        ["roles"] = { ["reply"] = true },
    },
    [3994018442] = {
        ["english"] = { [1] = "Hello once again, $N.  I sense that the flow of time remains threatened by forces that are quite powerful indeed.  Your continued assistance is always welcomed by the bronze dragonflight.$B$BWhile the past is set in its ways, the future is always changing.  The decisions you make in the here and now help guide that change." },
        ["text"] = "Знову привіт, $N. Я відчуваю, що плин часу досі перебуває під загрозою дуже могутніх сил. Бронзова драконяча зграя завжди рада твоїй подальшій допомозі.$B$BМинуле вже усталене, але майбутнє постійно змінюється. Рішення, які ти приймаєш тут і зараз, спрямовують ці зміни.",
        ["npcs"] = { [1] = 10667 },
        ["roles"] = { ["greeting"] = true },
    },
    [3568580208] = {
        ["english"] = { [1] = "Hello friend! What can we do for you?" },
        ["text"] = "Привіт, друже! Чим можемо допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [773317130] = {
        ["english"] = { [1] = "I am Kilram, master of the axe." },
        ["text"] = "Я Кілрам, майстер сокири.",
        ["npcs"] = { [1] = 11192 },
        ["roles"] = { ["greeting"] = true },
    },
    [2880358566] = {
        ["english"] = { [1] = "Hellfire Peninsula is a shattered realm - ruthless and unforgiving to its inhabitants. Be sure to repair and stock up on supplies before venturing out." },
        ["text"] = "Півострів Пекельного Вогню — розбитий край, безжальний і немилосердний до своїх мешканців. Перед виходом обов'язково полагодь спорядження й запасися припасами.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2232225616] = {
        ["english"] = { [1] = "Hello there! My name's Jenna! And you? " },
        ["text"] = "Привіт! Мене звати Дженна! А тебе? ",
        ["npcs"] = { [1] = 11037 },
        ["roles"] = { ["greeting"] = true },
    },
    [800935064] = {
        ["english"] = { [1] = "Don't be alarmed... while my gryphons may not be entirely whole, they will still carry you faithfully to your destination. Tell me... which tower do you seek?" },
        ["text"] = "Не лякайтеся... мої грифони, може, й не зовсім цілі, та все одно вірно доправлять вас куди треба. Скажіть... яку вежу ви шукаєте?",
        ["npcs"] = { [1] = 17209 },
        ["roles"] = { ["greeting"] = true },
    },
    [2863526885] = {
        ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of the Gnomeregan Exiles.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from the Gnomeregan Exiles for your duty and service.\010" },
        ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє вигнанців Ґномреґана. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Альянсу.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання вигнанців Ґномреґана.\010",
        ["npcs"] = { [1] = 15733, [2] = 15763 },
        ["roles"] = { ["greeting"] = true },
    },
    [1140235162] = {
        ["english"] = { [1] = "Heh, heh... Quite the inquisitive one, aren't ya, $n? Well, here's what you need to do.$B$BNorth of here, in the old ruins, lives a very disagreeable gnoll by the name of Miblon Snarltooth. He guards the only Evoroot I know of, but he watches it night and day! Seems like he never even sleeps!$B$BWhat you can do, is bribe him. I can sell you some bait that he'll find tasty -- just put it down near him and that will distract him long enough for you to grab the Evoroot. Good luck!" },
        ["text"] = "Хе-хе... Допитливий ти, еге ж, $n? Ось що треба зробити.$B$BНа північ звідси, у старих руїнах, живе дуже непривітний ґнол на ім'я Міблон Рикозуб. Він охороняє єдиний відомий мені евокорінь і стереже його вдень і вночі! Здається, взагалі не спить!$B$BМожеш його підкупити. Я продам тобі наживку, яка йому сподобається — поклади її поруч, це відволіче його достатньо довго, щоб ти забрав евокорінь. Щасти!",
        ["npcs"] = { [1] = 7775 },
        ["roles"] = { ["greeting"] = true },
    },
    [2542830926] = {
        ["english"] = { [1] = "Hello stranger, and welcome to the untamed majesty of Un'Goro Crater!$B$BMy name is Williden Marshal.  My sister, our companions, and I make up Marshal Expeditions - scientists and explorers of Azeroth's wild and great unknown.$B$BWe've hit a bit of a rough patch here, and we're looking for some help if you have the time!" },
        ["text"] = "Привіт, чужинцю, і ласкаво просимо до неприборканої величі кратера Ун'Ґоро!$B$BМене звати Вілліден Маршалл. Я, моя сестра та наші супутники — експедиція Маршалла, науковці й дослідники великих незвіданих земель Азероту.$B$BУ нас тут почалися труднощі, і якщо маєш час — нам не завадила б допомога!",
        ["npcs"] = { [1] = 9270 },
        ["roles"] = { ["greeting"] = true },
    },
    [1157919168] = {
        ["english"] = { [1] = "Hearthglen?? But...", [2] = "Hearthglen?? But...\010" },
        ["text"] = "Гартґлен?? Але...",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["reply"] = true },
    },
    [1595509399] = {
        ["english"] = { [1] = "Hey Hey Hey!  I am here to promote a fabulous fishing tournament in Stranglethorn but you need to be tough enough to survive there and have enough skill in fishing to fish those waters.$B$B Come back later when you are more qualified!\010\010" },
        ["text"] = "Гей-гей-гей! Я тут рекламую неймовірний рибальський турнір у Тернистій долині, але треба бути достатньо сильним, щоб там вижити, і достатньо вправним рибалкою, щоб ловити в тих водах.$B$BПовертайся пізніше, коли будеш краще підготовлений!\010\010",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2570975705] = {
        ["english"] = { [1] = "Gul'dan" },
        ["text"] = "Ґул'дан",
        ["npcs"] = { [1] = 4488 },
        ["roles"] = { ["reply"] = true },
    },
    [1986660612] = {
        ["english"] = { [1] = "Exalted." },
        ["text"] = "Піднесення.",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["reply"] = true },
    },
    [750108340] = {
        ["english"] = { [1] = "Erma does all the caring for animals around here.  She's right outside the Lion's Pride Inn if you need to speak with her." },
        ["text"] = "Ерма тут доглядає всіх тварин. Якщо треба з нею поговорити, вона просто біля таверни «Гордість Лева».",
        ["npcs"] = { [1] = 1423 },
        ["roles"] = { ["greeting"] = true },
    },
    [3234095561] = {
        ["english"] = { [1] = "Hrm, I'm listening. What is this offer?" },
        ["text"] = "Грм, я слухаю. Що це за пропозиція?",
        ["npcs"] = { [1] = 12944 },
        ["roles"] = { ["reply"] = true },
    },
    [4050269514] = {
        ["english"] = { [1] = "Fishing is a sport for the old who have not died in battle!  Go find Lumak on the lake in the Valley of Honor." },
        ["text"] = "Рибальство — спорт для старих, які не загинули в бою! Іди до Лумака біля озера в Долині Честі.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [2459534182] = {
        ["english"] = { [1] = "Hey mon, you ready to try da best brew in all da realms?" },
        ["text"] = "Гей, мон, готовий скуштувати найкраще вариво в усіх світах?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [783557375] = {
        ["english"] = { [1] = "Give me a moment; there are a lot of numbers to remember here. It looks like we have $2066w of $2067w heavy leather skins collected. As well, we have $2070w out of $2071w thick leather, and $2073w of $2074w rugged leather stockpiled." },
        ["text"] = "Дай хвилинку, тут стільки чисел треба пам'ятати. Схоже, ми зібрали $2066w із $2067w важких шкур. Також маємо $2070w із $2071w товстої шкіри та $2073w із $2074w грубої шкіри.",
        ["npcs"] = { [1] = 15700 },
        ["roles"] = { ["greeting"] = true },
    },
    [688918623] = {
        ["english"] = { [1] = "Hello, $N. Welcome to Refuge Pointe." },
        ["text"] = "Привіт, $N. Ласкаво просимо до Притулку.",
        ["npcs"] = { [1] = 2788 },
        ["roles"] = { ["greeting"] = true },
    },
    [3925425667] = {
        ["english"] = { [1] = "I almost have enough supplies to upgrade to champion units." },
        ["text"] = "Мені майже вистачає припасів, щоб покращити війська до рівня чемпіонів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1155134765] = {
        ["english"] = { [1] = "He grows fatter and more corrupt with each passing day. Ye can smell the stink comin' off o' his body. He be dirty, an' I dun just mean he be needin' a wash.$B$BEnough babblin' from Hulfdan. Where did ye come from and how can me help ye, $c?\010" },
        ["text"] = "Він щодня стає товстішим і все більш оскверненим. Від нього тхне за версту. Він брудний — і я не лише про те, що йому б не завадило помитися.$B$BДосить балачок Гулфдана. Звідки ти прийшов і чим я можу допомогти, $c?\010",
        ["npcs"] = { [1] = 5165 },
        ["roles"] = { ["greeting"] = true },
    },
    [1417368282] = {
        ["english"] = { [1] = "Greetings. How may we of the Royal Exchange Bank assist you today?" },
        ["text"] = "Вітаю. Чим Королівський обмінний банк може вам сьогодні допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1751932249] = {
        ["english"] = { [1] = "Go to inner ring of War Quarter.  Brom Killian there." },
        ["text"] = "Іди до внутрішнього кільця Військового кварталу. Там Бром Кілліан.",
        ["npcs"] = { [1] = 5624 },
        ["roles"] = { ["greeting"] = true },
    },
    [3740895908] = {
        ["english"] = { [1] = "Exalted" },
        ["text"] = "Піднесення",
        ["npcs"] = { [1] = 11536 },
        ["roles"] = { ["reply"] = true },
    },
    [805390248] = {
        ["english"] = { [1] = "Gonna make a guild, are ya? Good luck to ya then!\010\010Talk to Aldwin Laughlin in the Stormwind Vistor's Center. It's in the Trade District right as you come in from the Valley of Heroes." },
        ["text"] = "Гільдію створюєш, еге ж? Ну, тоді щасти!\010\010Поговори з Олдвіном Лафліном у Центрі відвідувачів Штормовію. Він у Торговому районі, просто при вході з Долини Героїв.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [1307164680] = {
        ["english"] = { [1] = "He called himself Gearmaster Mechazod. When we arrived he was busy transforming the survivors into mechanical beings!$B$BHe greeted us warmly and explained that he was one of the first gnomes ever to be created by something he called \"The Grand Architect\", a Titan keeper from within the halls of fabled Ulduar.$B$BApparently, he was the blockage that my team had accidentally sucked up from where he'd malfunctioned thousands of years ago. It was just our luck that we'd built the pumping station right above him." },
        ["text"] = "Він називав себе Мехазодом, Майстром Механізмів. Коли ми прибули, він саме перетворював уцілілих на механічних істот!$B$BВін привітно зустрів нас і пояснив, що був одним із перших гномів, створених тим, кого він називав «Великим Архітектором», титанічним хранителем із залів легендарного Ульдуару.$B$BВиявилося, саме він був тією перешкодою, яку моя команда випадково всмоктала з місця, де він зламався тисячі років тому. І треба ж було нам збудувати насосну станцію просто над ним.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2974679141] = {
        ["english"] = { [1] = "Greetings, little one.  You have business with the Waterlords?" },
        ["text"] = "Вітаю, малий. Маєш справу до Володарів Води?",
        ["npcs"] = { [1] = 13322 },
        ["roles"] = { ["greeting"] = true },
    },
    [2973102699] = {
        ["english"] = { [1] = "Elder Bladeswift wanders the paths of Darnassus atop Teldrassil." },
        ["text"] = "Старійшина Швидкоклинок мандрує стежками Дарнаса на вершині Тельдрассіля.",
        ["npcs"] = { [1] = 15562, [2] = 15595, [3] = 15600, [4] = 15601, [5] = 15871 },
        ["roles"] = { ["greeting"] = true },
    },
    [1610577851] = {
        ["english"] = { [1] = "Haven't you been listening? No, I very much doubt we would be having this conversation had Kel'Thuzad formed the staff. Kel'Thuzad holds the head. His underlings hold forty splinters of Atiesh. The last piece - the base - was uncovered by Brann Bronzebeard. He was last seen in the Silithus desert; undoubtedly doing his best to stay as far away as possible from the relentless seekers Kel'Thuzad has dispatched into the world." },
        ["text"] = "Ти взагалі слухав? Ні, дуже сумніваюся, що ми зараз розмовляли б, якби Кел'Тузад зібрав посох. У Кел'Тузада верхівка. Його прислужники мають сорок уламків Атієша. Останню частину — основу — знайшов Бранн Бронзобородий. Востаннє його бачили в пустелі Силітус; без сумніву, він намагається триматися якнайдалі від невтомних шукачів, яких Кел'Тузад розіслав по світу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [465715379] = {
        ["english"] = { [1] = "Hail, $c.  There is a great need and even greater honor and renown to be had in Alterac Valley at this time. Will you join our fight against the Stormpike Guard?" },
        ["text"] = "Вітаю, $c. Нині в Альтерацькій долині велика потреба в бійцях і ще більша нагода здобути честь та славу. Приєднаєшся до нашої боротьби проти варти Грозової Вершини?",
        ["npcs"] = { [1] = 15106 },
        ["roles"] = { ["greeting"] = true },
    },
    [427072578] = {
        ["english"] = { [1] = "Elder Ironband lives in Blackchar Cave in Searing Gorge." },
        ["text"] = "Старійшина Залізна Пов'язка живе в Чорновугільній печері у Випаленій ущелині.",
        ["npcs"] = { [1] = 15549, [2] = 15558, [3] = 15560, [4] = 15564, [5] = 15569, [6] = 15579, [7] = 15580, [8] = 15871 },
        ["roles"] = { ["greeting"] = true },
    },
    [159687791] = {
        ["english"] = { [1] = "Haven't got much time to talk, $r. That is, unless you're willin' to help with this mine trouble." },
        ["text"] = "Не маю багато часу на розмови, $r. Хіба що ти готовий допомогти з проблемами в копальні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3315500804] = {
        ["english"] = { [1] = "Hello there! Care to buy some fishing supplies, or perhaps take a lesson or two?" },
        ["text"] = "Привіт! Хочеш купити рибальські припаси або, може, взяти пару уроків?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [633689937] = {
        ["english"] = { [1] = "Dreams?" },
        ["text"] = "Сни?",
        ["npcs"] = { [1] = 9077 },
        ["roles"] = { ["reply"] = true },
    },
    [4065488704] = {
        ["english"] = { [1] = "Excellent! Let me know when you are ready for the next attempt." },
        ["text"] = "Чудово! Дай знати, коли будеш готовий до наступної спроби.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2816691165] = {
        ["english"] = { [1] = "Have you tried our bread? Baker Masterson must be the most gifted chef to have ever lived!" },
        ["text"] = "Пробував наш хліб? Пекар Мастерсон, мабуть, найобдарованіший кухар усіх часів!",
        ["npcs"] = { [1] = 11277 },
        ["roles"] = { ["greeting"] = true },
    },
    [2738648499] = {
        ["english"] = { [1] = "Hey, that reminds me, I need to have my rocket boots repaired.  Word to the wise my friend, rocket boots and gryphons don't mix.  \010\010Oh, but you need directions...  just head on over to the Dwarven District, you'll find Lilliam Sparkspindle towards the back." },
        ["text"] = "Гей, до речі, треба віддати в ремонт ракетні чоботи. Порада від знавця, друже: ракетні чоботи й грифони не поєднуються.\010\010А, тобі ж дорога потрібна... прямуй до Дворфівського району, Лілліам Іскрошпиндель буде ближче до дальнього краю.",
        ["npcs"] = { [1] = 68, [2] = 1976, [3] = 2808, [4] = 6272, [5] = 6740, [6] = 8931 },
        ["roles"] = { ["greeting"] = true },
    },
    [2099469916] = {
        ["english"] = { [1] = "Elder Graveborn spends time near Brill in Tirisfal Glades." },
        ["text"] = "Старійшина Народжений Могилою проводить час поблизу Брілля в Тірісфальському переліссі.",
        ["npcs"] = { [1] = 15561, [2] = 15564, [3] = 15566, [4] = 15594, [5] = 15602 },
        ["roles"] = { ["greeting"] = true },
    },
    [3400983041] = {
        ["english"] = { [1] = "Have you seen Watcher Backus? So brave...$B$BI think he's the toughest of all the Night Watch. I wonder if he even notices I'm around...." },
        ["text"] = "Бачив вартового Бакуса? Такий хоробрий...$B$BМені здається, він найсильніший у всій Нічній Варті. Цікаво, чи він узагалі помічає мене....",
        ["npcs"] = { [1] = 11040 },
        ["roles"] = { ["greeting"] = true },
    },
    [4208256543] = {
        ["english"] = { [1] = "Genius, I know... It will never be found; but, in case it is found, I gave the minnow some special powers." },
        ["text"] = "Геніально, знаю... Його ніколи не знайдуть. Але на випадок, якщо таки знайдуть, я наділив цю рибку особливими силами.",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["greeting"] = true },
    },
    [3860331175] = {
        ["english"] = { [1] = "Dun Baldar is the strongest point of Alliance power in Alterac Valley.  Nestled in the northern reaches of the valley, Dun Baldar is the staging ground for all advances to the south.$B$BDun Baldar is intact." },
        ["text"] = "Дун-Балдар — найміцніший осередок сили Альянсу в Альтерацькій долині. Розташований у північній частині долини, він є плацдармом для всіх наступів на південь.$B$BДун-Балдар неушкоджений.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2665396019] = {
        ["english"] = { [1] = "Greetings, traveler. It was here, nearly 1,000 years past, that the Qiraji began their march of destruction across Kalimdor.$B$BThousands of lives were lost during the war, most in this cursed desert during the initial invasion.$B$BI am one of only a few that remain, chained to both the past and the present. I know not why I am to remain stationed here but I know that I must." },
        ["text"] = "Вітаю, мандрівнику. Саме тут майже тисячу років тому кіражі почали свій нищівний похід Калімдором.$B$BУ війні загинули тисячі, більшість — у цій проклятій пустелі під час першого вторгнення.$B$BЯ один із небагатьох, хто лишився, прикутий і до минулого, і до сучасності. Не знаю, чому мушу залишатися на цій заставі, але знаю, що мушу.",
        ["npcs"] = { [1] = 15169 },
        ["roles"] = { ["greeting"] = true },
    },
    [1901002890] = {
        ["english"] = { [1] = "Hail to da new king!" },
        ["text"] = "Слава новому королю!",
        ["npcs"] = { [1] = 11441, [2] = 11444, [3] = 11445, [4] = 11448, [5] = 11450, [6] = 14325, [7] = 14351 },
        ["roles"] = { ["greeting"] = true },
    },
    [365631211] = {
        ["english"] = { [1] = "How can I summon Omen?" },
        ["text"] = "Як викликати Омена?",
        ["npcs"] = { [1] = 15864 },
        ["roles"] = { ["reply"] = true },
    },
    [1141120735] = {
        ["english"] = { [1] = "Have you honed your skills enough to learn what I have to teach?" },
        ["text"] = "Ти вже достатньо відточив навички, щоб навчитися того, що я можу показати?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3678796761] = {
        ["english"] = { [1] = "Eh? I don't have time ta chat, my da' wants me ta finish this order fer him." },
        ["text"] = "Га? Не маю часу балакати, тато хоче, щоб я закінчив це замовлення.",
        ["npcs"] = { [1] = 6299, [2] = 10277 },
        ["roles"] = { ["greeting"] = true },
    },
    [422903722] = {
        ["english"] = { [1] = "Have you heard the good news, $c? The Alliance has completed all of its war effort collections! Now we simply await the Horde to finish theirs. When they do, we'll begin shipping all of the war materiel over to Silithus, and it shouldn't be long after that until the Ahn'Qiraj War begins." },
        ["text"] = "Чув добрі новини, $c? Альянс завершив усі збори для війни! Тепер лишилося дочекатися, поки Орда завершить свої. Після цього ми почнемо перевозити військові припаси до Силітусу, і невдовзі почнеться війна в Ан'Кіражі.",
        ["npcs"] = { [1] = 15701 },
        ["roles"] = { ["greeting"] = true },
    },
    [1996842566] = {
        ["english"] = { [1] = "I am a crafter of some renown, $c. With the proper materials, I am able to craft an armor known as Dreamwalker. Druids - and even some shaman - are drawn to this armor due to its magical properties. Are you interested?" },
        ["text"] = "Я ремісник із певною славою, $c. Маючи потрібні матеріали, я можу створити обладунок, відомий як Мандрівник Снами. Друїди — і навіть деякі шамани — цінують його за магічні властивості. Цікавить?",
        ["npcs"] = { [1] = 16135 },
        ["roles"] = { ["greeting"] = true },
    },
    [2566689377] = {
        ["english"] = { [1] = "Have you come to hurt me?  I have nothing to do with the war, $r.$B$BI'm just a sickly scholar, please leave me alone!" },
        ["text"] = "Ти прийшов нашкодити мені? Я не маю нічого спільного з війною, $r.$B$BЯ лише хворобливий учений, залиш мене в спокої!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3681822799] = {
        ["english"] = { [1] = "Fleshling, I am Captain Saeed of the Protectorate and these soldiers that stand by me are my avengers. We await orders from the fleshling who destroyed the void conduit. On that fleshling's word, we will make our way up to Dimensius's lair and wait for the word to make a final strike!$B$BToo long it has been... The void lord will soon face our combined might!" },
        ["text"] = "Плотянику, я капітан Саїд із Протекторату, а ці солдати поруч — мої месники. Ми чекаємо наказу від плотяника, який знищив провідник Порожнечі. За його словом ми рушимо до лігва Діменсіуса й чекатимемо наказу на останній удар!$B$BНадто довго ми чекали... Володар Порожнечі скоро відчує нашу об'єднану міць!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [794514761] = {
        ["english"] = { [1] = "Greetings, traveler. I am Oronok. Please, sit by my fire and warm yourself.$B$BBeware the ravenous beasts of the shattered shelf below us!" },
        ["text"] = "Вітаю, мандрівнику. Я Оронок. Сідай біля мого вогню й зігрійся.$B$BСтережися ненажерливих звірів на розколотому уступі внизу!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [475820595] = {
        ["english"] = { [1] = "Does being in the presence of a Black Dragon make you nervous?$B$BGood. It should. It makes these dragons nervous too. They cling to their ancient virtues though - they wouldn't dare attack me here.$B$BFools." },
        ["text"] = "Нервуєте поруч із чорним драконом?$B$BІ правильно. Так і має бути. Ці дракони теж нервують. Та вони чіпляються за свої давні чесноти — тут вони не наважаться напасти на мене.$B$BДурні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3700255216] = {
        ["english"] = { [1] = "Hello, $c. From what I've been told, everything's been collected, and all of the materiel for the war is being shipped over to Silithus as we speak. It should all be there in less than $2113w days. Once that's done, and the gong has been rung with the Scepter of the Shifting Sands, the war will really begin." },
        ["text"] = "Привіт, $c. Наскільки я знаю, все вже зібрано, а військові припаси зараз перевозять до Силітусу. Усе має прибути менш ніж за $2113w днів. Після цього, коли в гонг ударять Скіпетром Мінливих Пісків, війна почнеться по-справжньому.",
        ["npcs"] = { [1] = 15432 },
        ["roles"] = { ["greeting"] = true },
    },
    [3872156045] = {
        ["english"] = { [1] = "Have you come here for instruction in the art of making potions? You were mistaken if you thought that I would offer such a privilege to you, unearned. Go, and do not return to me until you have greater skill." },
        ["text"] = "Прийшов навчитися варити зілля? Якщо думав, що я дам тобі такий привілей просто так, то помилився. Іди й не повертайся, доки не станеш вправнішим.",
        ["npcs"] = { [1] = 7948 },
        ["roles"] = { ["greeting"] = true },
    },
    [2351942862] = {
        ["english"] = { [1] = "Have you any idea what I go through to bring these incomparable valuables to sell?  Come see them all for yourself!" },
        ["text"] = "Ти хоч уявляєш, через що я проходжу, щоб привезти ці неперевершені коштовності на продаж? Поглянь сам!",
        ["npcs"] = { [1] = 14846 },
        ["roles"] = { ["greeting"] = true },
    },
    [3323639941] = {
        ["english"] = { [1] = "Have a look at my meats, friend.  You won't want to go out into the Barrens without a good stock of provisions." },
        ["text"] = "Поглянь на моє м'ясо, друже. Не варто вирушати в Степи без доброго запасу харчів.",
        ["npcs"] = { [1] = 3489 },
        ["roles"] = { ["greeting"] = true },
    },
    [3927413393] = {
        ["english"] = { [1] = "Hello, $N. If you're looking for cooking training, you've come to the right place. I usually get lots of new students when Pilgrim's Bounty rolls around." },
        ["text"] = "Привіт, $N. Якщо шукаєш навчання кулінарії, ти прийшов куди треба. Під час Щедрості Пілігрима в мене зазвичай повно нових учнів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1103595054] = {
        ["english"] = { [1] = "Happy Hallow's End, $c!" },
        ["text"] = "Щасливого Тиквовину, $c!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2765346775] = {
        ["english"] = { [1] = "Elder Snowcrown can be found in Light's Hope Chapel in the Eastern Plaguelands." },
        ["text"] = "Старійшину Снігова Корона можна знайти в каплиці Надії Світла у Східному Чумнозем'ї.",
        ["npcs"] = { [1] = 15568, [2] = 15592, [3] = 15594, [4] = 15602, [5] = 15607 },
        ["roles"] = { ["greeting"] = true },
    },
    [4233517502] = {
        ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Thunder Bluff.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Thunder Bluff for your duty and service.\010", [2] = "Greetings, $c - I'm a Commendation Officer acting on behalf of Thunder Bluff.  It is my duty to assist adventurers who have received Horde Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from Thunder Bluff for your duty and service.\010\010" },
        ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Громовий Бескид. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Орди.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Громового Бескиду.\010",
        ["npcs"] = { [1] = 15739, [2] = 15767 },
        ["roles"] = { ["greeting"] = true },
    },
    [448404204] = {
        ["english"] = { [1] = "How do you know?" },
        ["text"] = "Звідки ви знаєте?",
        ["npcs"] = { [1] = 15169 },
        ["roles"] = { ["reply"] = true },
    },
    [848804359] = {
        ["english"] = { [1] = "Hello, $c. I am Jessir Moonbow. I have come from Darnassus seeking two friends who came looking for signs of the Shadow Council in Felwood.$B$BIt seems those vile creatures who claim responsibility for much of the orcish race's suffering seeks to regain some of its power.$B$BMy two friends went looking in Jaedenar to prove one way or the other what was happening.$B$BI expected them to be here when I arrived, but now they are days late." },
        ["text"] = "Привіт, $c. Я Джессір Місячний Лук. Прибув із Дарнаса в пошуках двох друзів, які вирушили до Сквернолісся шукати ознаки Ради Тіней.$B$BСхоже, ці мерзотники, винні в багатьох стражданнях орків, прагнуть відновити частину своєї сили.$B$BМої друзі пішли до Джеденара, щоб з'ясувати, що там відбувається.$B$BЯ сподівався зустріти їх тут, але вони запізнюються вже на кілька днів.",
        ["npcs"] = { [1] = 11019 },
        ["roles"] = { ["greeting"] = true },
    },
    [2712298091] = {
        ["english"] = { [1] = "Ey, mon!$b$bGood to be seein' ya again... $N, right? Yes, yes, of course.$b$bYou and I gunna be real good friends. Drakuru know dese things.$b$b<A grin slowly spreads across the troll's painted face.>" },
        ["text"] = "Йо, мон!$b$bРадий знову тебе бачити... $N, так? Так-так, звісно.$b$bМи з тобою станемо дуже добрими друзями. Дракуру знає такі речі.$b$b<На розмальованому обличчі троля повільно розповзається усмішка.>",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [391508016] = {
        ["english"] = { [1] = "I am dishonored. I should have died with the farseer at Magmoth.$B$BLeave me to my thoughts." },
        ["text"] = "Я зганьблений. Мав загинути разом із провидцем у Маґмоті.$B$BЗалиш мене наодинці з думками.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [899709575] = {
        ["english"] = { [1] = "Flowers?  In this wasteland?  If anyone can teach you how to find them it will be Mishiki down in Sen'jin Village to the south." },
        ["text"] = "Квіти? У цій пустці? Якщо хтось і навчить тебе їх знаходити, то це Мішікі в селищі Сен'джин на півдні.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [3465464453] = {
        ["english"] = { [1] = "Do you wish to learn the blacksmithing profession or is there something else you wish to tell me?" },
        ["text"] = "Бажаєте опанувати ковальство чи хотіли сказати мені щось інше?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1338508326] = {
        ["english"] = { [1] = "Don't bother me with trifles!" },
        ["text"] = "Не турбуйте мене дрібницями!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [148276194] = {
        ["english"] = { [1] = "Hail, $r! I am Lieutenant Haggerdin, officer in charge of recruitment for the Stormpike Guard.$B$BAs you gain prestige and notoriety among the Stormpike, return to me and I shall see about upgrading your insignia. Also, should you ever lose your insignia, I am able to supply a replacement." },
        ["text"] = "Вітаю, $r! Я лейтенант Гаґґердін, офіцер з набору до варти Грозової Вершини.$B$BКоли твоя слава серед Грозової Вершини зростатиме, повертайся до мене — я подбаю про покращення твоєї відзнаки. А якщо загубиш її, я зможу видати заміну.",
        ["npcs"] = { [1] = 13841 },
        ["roles"] = { ["greeting"] = true },
    },
    [685668602] = {
        ["english"] = { [1] = "Glory will be ours when we win this tournament in the name of Silvermoon." },
        ["text"] = "Слава буде нашою, коли ми виграємо цей турнір в ім'я Срібномісяця.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3184009366] = {
        ["english"] = { [1] = "Hail, $N!  It is good you came to see me.  We are prepared to launch a ground assuault through the Field of Strife!  Once Warmaster Garrick gets his orders, he and his reavers will cut a swath through the Alliance!$B$BDo you want to deliver those orders, $N?  Garrick is waiting in the Field of Strife..." },
        ["text"] = "Вітаю, $N! Добре, що прийшов. Ми готові розпочати наземний наступ через Поле Чвар! Щойно воєначальник Ґаррік отримає накази, він зі своїми рубаками проріже шлях крізь Альянс!$B$BХочеш доставити ці накази, $N? Ґаррік чекає на Полі Чвар...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1445708949] = {
        ["english"] = { [1] = "Hail, $c.  The Ironforge Brigade is stationed here to keep an eye on Hive'Zora.  The Cenarion Circle druids have been monitoring silithid movement and they're anticipating something major in this area." },
        ["text"] = "Вітаю, $c. Залізогартська бригада стоїть тут, щоб стежити за вуликом Зора. Друїди Кенарієвого Кола спостерігають за пересуваннями силітидів і очікують тут чогось великого.",
        ["npcs"] = { [1] = 15443 },
        ["roles"] = { ["greeting"] = true },
    },
    [197369510] = {
        ["english"] = { [1] = "Hail, $C. In my years I have seen many eager tauten who wish to prove their worth to the tribe. It should not be forgotten thet eagerness is no substitute for wisdom and experience." },
        ["text"] = "Вітаю, $C. За свої роки я бачив багатьох запальних тауренів, які прагнули довести свою цінність племені. Не забувай: запал не замінить мудрості й досвіду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [641734928] = {
        ["english"] = { [1] = "Hail, $c. I trust you are here to inquire on the Ahn'Qiraj war effort. We are going to need a great deal of assistance.$B$BThe war effort is a united effort between the Horde and Alliance to prepare for the impending war against the Silithid and their masters in Ahn'Qiraj. In Orgrimmar's Valley of Spirits, we are collecting a vast number of goods to create war materiel, and these gathering tasks are what we need your help with.$B$BCan I convince you to speak with our commander about helping out?" },
        ["text"] = "Вітаю, $c. Гадаю, ти прийшов дізнатися про підготовку до війни в Ан'Кіражі. Нам знадобиться величезна допомога.$B$BЦя підготовка — спільна справа Орди й Альянсу перед війною проти силітидів та їхніх володарів в Ан'Кіражі. У Долині Духів Орґріммара ми збираємо величезні запаси товарів для військових припасів, і саме з цим нам потрібна твоя допомога.$B$BМоже, поговориш із нашим командиром про участь?",
        ["npcs"] = { [1] = 15702, [2] = 15703, [3] = 15704 },
        ["roles"] = { ["greeting"] = true },
    },
    [4252682293] = {
        ["english"] = { [1] = "Hail, $c. As you may know, we've completed all collections necessary for the Alliance's role in the upcoming war. Now it's up to the Horde to finish with theirs and we'll ship out to Silithus." },
        ["text"] = "Вітаю, $c. Як ти, мабуть, знаєш, Альянс завершив усі збори, потрібні для своєї участі в майбутній війні. Тепер черга Орди завершити свої, і тоді ми відправимо все до Силітусу.",
        ["npcs"] = { [1] = 15445 },
        ["roles"] = { ["greeting"] = true },
    },
    [829972988] = {
        ["english"] = { [1] = "I am an orc of medicine, $r. If you have come here to learn, I shall do my best to teach." },
        ["text"] = "Я орк-лікар, $r. Якщо прийшов учитися, я зроблю все можливе, щоб навчити.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3291557532] = {
        ["english"] = { [1] = "Greetings, $glad:lass;. I'm Grelin Whitebeard. I'm here to examine the threat posed by the growing numbers of trolls in Coldridge Valley. What have I found? It's a bit troubling..." },
        ["text"] = "Вітаю, $gхлопче:дівчино;. Я Ґрелін Білобородий. Я тут, щоб дослідити загрозу від зростання кількості тролів у Морозній долині. Що я виявив? Дещо тривожне...",
        ["npcs"] = { [1] = 786 },
        ["roles"] = { ["greeting"] = true },
    },
    [2900506576] = {
        ["english"] = { [1] = "Greetings my friend, and welcome to the greatest show in Outland!$B$BPlease, step right up and take in all we have to offer.  Amaze at the wonders that the Darkmoon Faire has uncovered in this vast and mysterious world!  We have spared no expense in bringing you excitement that children of all ages will delight in!" },
        ["text"] = "Вітаю, друже, і ласкаво просимо на найбільше видовище Позамежжя!$B$BПідходьте ближче й погляньте на все, що ми пропонуємо. Дивуйтеся чудесам, які ярмарок Темного Місяця відкрив у цьому величезному й загадковому світі! Ми не шкодували коштів, щоб принести вам розваги, від яких будуть у захваті діти будь-якого віку!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [161733023] = {
        ["english"] = { [1] = "Don't forget to stock up on wrapping paper this holiday season!  Nothing says \"Wondrous Winter Veil\" like wrapped armors and weapons for your friends and family." },
        ["text"] = "Не забудьте запастися обгортковим папером до свят! Ніщо так не каже «Дивовижний Зимовий Покров», як загорнуті обладунки та зброя для друзів і родини.",
        ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 },
        ["roles"] = { ["greeting"] = true },
    },
    [476095809] = {
        ["english"] = { [1] = "Good day to you." },
        ["text"] = "Добридень.",
        ["npcs"] = { [1] = 5567 },
        ["roles"] = { ["greeting"] = true },
    },
    [4182418142] = {
        ["english"] = { [1] = "Hail to thee, $c." },
        ["text"] = "Вітаю тебе, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1920782549] = {
        ["english"] = { [1] = "Huh?  What?  I'm a little busy here, friend!$B$BOf course, if you're here to help, I've got all the time in the world." },
        ["text"] = "Га? Що? Я тут трохи зайнятий, друже!$B$BЗвісно, якщо прийшов допомогти, у мене для тебе скільки завгодно часу.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2895370098] = {
        ["english"] = { [1] = "Have you seen the damaged sentries that wander the island?  A few modifications to the crystals that control their behavior will allow us to gain control of them and use them to secure tactical locations.$B$BThe Sun's Reach Sanctum will be ours in no time.  We are $3244w percent done with this goal." },
        ["text"] = "Бачив пошкоджених вартових, що блукають островом? Кілька змін у кристалах, які визначають їхню поведінку, дозволять нам підкорити їх і використати для захоплення стратегічних позицій.$B$BСвятилище Сонячного Краю скоро буде нашим. Ми виконали $3244w відсотків цієї мети.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3301759918] = {
        ["english"] = { [1] = "Hi there! We're being blockaded by those good-for-nothing pirates out in the bay! Do you think you can help us out by dropping a few bombs on them?!$B$BOur stolen zeppelin's almost here... I think I hear her now.  Make sure you're onboard when she leaves!" },
        ["text"] = "Привіт! Ті нікчемні пірати в затоці взяли нас у блокаду! Допоможеш скинути на них кілька бомб?!$B$BНаш украдений дирижабль уже майже тут... здається, я його чую. Не проґав відправлення!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1317837403] = {
        ["english"] = { [1] = "Hail $c. Didn't I see you recently at an exclusive gathering? You look familiar, but then again this city is a busy place.$B$BIf you attended that convention, then surely you were given a secret code. Tell me your code and I will give you a special prize in return." },
        ["text"] = "Вітаю, $c. Чи не бачив я тебе нещодавно на одному закритому зібранні? Обличчя знайоме, хоча це місто дуже людне.$B$BЯкщо ти був на тій зустрічі, тобі мали дати таємний код. Назви його — і я дам особливу нагороду.",
        ["npcs"] = { [1] = 2943, [2] = 7951, [3] = 16070, [4] = 16076 },
        ["roles"] = { ["greeting"] = true },
    },
    [499441698] = {
        ["english"] = { [1] = "I already know a lot about style. Now it's just a matter of mastering the techniques for working with leather. Good thing Simon's a real sport about helping me learn them." },
        ["text"] = "Я вже багато знаю про стиль. Тепер залишилося лише опанувати техніки роботи зі шкірою. Добре, що Саймон такий добряк і допомагає мені їх вивчати.",
        ["npcs"] = { [1] = 11096 },
        ["roles"] = { ["greeting"] = true },
    },
    [1724082900] = {
        ["english"] = { [1] = "Haha, you be pullin' me leg mon. Pele'keiki know that you know we Horde already be havin' all the war stuff we be needin'. Now we just waitin' on that Alliance to get all theirs and we startin' up the war." },
        ["text"] = "Ха-ха, ти мене розігруєш, мон. Пеле'кейкі знає, що ти знаєш: ми, Орда, вже маємо всі військові припаси, що потрібні. Тепер просто чекаємо, поки Альянс збере свої, і почнемо війну.",
        ["npcs"] = { [1] = 15508 },
        ["roles"] = { ["greeting"] = true },
    },
    [3364239647] = {
        ["english"] = { [1] = "Head north up the road to Orgrimmar.  You can ask one of the grunts there for directions to the Cooking Trainer." },
        ["text"] = "Іди дорогою на північ до Орґріммара. Там спитай у когось із рубак дорогу до наставника кулінарії.",
        ["npcs"] = { [1] = 5953 },
        ["roles"] = { ["greeting"] = true },
    },
    [1314277569] = {
        ["english"] = { [1] = "Go back to work before the overseer sees us." },
        ["text"] = "Повертайся до роботи, поки наглядач нас не побачив.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1412418749] = {
        ["english"] = { [1] = "Gurf is my name, stranger. Gurf the Brave!" },
        ["text"] = "Мене звати Ґурф, чужинцю. Ґурф Хоробрий!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2646939671] = {
        ["english"] = { [1] = "Hello, little $r." },
        ["text"] = "Привіт, маленький $r.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3867873792] = {
        ["english"] = { [1] = "Gubber, I don't know how to fish.", [2] = "Gubber, I don't know how to fish.\010" },
        ["text"] = "Ґаббере, я не вмію рибалити.",
        ["npcs"] = { [1] = 10216 },
        ["roles"] = { ["reply"] = true },
    },
    [3671134537] = {
        ["english"] = { [1] = "Even in this remote corner of the world, know that Hellscream's eyes are upon you." },
        ["text"] = "Навіть у цьому віддаленому куточку світу пам'ятай: очі Пеклокрика стежать за тобою.",
        ["npcs"] = { [1] = 2465 },
        ["roles"] = { ["greeting"] = true },
    },
    [3905193869] = {
        ["english"] = { [1] = "How do you do, $c?" },
        ["text"] = "Як поживаєте, $c?",
        ["npcs"] = { [1] = 6782 },
        ["roles"] = { ["greeting"] = true },
    },
    [199682921] = {
        ["english"] = { [1] = "Gryphon Master" },
        ["text"] = "Майстер грифонів",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1976, [5] = 2808, [6] = 5595, [7] = 6272, [8] = 6740, [9] = 8931, [10] = 12996, [11] = 13076, [12] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [1359320266] = {
        ["english"] = { [1] = "Hello, peach - good to have your company!" },
        ["text"] = "Привіт, красунчику — радий твоєму товариству!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [514744766] = {
        ["english"] = { [1] = "Fine work! You are truly deserving of the knowledge I shall bestow upon you!" },
        ["text"] = "Чудова робота! Ти справді гідний знань, якими я з тобою поділюся!",
        ["npcs"] = { [1] = 4213 },
        ["roles"] = { ["greeting"] = true },
    },
    [2696865018] = {
        ["english"] = { [1] = "Grrr, what do you want, $r? Oh, you must be here about the lean wolf steaks for the impending Ahn'Qiraj War. Yes, you heard right, I'm collecting them, what about it? Do you have a fresh stack for me? I only need $2096w, and it looks like we have $2095w right now." },
        ["text"] = "Гррр, чого тобі, $r? А, мабуть, через пісні вовчі стейки для майбутньої війни в Ан'Кіражі. Так, усе правильно, я їх збираю, і що? Приніс свіжу пачку? Треба всього $2096w, а зараз, схоже, маємо $2095w.",
        ["npcs"] = { [1] = 15533 },
        ["roles"] = { ["greeting"] = true },
    },
    [1505690086] = {
        ["english"] = { [1] = "Even I have my limitations! Go talk to Lavinia Crowe in Undercity if you wish to further your training." },
        ["text"] = "Навіть мої можливості не безмежні! Якщо хочеш учитися далі, поговори з Лавінією Кроу в Підмісті.",
        ["npcs"] = { [1] = 5695 },
        ["roles"] = { ["greeting"] = true },
    },
    [2248776243] = {
        ["english"] = { [1] = "Glad you asked. Darkmoon Faire Prize Tickets are our way of letting you help with the faire, and in return you can turn in your tickets for special prizes!\010\010To get started you'll want to talk to Chronos, Kerri Hicks, Ringling and Yebb Nebblegear to see who you can best help. They always have something that needs doing to improve and expand our attractions.\010\010Then when you have enough tickets, speak with Gelvas Grimegate and he will give you a list of prizes to choose from.\010" },
        ["text"] = "Радий, що питаєте. Призові квитки ярмарку Темного Місяця — це наш спосіб дозволити вам допомагати ярмарку, а натомість обмінювати квитки на особливі нагороди!\010\010Для початку поговоріть із Хроносом, Керрі Гікс, Рінґлінґом і Єббом Небблґіром та дізнайтеся, кому з них ви найкраще зможете допомогти. У них завжди знайдеться робота для покращення й розширення наших атракціонів.\010\010Коли назбираєте достатньо квитків, поговоріть із Ґелвасом Бруднобрамом, і він дасть вам список нагород на вибір.\010",
        ["npcs"] = { [1] = 10445 },
        ["roles"] = { ["greeting"] = true },
    },
    [209506122] = {
        ["english"] = { [1] = "Greetings, and welcome.  I am not very good at smiling, but trust me; I am happy to serve you." },
        ["text"] = "Вітаю й ласкаво просимо. Я не дуже вмію усміхатися, але повірте: я радий вам служити.",
        ["npcs"] = { [1] = 4556 },
        ["roles"] = { ["greeting"] = true },
    },
    [3574571348] = {
        ["english"] = { [1] = "Gremlock doesn't always have the best of luck with cooking, but he does have some tasty recipies worth learning.  Go chat him up in the Thunderbrew Distillery and see what he'll teach ye." },
        ["text"] = "Ґремлоку не завжди щастить із куховарством, але в нього є кілька смачних рецептів, які варто вивчити. Завітай до нього у винокурню Громовара й дізнайся, чого він тебе навчить.",
        ["npcs"] = { [1] = 727, [2] = 12996, [3] = 13076 },
        ["roles"] = { ["greeting"] = true },
    },
    [2280657058] = {
        ["english"] = { [1] = "Grekk holds them.$b$bMaybe he'll give you one if you help him out. The next time you're up north at Blue Sky logging Grounds be sure to talk to him." },
        ["text"] = "Вони в Ґрекка.$b$bМоже, він дасть тобі одну, якщо допоможеш йому. Наступного разу, коли будеш на півночі біля лісозаготівель Блакитного Неба, обов'язково поговори з ним.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1897927251] = {
        ["english"] = { [1] = "Greetings.  You are here to help?" },
        ["text"] = "Вітаю. Ви прийшли допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2178118592] = {
        ["english"] = { [1] = "Greetings.  Our bats are well trained and fed.  You'll not find faster." },
        ["text"] = "Вітаю. Наші кажани добре навчені й нагодовані. Швидших не знайдете.",
        ["npcs"] = { [1] = 2226 },
        ["roles"] = { ["greeting"] = true },
    },
    [1091905975] = {
        ["english"] = { [1] = "Greetings, young $c. In preparation for the war at Ahn'Qiraj against the Silithid, the Alliance has asked me to head up their collection of purple lotus. This flower has many uses that I am aware of, and thus, I have agreed to help them attain $2055w. To date we have collected $2053w." },
        ["text"] = "Вітаю, юний $c. Готуючись до війни в Ан'Кіражі проти силітидів, Альянс доручив мені очолити збір пурпурового лотоса. Я знаю чимало способів використання цієї квітки, тож погодився допомогти їм зібрати $2055w. Наразі ми зібрали $2053w.",
        ["npcs"] = { [1] = 15437 },
        ["roles"] = { ["greeting"] = true },
    },
    [3328464446] = {
        ["english"] = { [1] = "Get that head and it's sure to give Daryl a fright. Not that he doesn't deserve it, the bloody arrogant bastard. But ha! I can't wait to see the look on his face when you show it to him." },
        ["text"] = "Здобудь ту голову — і Деріл точно перелякається. Не те щоб він цього не заслужив, кривавий пихатий виродок. Ха! Не можу дочекатися його пики, коли ти йому це покажеш.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2291476855] = {
        ["english"] = { [1] = "Have you seen the Headless Horseman?  If he comes here then I'll fight him and steal his pumpkin!" },
        ["text"] = "Бачив Вершника без Голови? Якщо він прийде сюди, я з ним битимусь і вкраду його гарбуз!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4162693214] = {
        ["english"] = { [1] = "Don't mind me. I'm just an old man, waiting on an old... friend." },
        ["text"] = "Не зважай на мене. Я лише старий, що чекає на старого... друга.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3158015027] = {
        ["english"] = { [1] = "Enchanting" },
        ["text"] = "Зачарування",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3084, [18] = 3212, [19] = 3215, [20] = 3217, [21] = 3218, [22] = 3219, [23] = 3220, [24] = 3221, [25] = 3222, [26] = 3223, [27] = 3224, [28] = 3296, [29] = 3571, [30] = 4262, [31] = 5595, [32] = 5624, [33] = 5725, [34] = 5953, [35] = 6272, [36] = 6740, [37] = 8931, [38] = 12996, [39] = 13076, [40] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [3050144015] = {
        ["english"] = { [1] = "Greetings, my $g lord : lady;. I trust that you are having a pleasant time?" },
        ["text"] = "Вітаю, мій $g володарю : володарко;. Сподіваюся, ви добре проводите час?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3642562166] = {
        ["english"] = { [1] = "Don't forget to buy refreshments and souvenirs!" },
        ["text"] = "Не забудьте купити частування й сувеніри!",
        ["npcs"] = { [1] = 14849 },
        ["roles"] = { ["greeting"] = true },
    },
    [1225137465] = {
        ["english"] = { [1] = "Even here in the wilds, you seek out learning. Your drive for knowledge is an admirable trait." },
        ["text"] = "Навіть тут, у дикій глушині, ти шукаєш знань. Твоє прагнення вчитися гідне поваги.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3186521538] = {
        ["english"] = { [1] = "Greetings, hero. I craft and sell Ymirjar Lord's armor for warriors." },
        ["text"] = "Вітаю, герою. Я виготовляю й продаю воїнам обладунки Володаря Імір'яра.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2626719329] = {
        ["english"] = { [1] = "Greetings, $r. I am Franclorn Forgewright. Are you here to learn of the Spire and of Dark Iron?" },
        ["text"] = "Вітаю, $r. Я Франклорн Горнмастак. Прийшов дізнатися про Шпиль і Темне Залізо?",
        ["npcs"] = { [1] = 8888 },
        ["roles"] = { ["greeting"] = true },
    },
    [2973370834] = {
        ["english"] = { [1] = "Greetings, hero. I craft and sell Dark Coven armor for warlocks.$B" },
        ["text"] = "Вітаю, герою. Я виготовляю й продаю чорнокнижникам обладунки Темного Ковену.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4234333684] = {
        ["english"] = { [1] = "Greetings, hero. I craft and sell Bloodmage armor for magi.$B" },
        ["text"] = "Вітаю, герою. Я виготовляю й продаю магам обладунки Мага Крові.$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [947988230] = {
        ["english"] = { [1] = "Elder Hammershout can be found within the walls of Stormwind." },
        ["text"] = "Старійшину Молотокрика можна знайти в мурах Штормовію.",
        ["npcs"] = { [1] = 15557, [2] = 15565, [3] = 15598, [4] = 15871 },
        ["roles"] = { ["greeting"] = true },
    },
    [1107456666] = {
        ["english"] = { [1] = "Don't forget to take some time out to fish while you're in Zangarmarsh. You never know when you'll see water again." },
        ["text"] = "Не забудьте порибалити, поки ви в Занґарському болоті. Хтозна, коли знову побачите воду.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3965574102] = {
        ["english"] = { [1] = "Greetings, $r $c. I am Commander Stronghammer, the ambassador representing the Alliance here. If you have any questions concerning the status of Alliance collections for the Ahn'Qiraj war effort, $g lad : lass;, don't hesitate to ask." },
        ["text"] = "Вітаю, $r $c. Я командир Міцномолот, посол Альянсу. Якщо маєш запитання щодо стану зборів Альянсу для війни в Ан'Кіражі, $g хлопче : дівчино;, не соромся питати.",
        ["npcs"] = { [1] = 15458 },
        ["roles"] = { ["greeting"] = true },
    },
    [4012442147] = {
        ["english"] = { [1] = "He's gone?  Hooray!" },
        ["text"] = "Він пішов? Ура!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [829987356] = {
        ["english"] = { [1] = "Hey dere. You need anythin', you let me know." },
        ["text"] = "Гей. Якщо щось треба — кажи.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [366164575] = {
        ["english"] = { [1] = "Greetings, citizen. I ask that you move along if you have nothing to ask of me." },
        ["text"] = "Вітаю, громадянине. Якщо вам нема чого в мене спитати, прошу не затримуватися.",
        ["npcs"] = { [1] = 17804 },
        ["roles"] = { ["greeting"] = true },
    },
    [2243157512] = {
        ["english"] = { [1] = "Huh?" },
        ["text"] = "Га?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2349968943] = {
        ["english"] = { [1] = "Glacial Vest." },
        ["text"] = "Льодовиковий жилет.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [4092990312] = {
        ["english"] = { [1] = "Greetings, $r.$B$BIf you are interested in helping with the defense of the temple, please speak with Lord Afrasastrasz inside." },
        ["text"] = "Вітаю, $r.$B$BЯкщо хочеш допомогти з обороною храму, поговори з лордом Афрасастразом усередині.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2126337985] = {
        ["english"] = { [1] = "Greetings, $r.$b$bI'm afraid you must excuse me as I'm terribly busy at the moment." },
        ["text"] = "Вітаю, $r.$b$bБоюся, доведеться мене вибачити — зараз я страшенно зайнятий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1146920946] = {
        ["english"] = { [1] = "Excellent! You meet the required parameters and specifications. What can I do for you?" },
        ["text"] = "Чудово! Ви відповідаєте необхідним параметрам і специфікаціям. Чим можу допомогти?",
        ["npcs"] = { [1] = 5114 },
        ["roles"] = { ["greeting"] = true },
    },
    [1759434110] = {
        ["english"] = { [1] = "Greetings, $r. Wonderful day to be alive, is it not?" },
        ["text"] = "Вітаю, $r. Чудовий день, щоб жити, хіба ні?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2240178542] = {
        ["english"] = { [1] = "Gather your senses quickly, we must press on." },
        ["text"] = "Швидко опануй себе, нам треба рушати далі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3865666925] = {
        ["english"] = { [1] = "Greetings, $r. The war materiel is gradually being sent on its way and should be at Cenarion Hold within $2113w day's time. We can only hope that once it is there that someone, having assembled the Scepter of the Shifting Sands, will step forward to ring the gong and open the gates." },
        ["text"] = "Вітаю, $r. Військові припаси поступово відправляють, і вони мають прибути до Кенарійської цитаделі за $2113w днів. Залишається сподіватися, що коли все буде на місці, хтось, зібравши Скіпетр Мінливих Пісків, вийде вперед, ударить у гонг і відчинить брами.",
        ["npcs"] = { [1] = 15457 },
        ["roles"] = { ["greeting"] = true },
    },
    [3248213077] = {
        ["english"] = { [1] = "Greetings, hero. I craft and sell Freya's Lasherweave armor for druids." },
        ["text"] = "Вітаю, герою. Я виготовляю й продаю друїдам обладунки Фрейїного лозоплетіння.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [441772166] = {
        ["english"] = { [1] = "Don't waste my time." },
        ["text"] = "Не марнуй мого часу.",
        ["npcs"] = { [1] = 987, [2] = 1404 },
        ["roles"] = { ["greeting"] = true },
    },
    [1562828763] = {
        ["english"] = { [1] = "Fimble Finespindle has a shop set up on the northwest side of The Great Forge.  I wager he could show ye how to make some fine armor." },
        ["text"] = "Фімбл Файнспіндел відкрив крамницю на північно-західному боці Великої Кузні. Б'юсь об заклад, він покаже тобі, як робити добрі обладунки.",
        ["npcs"] = { [1] = 5595, [2] = 274781 },
        ["roles"] = { ["greeting"] = true },
    },
    [858238537] = {
        ["english"] = { [1] = "Greetings, friend." },
        ["text"] = "Вітаю, друже.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1916615924] = {
        ["english"] = { [1] = "During the Day of the Dead, people gather in graveyards to celebrate with and cherish the spirits of those they have lost.$B$BYou can find the festivities in the cemeteries of any major city, where you'll be able to cook, dance, don costumes, and more." },
        ["text"] = "У День мертвих люди збираються на кладовищах, щоб святкувати разом із духами тих, кого втратили, і вшанувати їх.$B$BСвяткування відбуваються на цвинтарях усіх великих міст: там можна готувати, танцювати, вдягати костюми та багато іншого.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2092167577] = {
        ["english"] = { [1] = "Greetings, $n. You were not followed here, I trust?" },
        ["text"] = "Вітаю, $n. За тобою ніхто не стежив, сподіваюся?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2491430419] = {
        ["english"] = { [1] = "Gorth not afraid of getting killed.  Them Forsaken just put me back together again." },
        ["text"] = "Ґорт не боятися, що його вбити. Відречені просто зібрати мене докупи знову.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3056472558] = {
        ["english"] = { [1] = "Greetings, $N. This is the workshop of Keeper Mimir." },
        ["text"] = "Вітаю, $N. Це майстерня хранителя Міміра.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1393985688] = {
        ["english"] = { [1] = "Even as we speak, $c, all of the war materiel is being transported over to Silithus. By the looks of things, the last of it should arrive in less than a day. After that, a $g hero : heroine; will need to come along and ring the gong at the Scarab Dais. Then the war will begin in earnest." },
        ["text"] = "Поки ми говоримо, $c, усе військове спорядження перевозять до Силітусу. Схоже, остання партія прибуде менш ніж за день. Після цього має прийти $g герой : героїня; і вдарити в гонг біля Помосту Скарабея. Тоді війна почнеться по-справжньому.",
        ["npcs"] = { [1] = 15451 },
        ["roles"] = { ["greeting"] = true },
    },
    [4273174177] = {
        ["english"] = { [1] = "Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!" },
        ["text"] = "Просто з нашої ферми на вашу тарілку — корисна смакота «Пасовищ Димного Лісу»!",
        ["npcs"] = { [1] = 13418, [2] = 13420, [3] = 13430, [4] = 13432, [5] = 13433, [6] = 13434, [7] = 13435, [8] = 13436 },
        ["roles"] = { ["greeting"] = true },
    },
    [286399958] = {
        ["english"] = { [1] = "Dragonhawks, if raised properly, are really quite tame.  Don't you think that is fascinating?  To be so friendly and companionable if raised right and so vicious and deadly in the wild...I just love them so much." },
        ["text"] = "Дракояструби, якщо їх правильно вирощувати, на диво слухняні. Хіба це не захопливо? Виховані як слід — приязні й товариські, а в дикій природі — люті й смертоносні... Я їх просто обожнюю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2206024611] = {
        ["english"] = { [1] = "Greetings, $N. I see that you are already flagged as having completed the quest to gain entry to Naxxramas. Be sure to speak with Commander Eligor Dawnbringer at Light's Hope Chapel in the Eastern Plaguelands to acquire the quest, \"Echoes of War.\" You must first complete that quest to be able to access the quests for your Tier 3 armor set.$B$BI am able to teleport you directly to Naxxramas or you may use the portal found in Plaguewood, to the west." },
        ["text"] = "Вітаю, $N. Бачу, ти вже позначений як той, хто виконав завдання для доступу до Наксрамаса. Обов'язково поговори з командиром Еліґором Світанконосцем у каплиці Надії Світла в Східному Чумнозем'ї та візьми завдання «Відлуння війни». Спершу треба виконати його, щоб отримати доступ до завдань на комплект обладунків 3-го рівня.$B$BЯ можу телепортувати тебе прямо до Наксрамаса, або можеш скористатися порталом у Чумоліссі на заході.",
        ["npcs"] = { [1] = 16999 },
        ["roles"] = { ["greeting"] = true },
    },
    [2505425065] = {
        ["english"] = { [1] = "How do I form an arena team?" },
        ["text"] = "Як створити команду арени?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [494649086] = {
        ["english"] = { [1] = "Go and rest, wanderer. Our fires are yours." },
        ["text"] = "Іди відпочинь, мандрівнику. Наші вогнища — твої.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1110669188] = {
        ["english"] = { [1] = "Greetings, $c.$b$bYou want Darrok to send you to Venture Bay?" },
        ["text"] = "Вітаю, $c.$b$bХочеш, щоб Даррок відправив тебе до Бухти Підприємців?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2737647091] = {
        ["english"] = { [1] = "I am ready to hear your tale, Tirion." },
        ["text"] = "Я готовий почути твою історію, Тіріоне.",
        ["npcs"] = { [1] = 1855 },
        ["roles"] = { ["reply"] = true },
    },
    [2683039352] = {
        ["english"] = { [1] = "Fine then, have a seat. This might take a while.$B$BWhen we first came to this frozen hell, General Arlos, down in Valiance Keep, gave my group of flying daredevils and I a special task: to establish a forward airbase for Alliance operations.$B$BThis airstrip is the result. Let me tell you, it wasn't easy, what with all the nasty beasts and the ground rock-hard from being frozen! But we managed, and we did it quickly too!" },
        ["text"] = "Гаразд, сідай. Це може затягнутися.$B$BКоли ми вперше прибули до цього крижаного пекла, генерал Арлос із фортеці Відчайдухів доручив мені та моїй групі повітряних шибайголів особливе завдання: створити передову авіабазу для операцій Альянсу.$B$BОсь результат — ця злітна смуга. І повір, було нелегко: навколо гидкі звірі, а земля промерзла й тверда, мов камінь! Та ми впоралися, ще й швидко!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2066103699] = {
        ["english"] = { [1] = "Greetings, $c.$B$BThe Horde currently control Wintergrasp Fortress, but the next battle starts soon.   Get ready to head to Wintergrasp and support our forces!$B$BThe next battle begins in $4354k." },
        ["text"] = "Вітаю, $c.$B$BОрда зараз контролює фортецю Зимохвату, але наступна битва скоро почнеться. Готуйся вирушати до Зимохвату й підтримати наші сили!$B$BНаступна битва почнеться через $4354k.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4230563085] = {
        ["english"] = { [1] = "Excellent day for a foray into the field wouldn't you say, $g sir : ma'am;?" },
        ["text"] = "Чудовий день для вилазки в поле, чи не так, $g пане : пані;?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [112796769] = {
        ["english"] = { [1] = "Elune be with you, $c." },
        ["text"] = "Нехай Елуна буде з тобою, $c.",
        ["npcs"] = { [1] = 3595, [2] = 3600, [3] = 4090, [4] = 4091, [5] = 4092, [6] = 11397, [7] = 11401 },
        ["roles"] = { ["greeting"] = true },
    },
    [217676874] = {
        ["english"] = { [1] = "How can I help you, stranger?" },
        ["text"] = "Чим можу допомогти, чужинцю?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4252044124] = {
        ["english"] = { [1] = "Hi there, $c! With the Ahn'Qiraj War drawing near, our preparations here are in full swing. I'm in charge of thick leather collections. It's a fine day for gathering thick leather, don't ya think? I got my stacks here and it looks like we've got $2069w right now. Our magic number is $2071w. Want to help out?" },
        ["text"] = "Привіт, $c! Війна в Ан'Кіражі наближається, тож підготовка тут у самому розпалі. Я відповідаю за збір товстої шкіри. Гарний день для збору товстої шкіри, еге ж? Ось мої стоси, і зараз у нас, схоже, $2069w. Магічне число — $2071w. Допоможеш?",
        ["npcs"] = { [1] = 15450 },
        ["roles"] = { ["greeting"] = true },
    },
    [699445427] = {
        ["english"] = { [1] = "Greetings, $c. I am Field Marshal Snowfall, commander of the war effort here. We've a hard road to plow ahead of us, $g lad : lass;, so if you can help out, please do so. And feel free to ask questions." },
        ["text"] = "Вітаю, $c. Я фельдмаршал Снігопад, командувач тутешніми воєнними діями. Попереду в нас важкий шлях, $g хлопче : дівчино;, тож якщо можеш допомогти — допомагай. І не соромся ставити запитання.",
        ["npcs"] = { [1] = 15701 },
        ["roles"] = { ["greeting"] = true },
    },
    [523867938] = {
        ["english"] = { [1] = "How many battles have we won?" },
        ["text"] = "Скільки битв ми виграли?",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["reply"] = true },
    },
    [3466541910] = {
        ["english"] = { [1] = "Greetings, $c.  Welcome to Cenarion Hold.  From here we will strike against the silithid where they're at their strongest.  I hope you've come to lend a hand." },
        ["text"] = "Вітаю, $c. Ласкаво просимо до Кенарійської цитаделі. Звідси ми вдаримо по силітидах там, де вони найсильніші. Сподіваюся, ти прийшов допомогти.",
        ["npcs"] = { [1] = 15191 },
        ["roles"] = { ["greeting"] = true },
    },
    [1632498155] = {
        ["english"] = { [1] = "Greetings, $c.$B$BThe Horde currently control Wintergrasp Fortress, but the battle has begun.  Hurry to Wintergrasp and support our forces!" },
        ["text"] = "Вітаю, $c.$B$BОрда зараз контролює фортецю Зимохвату, але битва вже почалася! Поспішай до Зимохвату й підтримай наші сили!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3153298485] = {
        ["english"] = { [1] = "Greetings, $c.  It is good you've decided to visit us." },
        ["text"] = "Вітаю, $c. Добре, що ви вирішили нас відвідати.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3121061365] = {
        ["english"] = { [1] = "Elune be praised!  You seek out our Warsong Gulch Battlemaster?  Her name is Aethalas, and she stands ready to greet you near the warrior trainers." },
        ["text"] = "Хвала Елуні! Шукаєш нашого воєначальника Ущелини Пісні Війни? Її звати Еталас, і вона чекає на тебе біля наставників воїнів.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [949835389] = {
        ["english"] = { [1] = "Elder Kilias can be found inside Drak'Tharon Keep." },
        ["text"] = "Старійшину Кіліаса можна знайти всередині твердині Драк'Тарон.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1044131985] = {
        ["english"] = { [1] = "I am ready, Oronok. Let us destroy Cyrukh and free the elements!" },
        ["text"] = "Я готовий, Ороноку. Знищімо Сіруха й визволімо стихії!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2440668160] = {
        ["english"] = { [1] = "Him name is Grizzle Halfmane.  He in Royal Quarter with Banshee Queen and Dread Lord.", [2] = "Him name is Grizzle Halfmane. He in Royal Quarter with Banshee Queen and Dread Lord." },
        ["text"] = "Його звати Ґріззл Півгриви. Він у Королівському кварталі з Королевою банші й Володарем жаху.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [414981322] = {
        ["english"] = { [1] = "Greetings, $c. Don't have too much time to talk--I'm just using Chillwind as a camp to get some rest before heading to Hearthglen. I've heard word that before they went crazy, the Scarlet Crusade had a mage working for them who was trying to create powerful bows and guns for their soldiers. I'm not sure if he succeeded or not... the Crusade killed him before any of his finished product made it out. Maybe they killed him to keep it a secret... or maybe they distrust the arcane that much." },
        ["text"] = "Вітаю, $c. Довго говорити не можу — використовую Студовій як табір, щоб перепочити перед дорогою до Гартґлена. Чув, що до того, як Багряний Похід збожеволів, на них працював маг, який намагався створювати для їхніх солдатів потужні луки й рушниці. Не знаю, чи встиг він завершити роботу... Похід убив його раніше, ніж будь-який готовий виріб покинув майстерню. Може, щоб зберегти таємницю... а може, вони настільки не довіряють аркані.",
        ["npcs"] = { [1] = 11609 },
        ["roles"] = { ["greeting"] = true },
    },
    [286988205] = {
        ["english"] = { [1] = "Eh, well you've made it this far... go see Lavinia Crowe by the other bookshelf there. If you don't mess things up with her, maybe you can learn some more." },
        ["text"] = "Ех, якщо вже зайшли так далеко... поговоріть із Лавінією Кроу біля іншої книжкової шафи. Якщо з нею не схибите, може, ще чогось навчитеся.",
        ["npcs"] = { [1] = 11067 },
        ["roles"] = { ["greeting"] = true },
    },
    [2631843334] = {
        ["english"] = { [1] = "Forget Vixton's spread. You want the good stuff? You talk to Krixel here. I got just what you need, provided you got the right rep. You know, in the arena. This stuff isn't for sissies, kid." },
        ["text"] = "Забудь про товар Вікстона. Хочеш справжню річ? Говори з Крикселем. У мене є саме те, що тобі треба — якщо репутація відповідна. Ну, знаєш, на арені. Це не для слабаків, малий.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [495090124] = {
        ["english"] = { [1] = "Greetings, $c. Before the night elves invited the draenei to join them here, this glade was all but forgotten.$B$BThe kaldorei are deeply tied to these lands, and we draenei are honored that they have asked us to share in the task of revitalizing Forest Song." },
        ["text"] = "Вітаю, $c. До того як нічні ельфи запросили дренеїв оселитися тут разом із ними, про цю галявину майже забули.$B$BКалдораї глибоко пов'язані з цими землями, і для нас, дренеїв, велика честь, що вони попросили нас долучитися до відродження Лісової Пісні.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3432185006] = {
        ["english"] = { [1] = "Greetings, $c!$b$bI hope you don't mind a little hard work. We could sure use a hand here." },
        ["text"] = "Вітаю, $c!$b$bСподіваюся, трохи важкої роботи тебе не лякає. Нам тут не завадила б допомога.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [885985399] = {
        ["english"] = { [1] = "Hehehe, how you doin' mon. You gonna help Pele'keiki great deal he be thinkin'. We be needin' a bombastic amount of the firebloom herb to be preparin' right for the Ahn'Qiraj War. The Horde, they say, 'Pele'keiki, you get us $2051w of the fire petals right quick'.$B$BPele'keiki tell you now, he only have $2050w firebloom, but you gonna add to that real soon, right mon?" },
        ["text"] = "Хе-хе-хе, як справи, мон? Пеле'кейкі думати, що ти дуже-дуже допомогти. Треба бомбезна купа вогнецвіту, щоб добре підготуватися до війни в Ан'Кіражі. Орда сказати: «Пеле'кейкі, швидко принеси нам $2051w вогняних пелюсток».$B$BПеле'кейкі казати тобі зараз: у нього лише $2050w вогнецвіту, але ти скоро це виправити, правда, мон?",
        ["npcs"] = { [1] = 15508 },
        ["roles"] = { ["greeting"] = true },
    },
    [2380991274] = {
        ["english"] = { [1] = "Greetings, $c - I'm a Commendation Officer acting on behalf of the Exodar.  It is my duty to assist adventurers who have received Alliance Commendation Signets.$B$BI accept signets in different quantities, but the most beneficial exchange for you is to hand in a set of ten at once.  I will enter your deeds into our records when you hand in your signets.  As a result, you will earn recognition from the Exodar for your duty and service." },
        ["text"] = "Вітаю, $c — я офіцер відзнак, що представляє Екзодар. Мій обов'язок — допомагати шукачам пригод, які отримали Печатки відзнаки Альянсу.$B$BЯ приймаю печатки в різній кількості, але найвигідніше для вас здавати по десять за раз. Коли ви передасте печатки, я внесу ваші заслуги до наших записів. За службу й відданість ви здобудете визнання Екзодара.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2432704113] = {
        ["english"] = { [1] = "How do I make my ram go faster?" },
        ["text"] = "Як змусити мого барана бігти швидше?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [471305362] = {
        ["english"] = { [1] = "Greetings traveler, you have my undying gratitude for dispensing with those dreadful creatures! I was beginning to think I might have to hide out forever!" },
        ["text"] = "Вітаю, мандрівнику! Моя вдячність за те, що ти позбувся тих жахливих створінь, безмежна! Я вже починав думати, що доведеться ховатися вічно!",
        ["npcs"] = { [1] = 11073 },
        ["roles"] = { ["greeting"] = true },
    },
    [2124414881] = {
        ["english"] = { [1] = "Don't let those big, innocent eyes fool ye. Tally's an expert, all right: I learn something new every day. Why d'you think I'm here in Tinker Town? Do I look like an engineer to you? Aye, I didn't think so." },
        ["text"] = "Не дай цим великим невинним очам себе обдурити. Таллі — справжня майстриня: я щодня дізнаюся від неї щось нове. Чому, гадаєш, я сиджу в Штукарівці? Я схожий на інженера? Ага, і я так думаю.",
        ["npcs"] = { [1] = 1246 },
        ["roles"] = { ["greeting"] = true },
    },
    [1258124160] = {
        ["english"] = { [1] = "Eraka no Kimbul$BGod of Tigers, Lord of Beasts, King of Cats, the Prey's Doom$B$BUeetay no Mueh'zala$BGod of Death, Father of Sleep, Son of Time, the Night's Friend." },
        ["text"] = "Ерака но Кімбул$BБог Тигрів, Володар Звірів, Король Котів, Загибель Здобичі$B$BУїтай но Муез'зала$BБог Смерті, Батько Сну, Син Часу, Друг Ночі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1267525531] = {
        ["english"] = { [1] = "Hail friend - a moment of your time, if I may...$B$BWe have endured much in our trials and tribulations in establishing Teldrassil.  Were the constant strife of the times not enough, we now find ourselves in a dire shortage of cloth.  If you have the materials to spare, I ask that you please donate them.  You certainly would earn the gratitude of night elves everywhere in helping us out!" },
        ["text"] = "Вітаю, друже — якщо можна, хвилинку вашого часу...$B$BМи пережили чимало випробувань, створюючи Тельдрассіль. Наче постійних чвар було мало, тепер нам ще й гостро бракує тканини. Якщо маєте зайві матеріали, прошу пожертвувати їх. Допомога принесе вам вдячність усіх нічних ельфів!",
        ["npcs"] = { [1] = 14725 },
        ["roles"] = { ["greeting"] = true },
    },
    [3060267560] = {
        ["english"] = { [1] = "Do your part in keeping the Scourge at bay, soldier! Report all suspicious activity and kill first, ask questions later!" },
        ["text"] = "Зроби свій внесок у стримування Скверни, солдате! Доповідай про всю підозрілу діяльність і спершу вбивай, а питання став потім!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4181975356] = {
        ["english"] = { [1] = "Greetings and salutations, hero!  I have the latest news from both continents and points beyond for your consideration." },
        ["text"] = "Вітаю, герою! У мене для вас найсвіжіші новини з обох континентів і далеких країв.",
        ["npcs"] = { [1] = 2198, [2] = 10877, [3] = 10878, [4] = 10879, [5] = 10880, [6] = 10881 },
        ["roles"] = { ["greeting"] = true },
    },
    [2693112619] = {
        ["english"] = { [1] = "Greetings and salutations from the manor Ravenholdt, adventurer." },
        ["text"] = "Вітання з маєтку Рейвенгольд, шукачу пригод.",
        ["npcs"] = { [1] = 16091 },
        ["roles"] = { ["greeting"] = true },
    },
    [3873428241] = {
        ["english"] = { [1] = "Greetings $R, I am Tharnariun Treetender." },
        ["text"] = "Вітаю, $R, я Тарнаріун Дереволюб.",
        ["npcs"] = { [1] = 3701 },
        ["roles"] = { ["greeting"] = true },
    },
    [3665670780] = {
        ["english"] = { [1] = "Good thing that you deactivated the moon crystal at An'owyn when you did, $c! Come around any time you feel like pitching in with my research here." },
        ["text"] = "Добре, що ти вчасно деактивував місячний кристал в Ан'овіні, $c! Заходь будь-коли, якщо захочеш допомогти з моїми дослідженнями.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3048343477] = {
        ["english"] = { [1] = "Got somethin' that needs tightening, $r?" },
        ["text"] = "Є щось, що треба підтягнути, $r?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1653238280] = {
        ["english"] = { [1] = "Greetings $N." },
        ["text"] = "Вітаю, $N.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2415829924] = {
        ["english"] = { [1] = "Fish? You gave a piece of what could be the key to saving all life on Kalimdor to a fish?" },
        ["text"] = "Риба? Ти віддав рибі частину того, що може бути ключем до порятунку всього життя на Калімдорі?",
        ["npcs"] = { [1] = 6109, [2] = 15481 },
        ["roles"] = { ["reply"] = true },
    },
    [3966758098] = {
        ["english"] = { [1] = "Don't be afraid of the sword, nubling. It's the mutton that gets ya!" },
        ["text"] = "Не бійся меча, нубику. Баранина — ось що тебе доконає!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1416634861] = {
        ["english"] = { [1] = "Go to Kodohide Leatherworkers in The Drag. Ask for Kamari." },
        ["text"] = "Іди до «Шкіряників Кодошкури» в Хитрому провулку. Питай Камарі.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1219325874] = {
        ["english"] = { [1] = "How long have you worked for the Cult of the Damned?" },
        ["text"] = "Як довго ти служиш Культу Проклятих?",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [508032952] = {
        ["english"] = { [1] = "Even as we speak, $c, all of the war materiel is being transported over to Silithus. By the looks of things, all of it should arrive in less than $2113w days. After that, a $g hero : heroine; will need to come along and ring the gong at the Scarab Dais. Then the war will begin in earnest." },
        ["text"] = "Поки ми говоримо, $c, усе військове спорядження перевозять до Силітусу. Схоже, воно все прибуде менш ніж за $2113w днів. Після цього має прийти $g герой : героїня; і вдарити в гонг біля Помосту Скарабея. Тоді війна почнеться по-справжньому.",
        ["npcs"] = { [1] = 15451 },
        ["roles"] = { ["greeting"] = true },
    },
    [2922760004] = {
        ["english"] = { [1] = "Hi there! We're being blockaded by those good-for-nothing pirates out in the bay! Do you think you can help us out by dropping a few bombs on them?!$B$BOur stolen zeppelin's here; hop on board before she sets sail!" },
        ["text"] = "Привіт! Ті нікчемні пірати в затоці взяли нас у блокаду! Допоможеш скинути на них кілька бомб?!$B$BНаш украдений дирижабль уже тут; застрибуй на борт, поки не відчалив!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3619962031] = {
        ["english"] = { [1] = "Good. In order to carry out my plan, we must first create a lifestone. Are you prepared to act?" },
        ["text"] = "Добре. Щоб здійснити мій план, спершу треба створити камінь життя. Готовий діяти?",
        ["npcs"] = { [1] = 11286 },
        ["roles"] = { ["greeting"] = true },
    },
    [3424205030] = {
        ["english"] = { [1] = "Good day, $gsir:ma'am;. I'd shake your hand, but as you see, I'm in the middle of something. May I be of assistance?" },
        ["text"] = "Добридень, $gпане:пані;. Я б потиснув вам руку, але, як бачите, зараз зайнятий. Чим можу допомогти?",
        ["npcs"] = { [1] = 1215 },
        ["roles"] = { ["greeting"] = true },
    },
    [3788817485] = {
        ["english"] = { [1] = "Hello, $r.  I'm sorry that you had to see our sacred land for the first time in such a state." },
        ["text"] = "Привіт, $r. Шкода, що тобі вперше довелося побачити нашу священну землю саме в такому стані.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1010405386] = {
        ["english"] = { [1] = "Good luck." },
        ["text"] = "Щасти.",
        ["npcs"] = { [1] = 15909 },
        ["roles"] = { ["reply"] = true },
    },
    [2266593487] = {
        ["english"] = { [1] = "Greetings, $c. I am Kuros, second of the Triumvirate of the Hand." },
        ["text"] = "Вітаю, $c. Я Курос, другий із Тріумвірату Десниці.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1452581135] = {
        ["english"] = { [1] = "Don't tell me! Shhh! You are here about the Ashbringer?!? Yes... Yes... No! My bad.$B$BWhat can I help you with, $r?" },
        ["text"] = "Не кажи! Тсс! Ти через Попелителя?!? Так... Так... Ні! Помилився.$B$BЧим можу допомогти, $r?",
        ["npcs"] = { [1] = 11811 },
        ["roles"] = { ["greeting"] = true },
    },
    [2521272408] = {
        ["english"] = { [1] = "Good work, soldier. I need to get back to base camp! Will you cover me?" },
        ["text"] = "Гарна робота, солдате. Мені треба повернутися до базового табору! Прикриєш мене?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1743539348] = {
        ["english"] = { [1] = "Good day to you.  When you've risen a bit more in the ranks of the Sha'tari Skyguard, I will be able offer you a direct flight to the Skyguard Outpost, our base atop the Blade's Edge Mountains." },
        ["text"] = "Добридень. Коли трохи підніметеся в лавах Небесної варти Ша'тар, я зможу запропонувати вам прямий переліт до застави Небесної варти — нашої бази на вершинах Лезокраїх гір.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1658494670] = {
        ["english"] = { [1] = "Get out of here, Tobias, you're free!" },
        ["text"] = "Іди звідси, Тобіасе, ти вільний!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [467474082] = {
        ["english"] = { [1] = "Engineering" },
        ["text"] = "Інженерія",
        ["npcs"] = { [1] = 68, [2] = 727, [3] = 1423, [4] = 1496, [5] = 1652, [6] = 1735, [7] = 1738, [8] = 1742, [9] = 1743, [10] = 1744, [11] = 1745, [12] = 1746, [13] = 1976, [14] = 2209, [15] = 2210, [16] = 2808, [17] = 3296, [18] = 5595, [19] = 5624, [20] = 5725, [21] = 5953, [22] = 6272, [23] = 6740, [24] = 8931, [25] = 12996, [26] = 13076, [27] = 274781 },
        ["roles"] = { ["reply"] = true },
    },
    [2276838773] = {
        ["english"] = { [1] = "Good day to you, $c.$b$bThere's much to be done to assist in the effort here. Sadly, there's very little I can do for you until I get all of my supplies.$b$bI've now got $3223w percent of the razorthorn roots I need to get started. Any assistance you provide will be well worth the effort, I assure you." },
        ["text"] = "Добридень, $c.$b$bТут ще багато роботи, щоб допомогти нашим зусиллям. На жаль, я мало що можу зробити для вас, доки не отримаю всі припаси.$b$bНаразі маю $3223w відсотків коренів гострошипу, потрібних для початку. Будь-яка ваша допомога буде варта зусиль, запевняю.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3721535807] = {
        ["english"] = { [1] = "Hm... yes, I do have a recipe you might find useful.  Let me teach you!" },
        ["text"] = "Гм... так, у мене є рецепт, який може стати тобі в пригоді. Дозволь навчити!",
        ["npcs"] = { [1] = 8696 },
        ["roles"] = { ["greeting"] = true },
    },
    [191819574] = {
        ["english"] = { [1] = "Elder Nightwind passes the days at the shrine in Jaedenar in Felwood." },
        ["text"] = "Старійшина Нічний Вітер проводить дні біля святилища в Джеденарі, що в Скверноліссі.",
        ["npcs"] = { [1] = 15574, [2] = 15600, [3] = 15601, [4] = 15605, [5] = 15606 },
        ["roles"] = { ["greeting"] = true },
    },
    [3478325341] = {
        ["english"] = { [1] = "Good day to ye $g lad : lass;. Can I be of service?" },
        ["text"] = "Добридень, $g хлопче : дівчино;. Чим можу прислужитися?",
        ["npcs"] = { [1] = 1241 },
        ["roles"] = { ["greeting"] = true },
    },
    [1298757293] = {
        ["english"] = { [1] = "Go to the Valley of Honor and seek out Xon'cha near the stables." },
        ["text"] = "Іди до Долини Честі й шукай Ксон'чу біля стаєнь.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [1194110988] = {
        ["english"] = { [1] = "Even now, free-willed undead battle the League of Arathor in Arathi Basin.  Will you aid the Defilers in defeating the humans and their Alliance allies?" },
        ["text"] = "Навіть зараз невмерлі зі свободою волі б'ються з Лігою Аратора в Низині Араті. Допоможеш Осквернителям перемогти людей та їхніх союзників з Альянсу?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [554599930] = {
        ["english"] = { [1] = "Elder Moonstrike can be found in the Scholomance in the Western Plaguelands." },
        ["text"] = "Старійшину Місячний Удар можна знайти в Некроситеті в Західному Чумнозем'ї.",
        ["npcs"] = { [1] = 15559, [2] = 15561, [3] = 15564, [4] = 15566, [5] = 15568, [6] = 15592, [7] = 15602 },
        ["roles"] = { ["greeting"] = true },
    },
    [470390222] = {
        ["english"] = { [1] = "Go to the Hunter's Hall in the Valley of Honor, west of the Coliseum.  Talk to Ormak Grimshot there." },
        ["text"] = "Іди до Зали Мисливців у Долині Честі, на захід від Колізею. Там поговори з Ормаком Похмурим Пострілом.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [862670853] = {
        ["english"] = { [1] = "Go to the Hunter Rise. You will find the battlemasters there." },
        ["text"] = "Іди до Мисливського верхів'я. Там знайдеш воєначальників.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [844058948] = {
        ["english"] = { [1] = "For a limited time only, Crunchy Frog available exclusively here at the Darkmoon Faire." },
        ["text"] = "Лише обмежений час — Хрумка Жаба, тільки тут, на ярмарку Темного Місяця.",
        ["npcs"] = { [1] = 14845 },
        ["roles"] = { ["greeting"] = true },
    },
    [1489703846] = {
        ["english"] = { [1] = "Garadar is in shambles, stranger. Since the Greatmother took ill, Garrosh has gone into a deep depression. He is most certainly not his father's boy.$B$B<Kurkush sighs.>$B" },
        ["text"] = "Ґарадар лежить у руїнах, чужинцю. Відколи Велика Матір занедужала, Ґаррош поринув у глибоку зневіру. Він точно не син свого батька.$B$B<Куркуш зітхає.>$B",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2784652980] = {
        ["english"] = { [1] = "Don't blame you for taking up fishing.  Mulgore has some the best fishing spots in Southern Kalimdor and Mountaintop Bait & Tackle on the high rise has all of the gear you'll need to take advantage of it.\010\010Tell Kah Mistrunner that I sent ya!" },
        ["text"] = "Не дивуюся, що ви взялися за рибальство. У Мулґорі є одні з найкращих рибних місць Південного Калімдору, а в «Гірській наживці та снастях» на верхньому ярусі знайдеться все спорядження, яке вам знадобиться.\010\010Скажіть Ка Містраннер, що це я вас послав!",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [2087106109] = {
        ["english"] = { [1] = "Greed has led you back to me.$B$B<Mathredis laughs.>$B$BA wise Draenei once told me that it - greed - is the single quality that all of the races on this world share. I would have to agree.$B$BHave you collected the components listed within the libram?" },
        ["text"] = "Жадібність привела тебе назад до мене.$B$B<Матредіс сміється.>$B$BОдин мудрий дреней якось сказав мені, що жадібність — єдина риса, спільна для всіх рас цього світу. І я згоден.$B$BТи зібрав складники, перелічені в лібрамі?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1919323914] = {
        ["english"] = { [1] = "Go see Una at Thunder Bluff Armorers then.  It can be found on the middle rise." },
        ["text"] = "Тоді йди до Уни в «Зброярі Громового Бескиду». Вони на середньому ярусі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [56921854] = {
        ["english"] = { [1] = "Go Forsaken!  Yay us!" },
        ["text"] = "Уперед, Відречені! Ура нам!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2913445615] = {
        ["english"] = { [1] = "I am interested in warlock training." },
        ["text"] = "Мене цікавить навчання чорнокнижництву.",
        ["npcs"] = { [1] = 459, [2] = 460, [3] = 461, [4] = 906, [5] = 3156, [6] = 3172, [7] = 3324, [8] = 3325, [9] = 3326, [10] = 4563, [11] = 4564, [12] = 5171, [13] = 5172, [14] = 5173, [15] = 5495, [16] = 5496, [17] = 5612 },
        ["roles"] = { ["reply"] = true },
    },
    [3262264064] = {
        ["english"] = { [1] = "Greetings, $N, and welcome to Camp Narache. News of your arrival spread quickly among the tribe." },
        ["text"] = "Вітаю, $N, і ласкаво просимо до табору Нараче. Звістка про твоє прибуття швидко розійшлася плем'ям.",
        ["npcs"] = { [1] = 2980 },
        ["roles"] = { ["greeting"] = true },
    },
    [2281661873] = {
        ["english"] = { [1] = "Gnomeregan can be found in western Dun Morogh." },
        ["text"] = "Ґномреґан розташований у західній частині Дун-Морогу.",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [436675663] = {
        ["english"] = { [1] = "Greetings, $c.$B$BThe Alliance currently control Wintergrasp Fortress.  When the battle is about to begin, talk to me to enter the battle.$B$BThe next battle begins in $4354k." },
        ["text"] = "Вітаю, $c.$B$BАльянс зараз контролює фортецю Зимохвату. Коли битва буде от-от починатися, поговори зі мною, щоб вступити в бій.$B$BНаступна битва почнеться через $4354k.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3840643155] = {
        ["english"] = { [1] = "Gloom'rel, tell me your secrets!" },
        ["text"] = "Ґлум'рел, розкажи мені свої таємниці!",
        ["npcs"] = { [1] = 9037 },
        ["roles"] = { ["reply"] = true },
    },
    [3481732350] = {
        ["english"] = { [1] = "Gri'lek, of the Iron Blood$B$BThe wanderer.  May his strength and lust for battle pierce the ages.$B$BGri'lek now lingers near the edge of madness..." },
        ["text"] = "Ґрі'лек, із Залізної Крові$B$BМандрівник. Нехай його сила й жага битви пройдуть крізь віки.$B$BНині Ґрі'лек блукає біля межі божевілля...",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [606351380] = {
        ["english"] = { [1] = "Glacial Wrists." },
        ["text"] = "Льодовикові наручі.",
        ["npcs"] = { [1] = 16365 },
        ["roles"] = { ["reply"] = true },
    },
    [2315401868] = {
        ["english"] = { [1] = "Do you seek further training in the ways of the warrior?" },
        ["text"] = "Бажаєте продовжити навчання військовому ремеслу?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1963515444] = {
        ["english"] = { [1] = "Greetings, young $c." },
        ["text"] = "Вітаю, юний $c.",
        ["npcs"] = { [1] = 3144 },
        ["roles"] = { ["greeting"] = true },
    },
    [36356313] = {
        ["english"] = { [1] = "Get out of my face, kid! Can't you see that I'm training? That's right, yours truly is going to be the next Warmaul champion.$B$BYep, I'm almost ready for the Ring of Blood up north in the old Laughing Skull Ruins. But don't even think about it, kid. You're way too weak. Gurgthock, the ring announcer, wouldn't even let you peek inside that ring let alone fight in it.$B$BNow beat it before it beats you." },
        ["text"] = "Геть з очей, малий! Не бачиш, я тренуюся? Саме так, перед тобою майбутній чемпіон Бойового Молота.$B$BАга, я вже майже готовий до Кола Крові на півночі, в старих руїнах Сміхотливого Черепа. Але навіть не думай туди потикатися, малий. Ти надто слабкий. Ґурґток, розпорядник арени, не дозволить тобі навіть зазирнути всередину, не те що битися.$B$BА тепер зникай, поки сам не дістав прочухана.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1164733517] = {
        ["english"] = { [1] = "E'ko is da unfocused form of the supernatural power, and Juju is da concentrated essence. By using a stong incantation, I can transform da E'ko into Juju.  Once it becomes Juju, you can den use the Cache of Mau'ari ta reflect da powers onto yourself." },
        ["text"] = "Е'ко — то розсіяна форма надприродної сили, а джуджу — її згущена сутність. Сильним закляттям я можу перетворити е'ко на джуджу. А тоді Сховком Мау'арі ти зможеш відбити цю силу на себе.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [559117114] = {
        ["english"] = { [1] = "Get lost before I beat you with my booterang." },
        ["text"] = "Забирайся, поки я не відлупцював тебе своїм чоботарангом.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4070265280] = {
        ["english"] = { [1] = "I am Hydraxis, Duke of the Waterlords.  You are not an elemental and so cannot understand our struggle, but perhaps we can strike a deal that will benefit us both..." },
        ["text"] = "Я Гідраксіс, герцог Володарів Води. Ти не елементаль і тому не можеш зрозуміти нашої боротьби, але, можливо, ми укладемо угоду, вигідну нам обом...",
        ["npcs"] = { [1] = 13278 },
        ["roles"] = { ["greeting"] = true },
    },
    [2912464571] = {
        ["english"] = { [1] = "Elder Silvervein can be found near Thelsamar in Loch Modan." },
        ["text"] = "Старійшину Срібна Жила можна знайти поблизу Телсамара в Лох-Модані.",
        ["npcs"] = { [1] = 15567, [2] = 15569 },
        ["roles"] = { ["greeting"] = true },
    },
    [1770826404] = {
        ["english"] = { [1] = "Get away from me, nasty Scourge!" },
        ["text"] = "Відійди від мене, гидка Скверно!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2426671680] = {
        ["english"] = { [1] = "Get away from here, $c, or they'll put you in chains as well." },
        ["text"] = "Геть звідси, $c, або й тебе закують у ланцюги.",
        ["npcs"] = { [1] = 2238 },
        ["roles"] = { ["greeting"] = true },
    },
    [185525084] = {
        ["english"] = { [1] = "Every scrap used makes us less wasteful and brings us closer to the Earth Mother.  Mooranta can show you the way.  Seek her just outside the Thunder Bluff Armorers on the middle rise." },
        ["text"] = "Кожен використаний клапоть означає менше марнотратства й наближає нас до Матері-Землі. Муранта покаже тобі шлях. Шукай її просто біля «Зброярів Громового Бескиду» на середньому ярусі.",
        ["npcs"] = { [1] = 3084 },
        ["roles"] = { ["greeting"] = true },
    },
    [573151038] = {
        ["english"] = { [1] = "Hello, my child." },
        ["text"] = "Привіт, дитя моє.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3565952884] = {
        ["english"] = { [1] = "Go to the Great Forge at the very center of Ironforge. He works there, alongside the other Masters of our kind." },
        ["text"] = "Іди до Великої Кузні в самому центрі Залізогарта. Він працює там разом з іншими майстрами нашого ремесла.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2584740380] = {
        ["english"] = { [1] = "From this dock, The Bravery travels back and forth between Stormwind and Auberdine." },
        ["text"] = "Від цього причалу «Відвага» курсує між Штормовієм та Аубердіном.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1847422347] = {
        ["english"] = { [1] = "Elder Bellowrage watches over the Dark Portal from a ridge in the Blasted Lands." },
        ["text"] = "Старійшина Револють стежить за Темним порталом із кряжа в Спустошених землях.",
        ["npcs"] = { [1] = 15593 },
        ["roles"] = { ["greeting"] = true },
    },
    [3064420999] = {
        ["english"] = { [1] = "How do I train my pet?" },
        ["text"] = "Як навчати мого вихованця?",
        ["npcs"] = { [1] = 543, [2] = 2878, [3] = 2879, [4] = 3306, [5] = 3545, [6] = 3620, [7] = 3622, [8] = 3624, [9] = 3688, [10] = 3698, [11] = 4320, [12] = 10086, [13] = 10088, [14] = 10089, [15] = 10090 },
        ["roles"] = { ["reply"] = true },
    },
    [4003005086] = {
        ["english"] = { [1] = "Expire? Me? Heh, not hardly, kid. That was just a scratch." },
        ["text"] = "Померти? Я? Хех, навряд чи, малий. Це була лише подряпина.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2245005162] = {
        ["english"] = { [1] = "Hi $N!  Are you here to buy something?  Or maybe sell something?$B$BYou won't find better prices anywhere, or my name isn't Augustus the Touched!" },
        ["text"] = "Привіт, $N! Прийшов щось купити? А може, продати?$B$BКращих цін ніде не знайдеш, або я не Авґуст Торкнутий!",
        ["npcs"] = { [1] = 12384 },
        ["roles"] = { ["greeting"] = true },
    },
    [3489970588] = {
        ["english"] = { [1] = "Hail, adventurer. I am Rin'wosho, trader of Zuldazar. I come from the South Seas and bring many exotic goods and items from my homeland.$B$BPerhaps if you prove your worth to my tribe, I shall barter.  If you have any of my tribe's Honor Tokens, then perhaps we shall barter even more." },
        ["text"] = "Вітаю, шукачу пригод. Я Рін'вошо, торговець із Зулдазара. Я прибув із Південних морів і привіз чимало екзотичних товарів із батьківщини.$B$BМожливо, якщо доведеш свою цінність моєму племені, я торгуватиму з тобою. А якщо маєш Жетони честі мого племені — тим більше.",
        ["npcs"] = { [1] = 14921 },
        ["roles"] = { ["greeting"] = true },
    },
    [440677661] = {
        ["english"] = { [1] = "Earthen Templar! I hold your signet! Heed my call!" },
        ["text"] = "Земляний храмовнику! Я тримаю твою печатку! Почуй мій поклик!",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3002470420] = {
        ["english"] = { [1] = "Forgive me $c, but I must concentrate on my job." },
        ["text"] = "Пробачте, $c, але я мушу зосередитися на роботі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [516133332] = {
        ["english"] = { [1] = "Forgetting your skill in Elixir Mastery is not something to do lightly.\013\010\013\010Are you absolutely sure?" },
        ["text"] = "Відмова від майстерності еліксирів — серйозний крок.\013\010\013\010Ти цілком упевнений?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1022748296] = {
        ["english"] = { [1] = "Fhwoor like little sporelings.  They save Fhwoor.  Not eat them.$B$BFhwoor hate naga.  Fhwoor smash!" },
        ["text"] = "Фхвуур любити маленькі спорлінґи. Вони рятувати Фхвуур. Не їсти їх.$B$BФхвуур ненавидіти наґ. Фхвуур трощити!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [4274100747] = {
        ["english"] = { [1] = "Forgetting elemental leatherworking is not something to do lightly.  If you choose to abandon it you will forget all recipes that require elemental leatherworking as well!" },
        ["text"] = "Відмова від стихійного шкірництва — серйозний крок. Якщо відмовишся, забудеш усі рецепти, що потребують стихійного шкірництва!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3218633970] = {
        ["english"] = { [1] = "For the time being, that area is free of Scourge influence. I fear it will only be a matter of time before they return." },
        ["text"] = "Поки що ця місцевість вільна від впливу Скверни. Боюся, лише питання часу, коли вони повернуться.",
        ["npcs"] = { [1] = 16285, [2] = 16359 },
        ["roles"] = { ["greeting"] = true },
    },
    [2638171691] = {
        ["english"] = { [1] = "Go to the Hall of the Brave.  You will find The Defiler, Deze Snowbane there to assist you in getting to Arathi Basin." },
        ["text"] = "Іди до Зали Відважних. Там знайдеш Осквернителя Дезе Снігогуба, який допоможе тобі дістатися Низини Араті.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3282964500] = {
        ["english"] = { [1] = "Elder Chogan'gada can be found in Utgarde Pinnacle." },
        ["text"] = "Старійшину Чоґан'ґада можна знайти на вершині Утґард.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1595616025] = {
        ["english"] = { [1] = "I am 100% confident that I wish to learn in the ways of gnomish engineering." },
        ["text"] = "Я на 100% упевнений, що хочу вивчати гномську інженерію.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [3893148197] = {
        ["english"] = { [1] = "Freedom! Kraz life was over.$b$bI thank you, $c." },
        ["text"] = "Свобода! Життя Краза вже було скінчено.$b$bДякую тобі, $c.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1484748402] = {
        ["english"] = { [1] = "Greetings $c.  Do you wish to aid the Silverwing Sentinels in their fight at Warsong Gulch?" },
        ["text"] = "Вітаю, $c. Бажаєте допомогти Срібнокрилим вартовим у їхній боротьбі в Ущелині Пісні Війни?",
        ["npcs"] = { [1] = 2302 },
        ["roles"] = { ["greeting"] = true },
    },
    [2953917577] = {
        ["english"] = { [1] = "I am Skaltesh, guide to the shaman seeking enlightenment here... but even those who follow different paths can be shown a thing or two. Do you wish to see?" },
        ["text"] = "Я Скалтіш, провідник шаманів, що шукають тут просвітлення... але й тим, хто йде іншими шляхами, можна дещо показати. Хочеш побачити?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [150662288] = {
        ["english"] = { [1] = "Hello there $glad:lass;... the name's Oglethorpe and I may be responsible for one of the amazing gnomish devices you might possess!  If it blew up, then it wasn't me; if it made you rich though, we can discuss royalties!$B$BOh, and if you're from Gnomeregan, you can just take two ninety degree angles, smash them together, and start marching.  I have nothing to say to you." },
        ["text"] = "Привіт, $gхлопче:дівчино;... мене звати Оґлторп, і цілком можливо, що я відповідальний за один із дивовижних гномських пристроїв, які в тебе є! Якщо він вибухнув — це не я; а якщо зробив тебе багатим — можемо обговорити відсотки!$B$BО, і якщо ти з Ґномреґана, можеш узяти два прямі кути, скласти їх докупи й маршувати звідси. Мені нічого тобі сказати.",
        ["npcs"] = { [1] = 7406 },
        ["roles"] = { ["greeting"] = true },
    },
    [2062468218] = {
        ["english"] = { [1] = "Greetings, $c. I am Rexxar, champion of the Horde, servant of Thrall, master to the beasts of the wilds." },
        ["text"] = "Вітаю, $c. Я Рексар, чемпіон Орди, слуга Тралла, володар звірів дикої природи.",
        ["npcs"] = { [1] = 10182 },
        ["roles"] = { ["greeting"] = true },
    },
    [4207219548] = {
        ["english"] = { [1] = "Fine beasts, aren't they? The wyverns we raise here are trained to handle the fiercest and strangest weather conditions Draenor has to offer. You'll find them dependable and hardy." },
        ["text"] = "Гарні звірі, хіба ні? Виверн, яких ми тут вирощуємо, навчають витримувати найжорстокішу й найдивнішу погоду Дренору. На них можна покластися — вони витривалі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [455390777] = {
        ["english"] = { [1] = "Find the Hall of the Brave in the Valley of Honor and speak to Grezz Ragefist.  Let them know that I'll be reporting back in after my shift here." },
        ["text"] = "Знайди Залу Відважних у Долині Честі й поговори з Ґреззом Лютокулаком. Скажи, що я повернуся після зміни.",
        ["npcs"] = { [1] = 3296 },
        ["roles"] = { ["greeting"] = true },
    },
    [3888452634] = {
        ["english"] = { [1] = "Finlay, let me see what you have for sale." },
        ["text"] = "Фінлею, покажи, що маєш на продаж.",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [273403879] = {
        ["english"] = { [1] = "Greetings, $N. I am Doctor Gregory Victor, head trauma surgeon of Horde Trauma." },
        ["text"] = "Вітаю, $N. Я доктор Ґреґорі Віктор, головний хірург травматології Орди.",
        ["npcs"] = { [1] = 12920 },
        ["roles"] = { ["greeting"] = true },
    },
    [1959393812] = {
        ["english"] = { [1] = "Here for the rod? Or, maybe you're simply stocking up on runes?$B$BWait a minute! Are you just trying to offload a whole bunch of junk on me?! Curse my never-ending compulsion to buy, buy, buy!" },
        ["text"] = "Прийшов по жезл? А може, просто запасаєшся рунами?$B$BСтривай-но! Ти що, просто намагаєшся спихнути мені купу мотлоху?! Проклята моя невгамовна жага купувати, купувати, купувати!",
        ["npcs"] = { [1] = 16015 },
        ["roles"] = { ["greeting"] = true },
    },
    [2241967896] = {
        ["english"] = { [1] = "Greetings, $c. Our position here is a bit exposed given the build up of the Horde's forces to the south.$B$BAnything that you can do to help will be greatly appreciated." },
        ["text"] = "Вітаю, $c. Наша позиція тут трохи відкрита, зважаючи на нарощування сил Орди на півдні.$B$BБудемо дуже вдячні за будь-яку допомогу.",
        ["npcs"] = { [1] = 3845 },
        ["roles"] = { ["greeting"] = true },
    },
    [3260306086] = {
        ["english"] = { [1] = "I beg you, $r, be swift. They will not stop pursuing me! I cannot escape from them, even here!" },
        ["text"] = "Благаю, $r, поспішай. Вони не припинять переслідувати мене! Я не можу втекти від них навіть тут!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1053322715] = {
        ["english"] = { [1] = "Hey there!  Just because I can race rams better than anyone else, doesn't mean I won't pitch in and help out the brewers.  You can help out if you like.$b$bBut wait, there's more!$b$bHelping out with Brewfest means you get a chance to ride some of the fastest rams in the realms!" },
        ["text"] = "Привіт! Те, що я найкраще за всіх ганяю на баранах, не означає, що я не допомагаю пивоварам. І ти можеш долучитися.$b$bАле це ще не все!$b$bДопомога на Хмільному фестивалі дає шанс покататися на одних із найшвидших баранів у всіх світах!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3939874758] = {
        ["english"] = { [1] = "Elder Morningdew has taken to watching the commotion at the Mirage Raceway in Thousand Needles." },
        ["text"] = "Старійшина Ранкова Роса спостерігає за метушнею на Міражній гоночній трасі в Тисячі Шипів.",
        ["npcs"] = { [1] = 15581, [2] = 15582, [3] = 15584, [4] = 15587, [5] = 15588, [6] = 15597 },
        ["roles"] = { ["greeting"] = true },
    },
    [4270620994] = {
        ["english"] = { [1] = "Excellent, you have proven yourself worthy! Now for the next phase of your instruction..." },
        ["text"] = "Чудово, ти довів, що гідний! Тепер наступний етап навчання...",
        ["npcs"] = { [1] = 5174 },
        ["roles"] = { ["greeting"] = true },
    },
    [859538897] = {
        ["english"] = { [1] = "Elder Highpeak watches over the Hinterlands from a hill near its center." },
        ["text"] = "Старійшина Високий Пік споглядає Внутрішні землі з пагорба поблизу їхнього центру.",
        ["npcs"] = { [1] = 15561, [2] = 15594 },
        ["roles"] = { ["greeting"] = true },
    },
    [1646565914] = {
        ["english"] = { [1] = "Excellent! I've been hopin' for a new student. Well, let's get started right away then!" },
        ["text"] = "Чудово! Я давно сподівався на нового учня. Ну що ж, тоді почнімо негайно!",
        ["npcs"] = { [1] = 1703 },
        ["roles"] = { ["greeting"] = true },
    },
    [4029173455] = {
        ["english"] = { [1] = "Ezekiel said that you might have a certain book..." },
        ["text"] = "Єзекіїль сказав, що у вас може бути певна книга...",
        ["npcs"] = {},
        ["roles"] = { ["reply"] = true },
    },
    [2074791290] = {
        ["english"] = { [1] = "Fine, but be more careful with it this time!" },
        ["text"] = "Гаразд, але цього разу будь із ним обережнішим!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [187579305] = {
        ["english"] = { [1] = "Greetings, $c. It is good to see you interested in helping with the war effort. The collectors here are organizing the gathering of various stockpiles of goods so that we will be prepared when the time comes.$B$BI am in charge of obtaining $2106w baked salmon to store away for those involved in the fighting at Ahn'Qiraj. The last time that I counted, we had collected $2105w." },
        ["text"] = "Вітаю, $c. Радий бачити, що ти хочеш допомогти підготовці до війни. Збирачі тут організовують накопичення різних запасів, щоб ми були готові, коли настане час.$B$BЯ відповідаю за заготівлю $2106w запечених лососів для тих, хто битиметься в Ан'Кіражі. Востаннє, коли я рахував, ми зібрали $2105w.",
        ["npcs"] = { [1] = 15535 },
        ["roles"] = { ["greeting"] = true },
    },
    [4031636582] = {
        ["english"] = { [1] = "Ever since the shadows claimed Duskwood I haven't been able to sleep. I am kept awake by the ghostly sounds of screaming on the breeze. It sounds almost like lambs screaming, and they won't stop." },
        ["text"] = "Відколи тіні поглинули Смерколісся, я не можу заснути. Мене не дають спати примарні крики, що лунають на вітрі. Майже як крики ягнят — і вони не стихають.",
        ["npcs"] = { [1] = 3136 },
        ["roles"] = { ["greeting"] = true },
    },
    [4280984867] = {
        ["english"] = { [1] = "Even slight alterations to a potion's ingredients can change it fundamentally. Patience and precision, young one: they will serve you well in all walks of life." },
        ["text"] = "Навіть незначна зміна складників зілля може докорінно його змінити. Терпіння й точність, юначе: вони стануть у пригоді в усьому житті.",
        ["npcs"] = { [1] = 11042 },
        ["roles"] = { ["greeting"] = true },
    },
    [2770288074] = {
        ["english"] = { [1] = "Go find those hidden plagued grain crates and use your Arcane Disruptor on them! Arthas will then have the evidence he needs to begin the culling of Stratholme." },
        ["text"] = "Знайди приховані ящики із зараженим зерном і застосуй до них Арканічний руйнівник! Тоді Артас матиме докази, потрібні для початку очищення Стратгольма.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3503497750] = {
        ["english"] = { [1] = "Hungry? Can sleep here, too." },
        ["text"] = "Голодний? Тут і поспати можна.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [760595369] = {
        ["english"] = { [1] = "Greetings, $c.$B$BWhen the Horde controls Wintergrasp Fortress, I will open a portal for those who wish to travel there.$B$BThe next battle begins in $3975w:$3976w$3782w:$3784w$3785w." },
        ["text"] = "Вітаю, $c.$B$BКоли Орда контролює фортецю Зимохвату, я відкриваю портал для всіх, хто хоче туди вирушити.$B$BНаступна битва почнеться через $3975w:$3976w$3782w:$3784w$3785w.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1992873796] = {
        ["english"] = { [1] = "Enemies are closing in on us from all sides, and all the elders talk of abandoning this post. I say we should stand and fight like the warriors we are." },
        ["text"] = "Вороги насідають з усіх боків, а всі старійшини говорять про покидання цієї застави. А я кажу — треба стояти й битися, як воїни.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1593463660] = {
        ["english"] = { [1] = "Elune's grace upon you.  How can I serve?" },
        ["text"] = "Нехай благодать Елуни буде з вами. Чим можу служити?",
        ["npcs"] = { [1] = 4161 },
        ["roles"] = { ["greeting"] = true },
    },
    [2147092917] = {
        ["english"] = { [1] = "Enchanting has run in our family for generations. I learned at an early age, just as my son is doing now." },
        ["text"] = "У нашій родині зачаруванням займаються поколіннями. Я почав учитися змалку, як тепер мій син.",
        ["npcs"] = { [1] = 3011 },
        ["roles"] = { ["greeting"] = true },
    },
    [3392546244] = {
        ["english"] = { [1] = "Greetings, soldier. Are you here to help the cause?" },
        ["text"] = "Вітаю, солдате. Прийшов допомогти справі?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3022146589] = {
        ["english"] = { [1] = "Greetings, $c.$B$BThe Alliance now controls Wintergrasp Fortress. Use the portal, if you like.$B$BThe next battle begins in $3975w:$3976w$3782w:$3784w$3785w." },
        ["text"] = "Вітаю, $c.$B$BАльянс зараз контролює фортецю Зимохвату. Можеш скористатися порталом.$B$BНаступна битва почнеться через $3975w:$3976w$3782w:$3784w$3785w.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2898077248] = {
        ["english"] = { [1] = "Elder Windtotem is keeping company with the goblins of Ratchet on the coast of the Barrens." },
        ["text"] = "Старійшина Вітрототем водиться з гоблінами Кабестана на узбережжі Степів.",
        ["npcs"] = { [1] = 15572, [2] = 15575, [3] = 15579, [4] = 15580, [5] = 15588, [6] = 15597, [7] = 15604 },
        ["roles"] = { ["greeting"] = true },
    },
    [1224340239] = {
        ["english"] = { [1] = "Elder Skywarden can be found near Agmar's Hammer in Dragonblight." },
        ["text"] = "Старійшину Небесний Вартовий можна знайти біля Молота Аґмара на Драконовому кладовищі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1627348495] = {
        ["english"] = { [1] = "Ever trip over own feet? We have. Kind of hurt. No do it, not fun. Nope." },
        ["text"] = "Колись перечіплявся через власні ноги? Ми — так. Було боляче. Не роби так, не весело. Нє.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3578272922] = {
        ["english"] = { [1] = "Eager to get to Northrend, are you? The steam-powered Kraken sails from here to Valiance Keep in Borean Tundra." },
        ["text"] = "Кортить до Нортренду, еге ж? Паровий «Кракен» ходить звідси до фортеці Відчайдухів у Борейській тундрі.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2857957140] = {
        ["english"] = { [1] = "Greetings, friend.  Something I can do for ya?" },
        ["text"] = "Вітаю, друже. Чим можу допомогти?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [1537656421] = {
        ["english"] = { [1] = "Elder Farwhisper can be found wandering the streets of Stratholme." },
        ["text"] = "Старійшину Далекошепота можна зустріти на вулицях Стратгольма.",
        ["npcs"] = { [1] = 15566, [2] = 15592 },
        ["roles"] = { ["greeting"] = true },
    },
    [2403705245] = {
        ["english"] = { [1] = "Hmm... something familiar about your face $r...  Give me a moment...$B$BAh ha! Westfall, that's where I recognize you from.  You are $n!  It's good to see you again.  But, let's hope you can help us finish the job this time.$B$BNow we're a long way from Westfall up here, but if we don't win this battle, there may not be a home to return to." },
        ["text"] = "Гм... твоє обличчя мені знайоме, $r... дай подумати...$B$BАга! Західний край, ось звідки. Ти ж $n! Радий знову бачити. Сподіваймося, цього разу ти допоможеш довести справу до кінця.$B$BМи далеко від Західного краю, але якщо не виграємо цю битву, може не лишитися дому, куди повертатися.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2464924635] = {
        ["english"] = { [1] = "Hey!  Are you on an errand for Tirth?  If I were you I'd get as far away from him as I could!  His mind's been pickled from too much drink but his magic's as strong as ever!" },
        ["text"] = "Гей! Ти з дорученням від Тірта? На твоєму місці я тримався б від нього якнайдалі! Від випивки мозок у нього давно вимок, але магія досі сильна!",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [2680698699] = {
        ["english"] = { [1] = "During the War of the Ancients, the demigod Agamaggan came forth to battle the Burning Legion. The colossal boar was defeated, and over time in the areas where his blood fell, massive thorn-ridden vines sprouted to life. The quilboar came to occupy these regions and hold them sacred. The heart of these massive thorn-colonies is the Razorfen. Razorfen Kraul was conquered by the crone, Charlga Razorflank, who some speculate has been negotiating with agents of the Scourge for some insidious purpose.\010" },
        ["text"] = "Під час Війни Предків напівбог Аґамаґґан виступив проти Палаючого Легіону. Велетенського вепра було вбито, а згодом у місцях, де пролилася його кров, проросли величезні лози, вкриті колючками. Кіллборани оселилися в цих краях і вважають їх священними. Серце цих велетенських колоній колючок — Бритвоболото. Крааль Бритвоболотих захопила стара Шарлґа Бритвобока, яка, за чутками, веде переговори з агентами Скверни заради якоїсь лихої мети.\010",
        ["npcs"] = { [1] = 295, [2] = 1247, [3] = 1464, [4] = 2352, [5] = 2388, [6] = 2808, [7] = 3934, [8] = 5111, [9] = 5688, [10] = 5814, [11] = 6272, [12] = 6727, [13] = 6734, [14] = 6735, [15] = 6736, [16] = 6737, [17] = 6738, [18] = 6739, [19] = 6740, [20] = 6741, [21] = 6746, [22] = 6747, [23] = 6790, [24] = 6791, [25] = 6807, [26] = 6928, [27] = 6929, [28] = 6930, [29] = 7714, [30] = 7731, [31] = 7733, [32] = 7736, [33] = 7737, [34] = 7744, [35] = 8931, [36] = 9356, [37] = 9501, [38] = 11103, [39] = 11106, [40] = 11116, [41] = 11118, [42] = 12196, [43] = 14731, [44] = 16458 },
        ["roles"] = { ["greeting"] = true },
    },
    [1768294199] = {
        ["english"] = { [1] = "Drink from this vial, and the fog will be cleared for a short time. Go with the spirits, my friend." },
        ["text"] = "Випий із цього флакона — і туман на короткий час розвіється. Нехай духи ведуть тебе, друже.",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
    [3594865322] = {
        ["english"] = { [1] = "Draenei forces and their Alliance allies are engaged with the Horde in the Eye of the Storm in Outland. Will you join them in an effort to turn the tide of battle in our favor?" },
        ["text"] = "Сили дренеїв та їхні союзники з Альянсу б'ються з Ордою в Оці Бурі в Позамежжі. Приєднаєтеся до них, щоб схилити хід битви на нашу користь?",
        ["npcs"] = {},
        ["roles"] = { ["greeting"] = true },
    },
}
